// Reviewed German tool-page explanations and FAQs; code and security limits are preserved.
export const dePageCopy: Record<string, string> = {
  "pageText.494b4551": "Bleiben meine Daten privat?",
  "pageText.62172ab3": "Ja, die Ausführung erfolgt vollständig clientseitig in Ihrem Browser.",
  "pageText.f60263be": "Was ist JSON?",
  "pageText.b285e12f": "JSON (JavaScript Object Notation) ist ein leichtgewichtiges Datenaustauschformat, das Menschen leicht lesen und schreiben und Maschinen leicht parsen und erzeugen können.",
  "pageText.5fb110d7": "Wie formatiere ich JSON?",
  "pageText.3241bbe1": "Gültiges JSON in das Eingabefeld einfügen, die gewünschten Optionen für Einrückung und Schlüsselsortierung wählen und anschließend „JSON formatieren“ auswählen.",
  "pageText.fd4a654d": "Sind meine Daten sicher?",
  "pageText.542fb6d3": "Ja! Die gesamte Verarbeitung erfolgt in Ihrem Browser. Ihre Daten verlassen Ihren Computer nicht.",
  "pageText.d16ff7e1": "Was der JSON-Formatierer macht",
  "pageText.647c3353": "Ein JSON-Formatierer parst JSON-Text und serialisiert den resultierenden Wert mit einheitlichem Leerraum. Dieses Tool kann mit der gewählten Einrückung formatieren, das Ergebnis minimieren und optional Objektschlüssel rekursiv sortieren. RFC 8259 verlangt doppelte Anführungszeichen für Objektnamen und Zeichenfolgen; Kommentare, abschließende Kommas, NaN und Infinity gehören nicht zur JSON-Grammatik. Die Formatierung ändert die Darstellung, nicht die beabsichtigte Bedeutung der Daten.",
  "pageText.c80fe1c6": "Typische Anwendungen und Grenzen der Validierung",
  "pageText.b49ba2b3": "Verwenden Sie den Formatierer, wenn Sie während der Entwicklung JSON untersuchen oder vereinheitlichen möchten:",
  "pageText.92e09088": "Kompakte API-Antworten, Webhook-Bodys, Konfigurationen oder Protokolleinträge lesbarer machen.",
  "pageText.a1f30e1f": "Gültiges JSON minimieren, bevor es in eine Anfrage, Testvorgabe oder Umgebungsvariable kopiert wird.",
  "pageText.57fc338e": "Schlüssel für einen besser vorhersehbaren manuellen Vergleich zweier Objekte sortieren.",
  "pageText.a199e1c3": "Parsing-Fehler durch fehlende Kommas, nicht zusammenpassende Klammern oder ungültige Anführungszeichen sichtbar machen.",
  "pageText.bcfd24c3": "Ein erfolgreiches Parsing lediglich als Syntaxprüfung behandeln. Es prüft keine JSON-Schemas, API-Verträge, Pflichtfelder, Domänentypen oder Geschäftsregeln.",
  "pageText.0b90c1ae": "Durchgerechnetes Formatierungsbeispiel",
  "pageText.52d27152": "Die Eingabe {\"active\":true,\"user\":{\"id\":42,\"roles\":[\"admin\",\"editor\"]}} wird zu einem eingerückten Objekt, in dem der verschachtelte user-Wert und das roles-Array auf einen Blick sichtbar sind. Die Minimierung erzeugt wieder die kompakte Form. Enthielte die Eingabe ein abschließendes Komma, würde der Browserparser sie ablehnen, anstatt das Dokument unbemerkt zu reparieren.",
  "pageText.97fb560b": "Einschränkungen und Datenschutz",
  "pageText.57498e3b": "Das Parsing verwendet JavaScript-Zahlen; Ganzzahlen außerhalb des zuverlässig darstellbaren Bereichs können daher an Genauigkeit verlieren.",
  "pageText.ff4c61d4": "Doppelte Objektnamen können beim Parsing zusammenfallen. Vermeiden Sie Arbeitsabläufe mit Parsing und erneuter Serialisierung, wenn Duplikate erhalten bleiben müssen.",
  "pageText.c4310853": "Sortierte Ausgabe ist praktisch, aber kein kryptografisches JSON-Kanonisierungsformat und sollte nicht zur Vorbereitung signierter Daten verwendet werden.",
  "pageText.e01043b7": "Die Verarbeitung läuft im Browser. Sensibles JSON kann dennoch über den Zwischenablageverlauf, Browsererweiterungen, Bildschirmfreigaben oder ein gemeinsam genutztes Gerät offengelegt werden.",
  "pageText.7491abdf": "Was prüft dieses Tool?",
  "pageText.000db4ab": "Es prüft die JSON-Syntax nach RFC 8259: Schlüssel und Zeichenfolgen in doppelten Anführungszeichen, Kommas zwischen Einträgen, zusammenpassende Klammern, gültige Zahlen und Escape-Sequenzen sowie einen einzelnen Wert auf oberster Ebene.",
  "pageText.d5749034": "Was sind häufige JSON-Fehler?",
  "pageText.5c93c394": "Fehlende oder abschließende Kommas, einfache statt doppelter Anführungszeichen, Eigenschaftsnamen ohne Anführungszeichen, Kommentare, Zeilenumbrüche ohne Escape-Sequenz innerhalb von Zeichenfolgen und fehlende schließende Klammern.",
  "pageText.e46fbe66": "Warum scheitert JSON mit Kommentaren oder abschließenden Kommas?",
  "pageText.716a4b48": "Standard-JSON erlaubt beides nicht. Editoren wie VS Code akzeptieren dies in JSONC-Einstellungsdateien, und auch JSON5 erlaubt es; JSON.parse und die meisten APIs lehnen es jedoch ab. Entfernen Sie diese Elemente, bevor Sie die Daten an einen strikten Parser senden.",
  "pageText.14469b94": "Warum zeigt der Fehler auf die falsche Stelle?",
  "pageText.7c657bf0": "Parser melden die Stelle, an der sie aufgeben, oft unmittelbar nach dem eigentlichen Fehler. Ein fehlendes Komma wird beim nächsten Schlüssel markiert; eine nicht geschlossene Zeichenfolge oder Klammer wird möglicherweise erst am Ende der Eingabe erkannt.",
  "pageText.40ba76d4": "Bedeutet gültiges JSON, dass es meinem API-Vertrag entspricht?",
  "pageText.10c910fb": "Nein. Die Syntaxvalidierung beweist nur, dass der Text geparst werden kann. Um Pflichtfelder, Typen und erlaubte Werte zu prüfen, validieren Sie das Dokument mit dem JSON-Schema-Validator gegen ein Schema.",
  "pageText.eb70ad1f": "Ja. Die Validierung läuft in Ihrem Browser mit JSON.parse; das eingefügte JSON wird nicht hochgeladen.",
  "pageText.c7264f74": "Was JSON gültig macht",
  "pageText.bc86098b": "JSON ist strenger als die JavaScript-Objektsyntax. Ein Dokument besteht aus einem einzelnen Wert: Objekt, Array, Zeichenfolge, Zahl, true, false oder null. Schlüssel und Zeichenfolgen müssen doppelte Anführungszeichen verwenden; innerhalb von Zeichenfolgen sind nur wenige Backslash-Escape-Sequenzen erlaubt, etwa \\n, \\t, \\\" und \\uXXXX. Zahlen dürfen keine führenden Nullen, kein führendes + und keinen abschließenden Dezimalpunkt haben; NaN und Infinity sind ungültig. Kommentare und abschließende Kommas gehören nicht zum Standard. JSONC- und JSON5-Dateien scheitern hier daher auch dann, wenn Ihr Editor sie akzeptiert.",
  "pageText.41041c7a": "Häufige JSON-Fehler und ihre Behebung",
  "pageText.5e91d5ea": "Abschließendes Komma: {\"a\": 1,} – das Komma nach dem letzten Eintrag löschen.",
  "pageText.c20c98a8": "Einfache Anführungszeichen: {'a': 'b'} – durch doppelte Anführungszeichen ersetzen.",
  "pageText.dcfdd19f": "Schlüssel ohne Anführungszeichen: {a: 1} – jeden Schlüssel in Anführungszeichen setzen: {\"a\": 1}.",
  "pageText.544083f8": "Fehlendes Komma: {\"a\": 1 \"b\": 2} – der Fehler zeigt meist auf \"b\", den Anfang des nächsten Eintrags.",
  "pageText.9cec3362": "Echte Zeilenumbrüche oder Tabulatoren innerhalb einer Zeichenfolge – als \\n oder \\t schreiben.",
  "pageText.7165deea": "Sprachliterale: True, None, undefined und NaN sind keine JSON-Werte; verwenden Sie true, null oder eine Zeichenfolge.",
  "pageText.02f2728d": "Die Fehlerposition verstehen",
  "pageText.e4c68e30": "Der Fehlertext stammt aus dem JSON-Parser Ihres Browsers; die Formulierung unterscheidet sich daher zwischen Chrome, Firefox und Safari. Enthält die Meldung eine Zeichenposition, rechnet der Validator sie in Zeile und Spalte um. Prüfen Sie diese Stelle und den Bereich unmittelbar davor: Parser scheitern am ersten Zeichen, mit dem kein gültiges Dokument fortgesetzt werden kann, oft ein Token nach dem eigentlichen Fehler.",
  "pageText.21519e4a": "Statistiken und Parsergrenzen",
  "pageText.7a975d41": "Für gültiges JSON zählt das Tool Objekte, Arrays, Zeichenfolgen, Zahlen, boolesche Werte, Nullwerte und alle Schlüssel und meldet die maximale Verschachtelungstiefe. Diese Zahlen helfen, unerwartet tiefe Nutzdaten oder Typabweichungen zu erkennen, etwa Zahlen, die als Zeichenfolgen eintreffen. Zwei Verhaltensweisen von JSON.parse sind relevant: Doppelte Schlüssel werden akzeptiert, wobei der letzte Wert gewinnt; Zahlen werden als 64-Bit-Gleitkommazahlen gelesen, weshalb Ganzzahlen über 2^53 - 1 im geparsten Wert und in der formatierten Kopie an Genauigkeit verlieren.",
  "pageText.035fa382": "Wie unterscheidet sich dies vom JSON-Validator?",
  "pageText.bab0a1c3": "Der JSON-Validator prüft, ob Text gültige JSON-Syntax hat. Der JSON-Schema-Validator prüft den geparsten Wert zusätzlich gegen Regeln für Pflichtfelder, Typen, Wertebereiche und verschachtelte Strukturen.",
  "pageText.c715893e": "Welche JSON-Schema-Version unterstützt dieses Tool?",
  "pageText.b987a2d9": "Das Tool verwendet Ajv v8 mit dem standardmäßigen Draft-7-kompatiblen Validator. Unbekannte Erweiterungsschlüsselwörter werden mit einer sichtbaren Warnung ignoriert; Schemas, die ein anderes Metaschema benötigen, können eine draftspezifische Konfiguration erfordern.",
  "pageText.7d800344": "Wird mein JSON hochgeladen?",
  "pageText.0f050d2b": "Nein. Parsing, Schemakompilierung und Validierung laufen in Ihrem Browser. Vermeiden Sie sensible Daten auf gemeinsam genutzten Geräten, da Zwischenablageverlauf und Browsererweiterungen sie weiterhin offenlegen können.",
  "pageText.842ff766": "Was die JSON-Schema-Validierung prüft",
  "pageText.0cf82fa3": "Die JSON-Syntaxvalidierung beweist nur, dass Text geparst werden kann. Die JSON-Schema-Validierung wendet einen Vertrag auf den geparsten Wert an. Sie kann Eigenschaften verlangen, Werttypen und -bereiche einschränken, unerwartete Felder ablehnen und verschachtelte Arrays oder Objekte validieren. Das Ergebnis enthält für jeden erkannten Regelverstoß den Instanzpfad, Schemapfad, das Schlüsselwort und die Meldung.",
  "pageText.54bfa1e8": "So verwenden Sie den Validator",
  "pageText.813839e9": "Den zu prüfenden JSON-Wert in den Dokumenteditor einfügen.",
  "pageText.110b07c6": "Ein Draft-7-kompatibles JSON-Schema in den Schemaeditor einfügen.",
  "pageText.f0234285": "„Validieren“ auswählen, um das Schema zu kompilieren und alle zutreffenden Fehler zu melden.",
  "pageText.060913a1": "Mit Instanzpfaden fehlerhafte Dokumentwerte und mit Schemapfaden die ablehnende Regel finden.",
  "pageText.2b1361d8": "Grenzen und Datenschutz",
  "pageText.74eb328b": "Ein gültiges Ergebnis bedeutet, dass das aktuelle Dokument jede erkannte Regel des angegebenen Schemas erfüllt; es beweist nicht, dass das Schema jede Geschäftsregel ausdrückt. Unbekannte Erweiterungsschlüsselwörter werden mit einer sichtbaren Warnung ignoriert. Externe Schemas werden nicht automatisch abgerufen. Schemas für nicht unterstützte Drafts oder mit entfernten Referenzen können eine anwendungsspezifische Konfiguration benötigen. Dokument und Schema werden mit JavaScript-Zahlen geparst; Ganzzahlen außerhalb des sicheren Ganzzahlbereichs können daher an Genauigkeit verlieren.",
  "pageText.e7bc2558": "Welche Formate werden unterstützt?",
  "pageText.ffabae3c": "Auf einer Seite JSON-Arrays von Objekten, auf der anderen getrennten Text: kommagetrenntes CSV, semikolongetrenntes CSV, tabulatorgetrenntes TSV oder durch senkrechte Striche getrennte Werte.",
  "pageText.5e2ca3f9": "Wie werden verschachtelte Objekte behandelt?",
  "pageText.929320e9": "Bei der Verschachtelungsoption „Abflachen“ werden verschachtelte Objekte zu Spalten in Punktnotation wie address.city; Arrays werden als JSON-Text geschrieben. „JSON-Zeichenfolge“ schreibt jedes verschachtelte Objekt oder Array als JSON-Text in eine einzelne Spalte der obersten Ebene.",
  "pageText.e74ea8dd": "Kann ich ein einzelnes JSON-Objekt in CSV umwandeln?",
  "pageText.2de8fa13": "Umschließen Sie es zuerst mit eckigen Klammern, etwa [{\"id\": 1}]. Der Konverter erwartet ein nicht leeres Array, in dem jedes Objekt zu einer Zeile wird.",
  "pageText.16c231f7": "Warum sind nach der Umwandlung von CSV in JSON alle Werte Zeichenfolgen?",
  "pageText.82993149": "CSV hat keine Datentypen. Deshalb wird jede Zelle als Zeichenfolge zurückgegeben (\"30\" statt 30), um falsche Annahmen über Werte wie Postleitzahlen oder IDs mit führenden Nullen zu vermeiden. Konvertieren Sie die benötigten Felder in Ihrem eigenen Code.",
  "pageText.df332cb3": "Warum zeigt Excel Umlaute oder Akzente falsch an?",
  "pageText.af4d1154": "Die heruntergeladene Datei ist UTF-8 ohne Byte-Reihenfolgemarkierung; manche Excel-Versionen nehmen beim Doppelklick auf eine CSV eine ältere Codierung an. Importieren Sie sie stattdessen über „Daten > Aus Text/CSV“ und wählen Sie UTF-8.",
  "pageText.44ee1d3e": "Werden meine Daten hochgeladen?",
  "pageText.3c70ccff": "Nein. Parsing und Konvertierung laufen in Ihrem Browser; der Download wird lokal erzeugt.",
  "pageText.c0a1927b": "Welche JSON-Struktur sich in CSV umwandeln lässt",
  "pageText.110e0569": "CSV ist eine flache Tabelle. Die Eingabe muss daher ein JSON-Array von Objekten sein, etwa [{\"id\": 1, \"name\": \"Ada\"}, {\"id\": 2, \"name\": \"Linus\"}]. Jedes Objekt wird zu einer Zeile. Die Kopfzeile enthält die Vereinigung aller Schlüssel in der Reihenfolge ihres ersten Auftretens. Bei einem fehlenden Schlüssel erhält ein Objekt somit eine leere Zelle, statt die anderen Spalten zu verschieben; auch null-Werte werden als leere Zellen geschrieben. Eingaben, die kein nicht leeres Array sind, werden abgelehnt. Ein Array einfacher Werte wie [1, 2, 3] hat keine Schlüssel, die zu Spalten werden könnten.",
  "pageText.16c22164": "Umgang mit verschachtelten Objekten und Arrays",
  "pageText.2c00e178": "Abflachen (Standard): {\"address\": {\"city\": \"Paris\"}} wird zu einer Spalte address.city. Arrays werden als JSON-Text in eine Zelle geschrieben, etwa [\"a\",\"b\"].",
  "pageText.98e451ad": "JSON-Zeichenfolge: Behält nur Spalten der obersten Ebene bei und schreibt jedes verschachtelte Objekt oder Array als JSON-Text in seine Zelle.",
  "pageText.e646f74d": "Erweitern: Behält ebenfalls Spalten der obersten Ebene bei, serialisiert verschachtelte Objekte jedoch nicht; sie erscheinen deshalb als [object Object]. Verwenden Sie bei verschachtelten Daten „Abflachen“ oder „JSON-Zeichenfolge“.",
  "pageText.869ce735": "Anführungszeichen: Felder mit Trennzeichen, doppelten Anführungszeichen oder Zeilenumbrüchen werden in doppelte Anführungszeichen gesetzt. Eingebettete Anführungszeichen werden verdoppelt (\"\"), wie in RFC 4180 beschrieben.",
  "pageText.73ca705a": "CSV zurück in JSON umwandeln",
  "pageText.cbff28ff": "Der CSV-Parser verarbeitet Felder in Anführungszeichen, verdoppelte Anführungszeichen und Zeilenumbrüche innerhalb solcher Werte und akzeptiert LF- sowie CRLF-Zeilenenden. Ist „Erste Zeile enthält Überschriften“ aktiviert, werden die Kopfzellen zu Eigenschaftsnamen; andernfalls heißen die Schlüssel column1, column2 usw. Leere Zeilen werden übersprungen, fehlende Zellen werden zu leeren Zeichenfolgen und Zellen jenseits der Kopfzeilenbreite werden verworfen. Punktnotation in Überschriften wie address.city wird nicht zu verschachtelten Objekten zurückgebaut. Jeder Wert bleibt eine Zeichenfolge; bearbeiten Sie das Ergebnis nach, wenn Sie Zahlen, boolesche Werte oder Verschachtelungen benötigen.",
  "pageText.e37dc901": "Ein Trennzeichen auswählen",
  "pageText.1b5836ff": "Für die meisten Tools und APIs eignet sich ein Komma. Verwenden Sie ein Semikolon für Tabellenkalkulationen mit Komma als Dezimaltrennzeichen, einen Tabulator für TSV, das sich sauber in Tabellen einfügen lässt, oder einen senkrechten Strich, wenn Werte oft Kommas enthalten. Verwenden Sie beim Zurückkonvertieren dieselbe Trennzeicheneinstellung.",
  "pageText.3f419e1e": "Was unterscheidet interface und type?",
  "pageText.2896a196": "Beide beschreiben Objektstrukturen. Interfaces lassen sich mit extends erweitern und über mehrere Deklarationen zusammenführen; Typaliase können außerdem Unions, Schnittmengen und gemappte Typen ausdrücken. Für einfache API-Modelle eignet sich beides. Folgen Sie daher der Konvention Ihrer Codebasis.",
  "pageText.a76e5f0e": "Wie werden Arrays behandelt?",
  "pageText.9e602604": "Arrays mit einem einzigen Typ werden zu string[], number[] usw. Gemischte Arrays werden zu Unions wie (string | null)[]. Bei Objektarrays werden die Schlüssel aller Elemente zu einem gemeinsamen Elementtyp zusammengeführt; ein leeres Array wird zu unknown[].",
  "pageText.15efe178": "Warum hat eine Eigenschaft den Typ null oder unknown[]?",
  "pageText.e7edbada": "Das Beispiel enthält nicht genügend Informationen. Ein null-Wert kann nur als null typisiert werden; ein leeres Array hat kein untersuchbares Element. Ersetzen Sie diese Typen durch die tatsächlichen, etwa string | null oder Order[].",
  "pageText.3f42cbef": "Validieren die erzeugten Typen Daten zur Laufzeit?",
  "pageText.63a3aa5d": "Nein. TypeScript-Typen werden beim Kompilieren entfernt und können deshalb keine fehlerhafte API-Antwort ablehnen. Kombinieren Sie sie für nicht vertrauenswürdige Eingaben mit einer Laufzeitvalidierung wie Zod oder mit JSON-Schema-Validierung.",
  "pageText.dfbfc464": "Wie verwende ich das erzeugte Interface?",
  "pageText.ecad980d": "In einer .ts-Datei speichern, importieren und die geparsten Daten annotieren, etwa const user = (await response.json()) as Root; Die Typumwandlung dokumentiert die erwartete Struktur, prüft sie aber nicht.",
  "pageText.f2cb618b": "Nein. Das JSON wird in Ihrem Browser geparst und konvertiert; die erzeugten Typen werden nirgendwohin gesendet.",
  "pageText.24604c50": "Wie Typen aus einem JSON-Beispiel abgeleitet werden",
  "pageText.775e7460": "Der Konverter parst Ihr JSON und ordnet jedem Wert einen TypeScript-Typ zu: Zeichenfolgen werden zu string, Zahlen zu number (JSON hat keinen eigenen Ganzzahltyp), true und false zu boolean und null zu null. Objekte werden zu Interfaces oder Typaliasen; Arrays werden zum Elementtyp mit angehängtem []. Beispielsweise erzeugt {\"id\": 1, \"tags\": [\"a\", \"b\"], \"owner\": null} die Definitionen id: number; tags: string[]; owner: null;. Schlüssel, die keine gültigen Bezeichner sind, etwa \"first-name\", werden in der Ausgabe in Anführungszeichen gesetzt.",
  "pageText.2a4f9a5c": "Optionen und ihre Auswirkungen",
  "pageText.d80a13bc": "„Name des Wurzeltyps“ legt den Namen des Typs auf oberster Ebene fest und wandelt ihn in PascalCase um.",
  "pageText.58ca8924": "„Interface verwenden“ schaltet zwischen Interface-Deklarationen und Typaliasen um.",
  "pageText.b2718dc0": "„Eigenschaften optional machen“ fügt jeder Eigenschaft ein ? hinzu.",
  "pageText.7bc73d90": "„Export-Schlüsselwort hinzufügen“ setzt export vor jede Deklaration.",
  "pageText.f1ea6f0b": "„Verschachteltes extrahieren“ erstellt benannte Interfaces für verschachtelte Objekte und Objekte in Arrays (orders wird zu OrdersItem[]) statt Inline-Objekttypen.",
  "pageText.e8492b19": "„Union-Typen erkennen“ schreibt gemischte Arrays als Unions wie (string | null)[].",
  "pageText.f3ef2d66": "„JSDoc-Kommentare“ fügt über jeder Eigenschaft einen Kommentar hinzu; bei aktiviertem „Verschachteltes extrahieren“ enthalten die Kommentare Beispielwerte.",
  "pageText.91b2ba93": "Grenzen der Typableitung aus einem einzelnen Beispiel",
  "pageText.962bd555": "Ein einzelnes JSON-Dokument zeigt, wie eine Antwort aussah, aber nicht jede Struktur, die eine API zurückgeben kann. Prüfen Sie folgende Fälle, bevor Sie sich auf die Ausgabe verlassen:",
  "pageText.c04be53a": "Werte, die im Beispiel null sind, erhalten nur den Typ null. Bei aktiviertem „Verschachteltes extrahieren“ werden sie zusätzlich als optional markiert.",
  "pageText.65099d30": "Bei Objektarrays bestimmt der erste für jeden Schlüssel gefundene Wert dessen Typ. Schlüssel, die nur in einigen Elementen vorkommen, werden erst bei aktiviertem „Eigenschaften optional machen“ als optional markiert.",
  "pageText.1eb094ba": "Bei aktiviertem „Verschachteltes extrahieren“ werden ISO-Datumszeichenfolgen wie 2024-01-15 oder 2024-01-15T00:00:00Z als Date typisiert. JSON.parse gibt Zeichenfolgen zurück; ändern Sie diese Typen daher in string, sofern Ihr Code sie nicht konvertiert.",
  "pageText.1effcea1": "Numerische Zeichenfolgen bleiben string und große Ganzzahlen bleiben number; der Generator errät weder bigint noch spezielle ID-Typen mit Typmarkierung.",
  "pageText.9f62e4a3": "Eigenschaften behalten die Reihenfolge des Beispiels bei. Ein Objekt ohne Schlüssel wird bei Interfaces zu {} und bei Typaliasen zu Record<string, unknown>.",
  "pageText.0a050da5": "Was ist YAML?",
  "pageText.521b34a0": "YAML (YAML Ain't Markup Language) ist ein menschenlesbares Datenserialisierungsformat, das Einrückungen statt Klammern verwendet. Es ist in Konfigurationsdateien für Kubernetes, Docker Compose, GitHub Actions und Ansible verbreitet.",
  "pageText.758c1349": "Wann sollte ich YAML oder JSON verwenden?",
  "pageText.ed21d83b": "YAML lässt sich leichter von Hand lesen und bearbeiten und unterstützt Kommentare, was sich für Konfigurationsdateien eignet. JSON ist einfacher zu parsen, hat keine Einrückungsregeln und wird überall unterstützt, was sich für APIs und Datenaustausch eignet.",
  "pageText.e2958c4e": "Welcher YAML-Kompatibilitätsmodus wird verwendet?",
  "pageText.962cba8d": "Die Konvertierung verwendet das YAML-1.1-Kompatibilitätsschema von js-yaml, sodass Anker, Aliase, Merge-Schlüssel, explizite Tags und typisierte Skalare wie im Beispiel funktionieren. YAML 1.1 kann einige unquotierte Skalare anders interpretieren als YAML 1.2.",
  "pageText.d8137672": "Warum wurden yes, no oder NO zu true oder false?",
  "pageText.a21ecd10": "Unter YAML 1.1 sind yes, no, on und off ohne Anführungszeichen boolesche Werte. Setzen Sie einen Wert in Anführungszeichen, etwa country: \"NO\", wenn er eine Zeichenfolge bleiben muss.",
  "pageText.5403e57d": "Kann ich eine YAML-Datei mit mehreren Dokumenten konvertieren?",
  "pageText.69ba905b": "Nicht in einem Durchlauf. Dieser Konverter liest ein einzelnes Dokument und meldet einen Fehler, wenn er --- als Trennzeichen mit weiteren Inhalten findet. Teilen Sie die Datei auf und konvertieren Sie jedes Dokument einzeln.",
  "pageText.1368c99b": "Bleiben YAML-Kommentare erhalten?",
  "pageText.311c9ca4": "Nein. JSON hat keine Kommentarsyntax. Kommentare gehen daher bei der Konvertierung in JSON verloren und können beim Zurückkonvertieren in YAML nicht wiederhergestellt werden.",
  "pageText.c261a8ae": "Wie YAML auf JSON abgebildet wird",
  "pageText.4bc6e145": "YAML-Zuordnungen werden zu JSON-Objekten, Sequenzen zu Arrays und Skalare zu Zeichenfolgen, Zahlen, booleschen Werten oder null. Kommentare werden verworfen. Anker (&name), Aliase (*name) und Merge-Schlüssel (<<: *defaults) werden zu vollständigen Kopien aufgelöst, weshalb das JSON länger als das YAML sein kann. JSON-zu-YAML erzeugt einfaches YAML im Blockstil: Schlüssel behalten ihre Reihenfolge, lange Zeichenfolgen werden nicht umgebrochen und wiederholte Objekte werden vollständig statt als Anker ausgegeben.",
  "pageText.8680939e": "YAML-1.1-Werte, die keine Zeichenfolgen sind",
  "pageText.28441e9f": "Das YAML-1.1-Schema entspricht vielen bestehenden Konfigurationsparsern, typisiert einige unquotierte Werte jedoch auf überraschende Weise:",
  "pageText.b9e6b5c4": "yes, no, on und off werden zu true oder false. Dies ist das klassische Norwegen-Problem, bei dem country: NO zu false wird.",
  "pageText.195c972a": "Zahlen mit führender Null wie 010 werden oktal (8) und 0x1F wird hexadezimal (31) gelesen.",
  "pageText.4683982b": "Durch Doppelpunkte getrennte Ziffern wie 22:22 werden als Zahlen zur Basis 60 (1342) gelesen, was Portzuordnungen und Zeitangaben verfälschen kann.",
  "pageText.bc57ba5f": "version: 1.10 wird zur Zahl 1.1; Datumswerte wie 2024-01-01 werden zu Zeitstempeln (2024-01-01T00:00:00.000Z).",
  "pageText.b58f4598": "Anführungszeichen und häufige Parsing-Fehler",
  "pageText.f9b2a402": "Setzen Sie jeden Wert, der Text bleiben muss, in Anführungszeichen: version: \"1.10\", port: \"22:22\", country: \"NO\". Die JSON-zu-YAML-Ausgabe setzt solche Zeichenfolgen automatisch in Anführungszeichen.",
  "pageText.159243ab": "Tabulatoren sind für Einrückungen nicht erlaubt. Die Fehlermeldung zeigt Zeile und Spalte an, etwa (2:1).",
  "pageText.cafe74b5": "Ein Fehler wegen falscher Einrückung eines Zuordnungseintrags bedeutet meist, dass ein Schlüssel anders viele Leerzeichen eingerückt ist als benachbarte Schlüssel.",
  "pageText.249bfb43": "Unquotierte Werte mit *, &, !, %, @ oder einem Graviszeichen am Anfang haben in YAML eine besondere Bedeutung und müssen in Anführungszeichen gesetzt werden.",
  "pageText.b07acd91": "JSON-zu-YAML benötigt striktes JSON: Abschließende Kommas, Kommentare und Zeichenfolgen in einfachen Anführungszeichen werden abgelehnt.",
  "pageText.6ad0b0ed": "Kubernetes- und CI-Dateien prüfen",
  "pageText.155c7fbc": "Kubernetes-Manifeste, Docker-Compose-Dateien und GitHub-Actions-Workflows werden in YAML geschrieben, während Tools wie die Ausgabe von kubectl get -o json und jq mit JSON arbeiten. Die Konvertierung einer Datei in JSON zeigt schnell, wie ein Parser jeden Wert typisiert hat, etwa ob ein Port zur Zahl wurde oder eine Version eine Zeichenfolge blieb, bevor ein Deployment daran scheitert. Fügen Sie beim Zurückkonvertieren in YAML benötigte Kommentare von Hand wieder hinzu.",
  "pageText.ac46f1af": "Ist JSON Pointer dasselbe wie JSONPath?",
  "pageText.cac8f6a8": "Nein. JSON Pointer ist die kompakte RFC-6901-Syntax zur Identifizierung eines einzelnen Werts. JSONPath ist eine eigene Abfragesprache mit Filtern, Platzhaltern und weiteren Auswahlfunktionen.",
  "pageText.8f9cad79": "Wie verweise ich auf einen Schrägstrich oder eine Tilde in einem Schlüssel?",
  "pageText.de336765": "Codieren Sie eine Tilde als ~0 und einen Schrägstrich als ~1 in jedem Referenztoken. Beispielsweise wählt /a~1b das Objektmitglied mit dem Namen a/b aus.",
  "pageText.3da5dc4a": "Was wählt ein leerer Pointer aus?",
  "pageText.354d9f94": "Der leere JSON Pointer wählt das vollständige JSON-Dokument aus.",
  "pageText.57bcfda7": "Was der JSON-Pointer-Auswerter macht",
  "pageText.f894f2e1": "JSON Pointer identifiziert einen einzelnen Wert, indem durch Schrägstriche getrennte Referenztokens ein JSON-Dokument durchlaufen. Objekttokens müssen Mitgliedsnamen genau entsprechen, während Array-Tokens nullbasierte Indizes verwenden. Der Auswerter meldet fehlende Mitglieder, ungültige Escape-Sequenzen, ungültige Array-Indizes oder Versuche, einen primitiven Wert zu durchlaufen, statt unbemerkt einen falschen Wert zurückzugeben.",
  "pageText.ab93ef77": "Syntax und Grenzen",
  "pageText.ce9c3b21": "Verwenden Sie eine leere Zeichenfolge für die Dokumentwurzel und / für ein Objektmitglied mit leerem Namen.",
  "pageText.dcc291b6": "Array-Indizes sind kanonische nicht negative Dezimalzahlen. Das spezielle Token - eignet sich für JSON-Patch-Anhängeoperationen, identifiziert aber keinen vorhandenen Wert.",
  "pageText.c2421fef": "Das Tool wertet nur die JSON-Pointer-Syntax aus. Es implementiert keine JSONPath-Filter, JSON-Patch-Operationen, URI-Fragment-Decodierung oder Schemavalidierung.",
  "pageText.532a56fb": "Wie unterscheidet sich JSONPath von JSON Pointer?",
  "pageText.ad67c7e7": "JSON Pointer identifiziert einen genau bestimmten Wert mit schrägstrichgetrennten Tokens. JSONPath ist eine Abfragesprache, die mehrere Werte mit Platzhaltern, Slices und rekursiver Suche auswählen kann.",
  "pageText.f33ae85e": "Unterstützt dieser Tester Filterausdrücke?",
  "pageText.922825ba": "Nein. Er unterstützt bewusst eine sichere Kernteilmenge von RFC 9535 und lehnt Filter- oder Skriptausdrücke ab, statt Code auszuwerten. Verwenden Sie untergeordnete Namen, Indizes, Platzhalter, Slices oder rekursive Suche.",
  "pageText.37dcaef8": "Wird das JSON-Dokument hochgeladen?",
  "pageText.b2396fff": "Nein. JSON-Parsing und Pfadauswertung laufen in Ihrem Browser. Zwischenablageverlauf, Erweiterungen, Seitenskripte und gemeinsam genutzte Geräte können sensible Eingaben weiterhin offenlegen.",
  "pageText.926480c9": "Was der JSONPath-Tester auswählt",
  "pageText.6475775d": "Eine JSONPath-Abfrage beginnt bei $ und durchläuft Objektmitglieder oder Array-Elemente. Ein einzelner Pfad wie $.store.book[0].title wählt einen Wert aus; Platzhalter, Slices und rekursive Suche können eine geordnete Trefferliste erzeugen. Jedes Ergebnis enthält den ausgewählten Wert und einen normalisierten Pfad zurück zu seiner Position im Eingabedokument.",
  "pageText.0522c849": "Unterstützte Syntax und Sicherheitsgrenze",
  "pageText.167ce42e": "Verwenden Sie .name oder ['name'] für Objektmitglieder und [0] oder [-1] für Array-Indizes.",
  "pageText.325bdf69": "Verwenden Sie .* oder [*] für Platzhalter untergeordneter Elemente, [start:end:step] für Array-Slices und ..name oder ..* für rekursive Suche.",
  "pageText.0fa965f1": "Filterselektoren, eingebettetes JavaScript, Funktionen und shellartige Ausdrücke werden abgelehnt; das Tool wertet den Abfragetext niemals als Code aus.",
  "pageText.0bd77a57": "Der Tester validiert vor der Abfrage die JSON-Syntax. Er wendet kein JSON-Schema an und beweist nicht, dass ausgewählte Werte einem API-Vertrag entsprechen.",
  "pageText.86927e79": "JSONPath-Ergebnisse interpretieren",
  "pageText.5564c402": "Null Treffer bedeuten, dass eine gültige Abfrage im aktuellen Dokument keinen Wert ausgewählt hat; das unterscheidet sich von der Auswahl eines JSON-null-Werts. Platzhalter und rekursive Suche können viele Werte zurückgeben. Gleiche Werte an verschiedenen Positionen bleiben eigene Treffer, da sich ihre normalisierten Pfade unterscheiden.",
  "pageText.2a7811c2": "Kann ein einzelnes JSON-Beispiel jede gültige Nutzdatenstruktur beschreiben?",
  "pageText.8aeafe2c": "Nein. Der Generator kann nur die Werte und Strukturen im Beispiel ableiten. Prüfen Sie Pflichtfelder und optionale Felder, Geschäftsregeln, Enums, Standardwerte, Verfeinerungen und Transformationen anhand des tatsächlichen API-Vertrags.",
  "pageText.9c0cad39": "Wie werden Arrays und fehlende Objekteigenschaften behandelt?",
  "pageText.01ee6835": "Array-Elementtypen werden zusammengeführt. Objekte im selben Array erhalten eine gemeinsame Struktur; fehlt eine Eigenschaft in einem Beispielobjekt, wird sie optional. Gemischte Arrays primitiver Werte werden zu Zod-Unions; leere Arrays verwenden z.unknown()-Elemente.",
  "pageText.2decefae": "Nein. JSON-Parsing und Schemaerzeugung laufen in Ihrem Browser. Sensible Daten können weiterhin durch Zwischenablageverlauf, Browsererweiterungen, Bildschirmfreigaben oder gemeinsam genutzte Geräte offengelegt werden. Verwenden Sie daher möglichst bereinigte Beispiele.",
  "pageText.a2131814": "Was der JSON-zu-Zod-Generator erzeugt",
  "pageText.843b2234": "Der Generator parst einen JSON-Wert und bildet Zeichenfolgen, Zahlen, Ganzzahlen, boolesche Werte, Nullwerte, Arrays und Objekte auf Zod-Ausdrücke ab. Der Wurzelname wird zu einem TypeScript-sicheren Schemabezeichner normalisiert. Bei aktivierter Typableitung enthält die Ausgabe außerdem einen z.infer-Alias, sodass Laufzeitvalidator und Typ zur Kompilierungszeit aus demselben Schema stammen.",
  "pageText.9fdeb27b": "Ableitungsregeln, die Sie prüfen sollten",
  "pageText.a373d436": "Ganzzahlen werden zu z.number().int(); Werte mit einem Nachkommaanteil werden zu z.number().",
  "pageText.7640c5c6": "Gemischte Array-Beispiele werden zu Unions. Objektarrays führen gefundene Schlüssel zusammen und markieren Schlüssel als optional, wenn sie in einem Beispiel fehlen.",
  "pageText.51004b4a": "Die optionale Formaterkennung erkennt typische UUID-, ISO-Datum-Uhrzeit-, E-Mail- und HTTP(S)-URL-Zeichenfolgen mit Zod-Zeichenfolgenprüfungen.",
  "pageText.297ff683": "Der strikte Objektmodus hängt .strict() an, sodass unbekannte Schlüssel abgelehnt werden, statt von den erzeugten Objektschemas unbemerkt entfernt zu werden.",
  "pageText.373ed392": "Leere Arrays können keinen Elementtyp erkennen lassen und werden daher zu z.array(z.unknown()).",
  "pageText.3733edff": "Beispielableitung ist ein Ausgangspunkt, kein Vertrag",
  "pageText.35b1bbc6": "Ein Beispiel beweist keine Mindestlängen, Zahlenbereiche, zulässigen Enum-Werte, feldübergreifenden Regeln, Standardwerte, Konvertierungsregeln oder ob ein zufällig vorhandenes Feld immer erforderlich ist. Vergleichen Sie das Ergebnis mit der API-Dokumentation und tatsächlichen Grenzfällen und ergänzen Sie Zod-Verfeinerungen und Tests, bevor Sie nicht vertrauenswürdige Eingaben akzeptieren. Das Tool erzeugt nur Quelltext; es führt das Schema nicht aus und installiert Zod nicht in Ihrem Projekt.",
  "pageText.b12736d6": "Datenschutz und Eingabegrenzen",
  "pageText.ac6e0f5e": "Die Erzeugung erfolgt lokal und ist bei gleichen Optionen und Eingaben deterministisch. Tief verschachtelte Eingaben sind begrenzt, damit der Browser reagiert. Vermeiden Sie Produktiv-Tokens oder personenbezogene Daten auch in lokalen Tools, wenn bereinigte Nutzdaten dieselbe Struktur beschreiben können.",
  "pageText.c12e919d": "Welche JSON-Patch-Operationen werden unterstützt?",
  "pageText.f93d0eb6": "Die Anwendung unterstützt add, remove, replace, move, copy und test. Erzeugte Patches verwenden deterministische add-, remove- und replace-Operationen; geänderte Arrays werden als ein Wert ersetzt, statt einen instabilen elementweisen Vergleich zu versuchen.",
  "pageText.9bcbf59a": "Wie werden Schrägstriche und Tilden in Pfaden dargestellt?",
  "pageText.153cbcc5": "JSON-Patch-Pfade verwenden RFC-6901-JSON-Pointer. Ein Schrägstrich in einem Objektschlüssel wird zu ~1 und eine Tilde zu ~0. Ein Schlüssel namens a/b wird somit über /a~1b adressiert.",
  "pageText.9bd286e3": "Ändert das Anwenden eines Patches den Quelleditor?",
  "pageText.1e520c6e": "Nein. Das Quell-JSON wird vor den Operationen geklont; das Ergebnis wird separat angezeigt. Das Entfernen der vollständigen Dokumentwurzel wird abgelehnt, da das Tool immer einen gültigen JSON-Wert zurückgibt.",
  "pageText.830d9198": "Wie aus dem JSON-Vergleich ein Patch wird",
  "pageText.27cb8257": "Objektschlüssel werden in sortierter Reihenfolge verglichen, sodass dieselbe Eingabe dieselbe Operationsfolge erzeugt. Fehlende Schlüssel werden zu remove-Operationen, neue Schlüssel zu add-Operationen und geänderte primitive Werte oder Arrays zu replace-Operationen. Verschachtelte Objekte werden rekursiv durchlaufen; jeder ausgegebene Pfad wird als RFC-6901-JSON-Pointer mit Escape-Sequenzen versehen.",
  "pageText.7a310a1e": "Patch-Anwendung und Verhalten bei Fehlern",
  "pageText.afbc723e": "Array-Indizes werden strikt validiert; das spezielle Token - hängt nur während add-Operationen an.",
  "pageText.e8c8cf45": "Replace, remove, move, copy und test benötigen vorhandene Quellpfade; Fehler nennen die Operationsnummer.",
  "pageText.3a420fd8": "Move lehnt das Verschieben eines Werts in eines seiner eigenen untergeordneten Elemente ab und wendet Array-Indexänderungen in Operationsreihenfolge an.",
  "pageText.b3c285ba": "Test verwendet strukturelle JSON-Gleichheit statt Objektidentität oder serialisierter Schlüsselreihenfolge.",
  "pageText.7a08072a": "Besondere Objektnamen wie __proto__ werden als eigene Dateneigenschaften angelegt, ohne Objektprototypen zu verändern.",
  "pageText.acc508bd": "Determinismus, Datenschutz und Prüfung",
  "pageText.39b818a8": "Erzeugung und Anwendung laufen vollständig in diesem Browser. Der erzeugte Vergleich ist bewusst vorhersehbar, aber nicht garantiert minimal, insbesondere bei Arrays. Prüfen Sie Operationsreihenfolge, Kosten der Array-Ersetzung, gleichzeitige Dokumentversionen und Anwendungsautorisierung, bevor Sie einen Patch auf dauerhaft gespeicherte Daten oder eine API anwenden.",
  "pageText.28d8aae9": "Welche Programmiersprachen werden unterstützt?",
  "pageText.b4757b15": "Der Generator unterstützt derzeit Go (Golang-Structs mit JSON-Tags), Python (Pydantic-v2-BaseModels), Rust (Serde-Structs), C# (Records mit JsonPropertyName) und Kotlin (Datenklassen).",
  "pageText.294e643e": "Wie werden verschachtelte Objekte und Arrays behandelt?",
  "pageText.850e01f2": "Verschachtelte JSON-Objekte werden als eigene typisierte Structs oder Klassen mit camelCase/PascalCase extrahiert; Array-Elementtypen werden automatisch abgeleitet.",
  "pageText.05225c44": "Werden meine JSON-Daten auf einen Server hochgeladen?",
  "pageText.16c71e23": "Nein. Die Codeerzeugung läuft vollständig lokal in Ihrem Browser mit clientseitigem JavaScript.",
  "pageText.6bf4c146": "Wie berechnet dieses Tool die JSON-Bytegröße?",
  "pageText.94825111": "Es berechnet mit der TextEncoder-API des Browsers die genaue UTF-8-Byteanzahl sowohl formatierter als auch minimierter JSON-Nutzdaten.",
  "pageText.449785d1": "Welche Kennzahlen werden ermittelt?",
  "pageText.200cd0b4": "Unkomprimierte Bytegröße, minimierte Bytegröße, prozentuale Verkleinerung, Gesamtschlüsselzahl, Anzahl verschachtelter Objekte und Arrays, maximale Hierarchietiefe und Anzahl der null-Felder.",
  "pageText.6bafe4b9": "Ja, die gesamte Verarbeitung erfolgt lokal in Ihrem Browser.",
  "pageText.f9bc4fe7": "Was ist Quoted-Printable-Codierung?",
  "pageText.b1f6a629": "Quoted-Printable ist eine Codierung mit druckbaren ASCII-Zeichen nach RFC 2045, die für die Übertragung von Nicht-ASCII-Zeichen per E-Mail entwickelt wurde.",
  "pageText.5c516685": "Sind meine Daten geschützt?",
  "pageText.ee52101e": "Ja, die gesamte Codierung und Decodierung läuft vollständig lokal in Ihrem Browser.",
  "pageText.6c6f7098": "Was ist der Base64URL-Codierer/Decodierer?",
  "pageText.f020a31f": "URL-sicheres Base64 ohne Füllzeichen codieren und decodieren.",
  "pageText.16ca11a3": "Wie unterscheidet sich Base64url von Standard-Base64?",
  "pageText.3b137bc0": "Base64url ersetzt + durch - und / durch _, damit der Wert sicher in URLs, Dateinamen und JWT-Segmenten stehen kann; die =-Füllzeichen entfallen gewöhnlich.",
  "pageText.06b202a5": "Kann ich eine vorhandene Base64-Zeichenfolge umwandeln, statt Text zu codieren?",
  "pageText.59313335": "Ja. Im Modus „Base64 zu Base64url“ werden das Alphabet ersetzt und Füllzeichen entfernt; „Base64url zu Base64“ stellt +, / und die =-Füllzeichen wieder her. Die Bytes werden nicht neu codiert.",
  "pageText.ad19a97c": "Werden meine Daten sicher verarbeitet?",
  "pageText.32092515": "Ja, die gesamte Verarbeitung und alle Berechnungen laufen für Datenschutz und Geschwindigkeit vollständig lokal in Ihrem Browser.",
  "pageText.054c55ba": "Ist Base64 eine Verschlüsselung?",
  "pageText.040d6643": "Nein. Base64 ist eine umkehrbare Codierung ohne Schlüssel; jeder kann sie decodieren. Verwenden Sie sie niemals zum Verbergen von Passwörtern, API-Tokens oder personenbezogenen Daten; nutzen Sie dafür echte Verschlüsselung wie AES-GCM.",
  "pageText.c07235a3": "Wie decodiere ich Base64 in JavaScript?",
  "pageText.190c8592": "Verwenden Sie in Node.js Buffer.from(value, 'base64').toString('utf8'). Im Browser gibt atob(value) eine Binärzeichenfolge zurück. Für UTF-8-Text verwenden Sie deshalb new TextDecoder().decode(Uint8Array.from(atob(value), (c) => c.charCodeAt(0))).",
  "pageText.3d513a1d": "Wie codiere ich eine Zeichenfolge in Python als Base64?",
  "pageText.5817c0f8": "Verwenden Sie nach import base64 den Aufruf base64.b64encode('text'.encode('utf-8')).decode('ascii'). Für das URL-sichere Alphabet rufen Sie stattdessen base64.urlsafe_b64encode auf.",
  "pageText.43cf2c6b": "Warum endet Base64 mit = oder ==?",
  "pageText.9dc050ab": "Base64 codiert drei Bytes als vier Zeichen. Ist die Eingabelänge kein Vielfaches von drei, füllen ein oder zwei =-Zeichen die Ausgabe auf ein Vielfaches von vier auf. Sie tragen keine Daten; dieser Decoder akzeptiert auch Eingaben, bei denen die Füllzeichen vollständig entfernt wurden.",
  "pageText.1e9e71cb": "Warum lässt sich scheinbar gültiges Base64 hier nicht decodieren?",
  "pageText.2bfb36f5": "Entweder enthält die Zeichenfolge Zeichen außerhalb des Standardalphabets (oft - oder _ aus Base64URL), oder die decodierten Bytes sind kein UTF-8-Text. Bilder, PDFs und andere Binärdaten scheitern in diesem Textdecoder auch bei korrekt geformtem Base64. Verwenden Sie stattdessen „Base64 zu Bild“ oder „Base64 zu PDF“.",
  "pageText.1f843857": "Werden meine Daten an einen Server gesendet?",
  "pageText.5356631f": "Nein. Codierung und Decodierung verwenden die integrierten Browserfunktionen btoa und atob auf Ihrem Gerät; keine eingefügten Daten werden hochgeladen.",
  "pageText.9673c683": "Wie Base64-Codierung funktioniert",
  "pageText.6840df16": "Base64 liest die Eingabe in Gruppen von drei Bytes (24 Bits) und teilt sie in vier 6-Bit-Gruppen. Jede Gruppe wählt ein Zeichen aus einem Alphabet mit 64 Zeichen: A–Z, a–z, 0–9, + und /. Ist die Eingabelänge kein Vielfaches von drei, wird die Ausgabe mit einem oder zwei =-Zeichen ergänzt, damit ihre Länge ein Vielfaches von vier bleibt. Beispielsweise wird Man zu TWFu, Ma zu TWE= und M zu TQ== codiert.",
  "pageText.376d85ff": "Dieses Tool wandelt Ihren Text vor der Codierung in UTF-8-Bytes um, sodass Nicht-ASCII-Zeichen korrekt hin- und zurückgewandelt werden: é umfasst zwei Bytes und wird zu w6k=; das Emoji 😀 umfasst vier Bytes und wird zu 8J+YgA==.",
  "pageText.3144275a": "Warum die Base64-Ausgabe etwa 33 % größer ist",
  "pageText.ce1baf42": "Je drei Eingabebytes werden zu vier Ausgabezeichen; codierte Daten wachsen also um ungefähr ein Drittel, zuzüglich bis zu zweier Füllzeichen. Aus 30 KB Nutzdaten werden etwa 40 KB Base64. Dieser Zusatzaufwand entsteht, weil beliebige Bytes mit druckbaren Zeichen dargestellt werden. Deshalb findet sich Base64 in JSON-Feldern, Daten-URIs, E-Mail-Anhängen und HTTP-Basic-Authentifizierungsheadern. Es ist weder Komprimierung noch Verschlüsselung.",
  "pageText.b3162ffd": "Base64 und Base64URL im Vergleich",
  "pageText.1a8a3497": "Standard-Base64 (RFC 4648, Abschnitt 4) verwendet + und / und füllt mit = auf. Base64URL (Abschnitt 5) ersetzt + durch - und / durch _ und lässt Füllzeichen meist weg, sodass Werte ohne Prozentcodierung in URLs, Dateinamen und JWT-Segmenten stehen können. Dieses Tool verwendet das Standardalphabet. Ersetzen Sie zum Decodieren von Base64URL hier zuerst - durch + und _ durch /, oder verwenden Sie den eigenen Base64URL-Codierer.",
  "pageText.92565596": "Häufige Decodierungsfehler und ihre Behebung",
  "pageText.a3f451e2": "Ungültige Zeichen: Alles außerhalb von A–Z, a–z, 0–9, +, / und = wird abgelehnt. Häufige Ursachen sind - und _ aus Base64URL oder zusammen mit dem Wert kopierte Anführungszeichen.",
  "pageText.8245a36e": "Falsche Länge: Ein Wert, dessen Länge bei Division durch vier den Rest eins hat, kann nicht gültig sein. Meist ging beim Kopieren ein Zeichen verloren. Vollständig fehlende Füllzeichen werden akzeptiert.",
  "pageText.f0196a80": "Binärinhalt: Die decodierten Bytes müssen gültiger UTF-8-Text sein. Base64 für Bilder, PDFs oder komprimierte Daten scheitert hier trotz gültiger Codierung.",
  "pageText.016597d5": "Zeilenumbrüche: Leerzeichen und Zeilenumbrüche innerhalb eines einzelnen Werts, etwa MIME-Ausgabe mit Umbruch nach 76 Zeichen, werden ignoriert. Im Stapelmodus wird dagegen jede Zeile als eigener Wert behandelt.",
  "pageText.49b68226": "Was ist URL-Codierung?",
  "pageText.5cd6b8f1": "Prozentcodierung stellt ein UTF-8-Byte als % gefolgt von zwei Hexadezimalziffern dar. Sie wird verwendet, wenn ein Zeichen in einem bestimmten URI-Teil nicht sicher direkt stehen kann.",
  "pageText.a2c17b54": "Sollte ich eine Komponente oder eine vollständige URL codieren?",
  "pageText.5905cd6b": "Verwenden Sie den Komponentenmodus für einen einzelnen Abfragewert, Pfadabschnitt oder Fragmentwert, da er auch Trennzeichen wie &, =, / und ? maskiert. Verwenden Sie den Modus für vollständige URLs, wenn die Eingabe bereits eine ganze URL enthält und deren strukturelle Trennzeichen lesbar bleiben müssen.",
  "pageText.f176d778": "Warum scheitert die Decodierung manchmal?",
  "pageText.231a3849": "Auf ein Prozentzeichen müssen zwei Hexadezimalziffern folgen; die resultierende Bytefolge muss decodierbar sein. Unvollständige Sequenzen wie %2 oder fehlerhaftes UTF-8 werden abgelehnt, statt unbemerkt verändert zu werden.",
  "pageText.a85f9468": "Was der URL-Codierer ändert",
  "pageText.62d7dab2": "Der Komponentenmodus verwendet das Browserverhalten von encodeURIComponent und decodeURIComponent. Er eignet sich für einzelne Abfragewerte oder Pfadabschnitte, da reservierte URL-Trennzeichen als Daten codiert werden. Der Modus für vollständige URLs verwendet encodeURI und decodeURI. Diese erhalten Strukturzeichen wie :, /, ?, #, & und =, damit eine bereits zusammengesetzte URL ihre Struktur behält.",
  "pageText.e84e968c": "Durchgerechnetes Prozentcodierungsbeispiel",
  "pageText.d6bede20": "Die Codierung der Komponente \"hello world&role=admin\" ergibt hello%20world%26role%3Dadmin. Würde derselbe Text ohne Komponentencodierung in eine Abfragezeichenfolge eingefügt, könnten das kaufmännische Und und das Gleichheitszeichen als neue Abfrageparameter statt als Teil des Werts interpretiert werden. Der Stapelmodus wendet die gewählte Operation unabhängig auf jede nicht leere Eingabezeile an.",
  "pageText.d69c3bf2": "Grenzen und Datenschutz",
  "pageText.66960492": "Dies ist URI-Prozentcodierung, keine application/x-www-form-urlencoded-Serialisierung. Formularcodierer stellen Leerzeichen häufig als + dar und wenden feldbezogene Regeln an.",
  "pageText.fb49cce2": "Die Decodierung prüft nicht, ob das Ergebnis eine sichere, erreichbare oder vertrauenswürdige URL ist. Validieren Sie Schemes, Hosts und Weiterleitungsziele separat.",
  "pageText.7ebaf6d4": "Codieren Sie einen bereits codierten Wert nicht wiederholt, sofern keine doppelte Codierung beabsichtigt ist; % kann zu %25 werden.",
  "pageText.5bdbc315": "Die Konvertierung läuft im Browser. Zwischenablageverlauf, Erweiterungen, gemeinsam genutzte Geräte und alle Ziele, in die Sie das Ergebnis einfügen, bleiben eigene Offenlegungswege.",
  "pageText.d1225e2e": "Beweist das Decodieren, dass ein JWT echt ist?",
  "pageText.154670ea": "Nein. Jeder kann Header und Payload mit Base64URL codieren. Die Echtheit steht erst fest, nachdem ein zugelassener Algorithmus mit dem richtigen Schlüssel verifiziert wurde und jede erforderliche Claim-Prüfung erfolgreich war.",
  "pageText.06daf1d8": "Welche JWT-Algorithmen kann diese Seite signieren und prüfen?",
  "pageText.50e5fffd": "Sie unterstützt die HMAC-Algorithmen HS256, HS384 und HS512 mit einem Textgeheimnis. Sie lehnt alg:none bewusst ab und akzeptiert keine RSA-, ECDSA-, EdDSA-, JWK-, JWKS- oder Zertifikatsschlüssel.",
  "pageText.d4ee3edc": "Werden Tokens und Geheimnisse hochgeladen?",
  "pageText.f21783fe": "Nein. Decodierung, Web-Crypto-HMAC-Signierung und Signaturprüfung laufen im Browser. Bearer-Tokens und Geheimnisse bleiben durch Zwischenablageverlauf, Erweiterungen, Bildschirmfreigaben und gemeinsam genutzte Geräte gefährdet. Verwenden Sie deshalb synthetische Daten.",
  "pageText.e5b685cb": "Decodieren, Prüfen und Signieren sind getrennte Vorgänge",
  "pageText.d5099b0a": "Decodieren teilt ein kompaktes Token in drei Teile und liest JSON-Header sowie Claims, ohne ihnen zu vertrauen. Prüfen wählt HS256, HS384 oder HS512 aus dem geschützten Header, prüft die genaue Signatureingabe mit Web Crypto und wertet danach exp, nbf, iat sowie optionale Issuer- oder Audience-Vorgaben aus. Signieren serialisiert die angegebenen JSON-Objekte, überschreibt header.alg mit dem gewählten HMAC-Algorithmus und erzeugt ein kompaktes JWS für Tests.",
  "pageText.1305057d": "Prüfregeln und Hinweise zur Fehlersuche",
  "pageText.7576ed65": "Eine gültige HMAC-Signatur beweist, dass der Signierende dasselbe Geheimnis hatte; sie beweist nicht, dass es sicher gespeichert oder verteilt wurde.",
  "pageText.6e0c0a9d": "Das Token wird abgelehnt, wenn sein Header alg auslässt, none auswählt oder einen nicht unterstützten asymmetrischen Algorithmus verlangt.",
  "pageText.caeba6bd": "Ablaufzeit, Gültigkeitsbeginn und Ausstellungszeitpunkt müssen endliche NumericDate-Werte in Sekunden sein; die Zeitabweichung kann zwischen null und 300 Sekunden liegen.",
  "pageText.b69c111a": "Der optionale Issuer-Abgleich ist exakt. Der Audience-Abgleich akzeptiert den erwarteten Wert entweder als aud-Zeichenfolge oder als einen Eintrag in einem aud-Array.",
  "pageText.45928def": "Autorisierungs-Claims wie Rollen und Scopes werden angezeigt, sind jedoch anwendungsspezifisch und werden von dieser Seite nicht ausgewertet.",
  "pageText.9f727ee8": "Sicherheits- und Interoperabilitätsgrenze",
  "pageText.79b6492c": "Ein Produktiv-Verifier sollte seinen erlaubten Algorithmus unabhängig konfigurieren, Schlüssel aus einer vertrauenswürdigen Issuer-Konfiguration wählen, alle Anwendungs-Claims durchsetzen, Geheimnisse rotieren und Regeln gegen Wiederholung oder für Widerruf berücksichtigen. Diese Seite entschlüsselt kein JWE, löst keine JWK- oder JWKS-Dokumente auf, validiert keine Zertifikate und bildet keine bibliotheksspezifische JSON-Serialisierung nach. Erzeugen Sie Produktiv-Tokens nur im vertrauenswürdigen Identitätssystem, dem der Schlüssel gehört.",
  "pageText.269f9532": "Was sind HTML-Entities?",
  "pageText.1998740e": "HTML-Entities sind besondere Codes zur Darstellung reservierter Zeichen in HTML. Beispielsweise steht &lt; für < und &amp; für &.",
  "pageText.b89e0526": "Warum HTML-Entities codieren?",
  "pageText.1529343a": "Die Codierung reservierter Zeichen kann verhindern, dass Text in einem HTML-Textkontext als Markup interpretiert wird. Sie ist keine vollständige XSS-Abwehr: Attribute, URLs, CSS, JavaScript und nicht vertrauenswürdiges HTML benötigen kontextspezifisches Escaping oder Bereinigung.",
  "pageText.047ad07a": "Welche Entity-Formate kann dieses Tool decodieren?",
  "pageText.8c48f80f": "Es decodiert vom Browser erkannte benannte Referenzen wie &amp;, dezimale Zahlenreferenzen wie &#169; und hexadezimale Referenzen wie &#xA9;.",
  "pageText.1f92ff4e": "Ist dies dasselbe wie ein HTML-Entity-Konverter?",
  "pageText.2bce97a1": "Ja. Dieses Tool codiert und decodiert HTML-Entities; es gibt daher keinen eigenen HTML-Entity-zu-Unicode-Konverter. Aktivieren Sie die erweiterte Option, um dezimale Zeichenreferenzen für Nicht-ASCII-Text auszugeben. Die Decodierung löst auch hexadezimale Referenzen auf.",
  "pageText.787f2f9a": "Was der HTML-Entity-Decodierer und -Codierer macht",
  "pageText.a65d3d26": "HTML-Zeichenreferenzen stellen Zeichen dar, die im Markup sonst mehrdeutig wären. Der Codierer ersetzt reservierte Zeichen wie das kaufmännische Und, Kleiner- und Größerzeichen, Anführungszeichen und Apostrophe. Seine erweiterte Option gibt auch dezimale Referenzen für Nicht-ASCII-Zeichen aus. Der Decoder löst benannte, dezimale und hexadezimale Referenzen mit dem HTML-Parser des Browsers auf.",
  "pageText.a4c17b02": "HTML-Entity-Beispiele",
  "pageText.6b1cb488": "&lt; wird zum Kleinerzeichen und &gt; zum Größerzeichen.",
  "pageText.656db619": "&amp; wird zum kaufmännischen Und und &quot; zum Anführungszeichen.",
  "pageText.b1f980f4": "&#169; und &#xA9; sind dezimale und hexadezimale Referenzen für das Copyrightzeichen.",
  "pageText.4a4bcadc": "Die Codierung von <p>Research & Development</p> erzeugt Text, der als Markup-Zeichen angezeigt werden kann, statt als dasselbe Element geparst zu werden.",
  "pageText.761ca2d4": "Sicherheits- und Darstellungsgrenzen",
  "pageText.b3511bac": "Entity-Codierung ist kontextabhängig. Das Escaping von Text für einen HTML-Textknoten macht denselben Wert nicht innerhalb eines Eventhandlers, einer URL, CSS-Deklaration, JavaScript-Zeichenfolge oder eines beliebigen HTML-Fragments sicher. Verwenden Sie standardmäßig das Escaping Ihres Frameworks und eine gepflegte Bereinigungsbibliothek, wenn vertrauenswürdige Formatierung erhalten bleiben muss. Die Decodierung nicht vertrauenswürdiger Entities sollte Text zur Untersuchung erzeugen und keinen Anlass bieten, das Ergebnis mit innerHTML einzufügen.",
  "pageText.29803de0": "Was ist Hexadezimalcodierung?",
  "pageText.debeda5a": "Hexadezimalcodierung stellt UTF-8-Bytes in Basis-16-Notation dar (0–9, A–F).",
  "pageText.3cde0e22": "Codieren Sie ~ als ~0 und / als ~1 innerhalb eines Tokens. Decodieren Sie zuerst ~1 zu / und danach ~0 zu ~, wie RFC 6901 verlangt.",
  "pageText.e26f9f25": "Wie verwende ich dieses Tool?",
  "pageText.0eb45c63": "Geben Sie Text in das Eingabefeld ein; er wird automatisch in Hexadezimaldarstellung umgewandelt. Sie können auch Hexwerte einfügen, um sie wieder in Text zu decodieren.",
  "pageText.8d56b3f0": "Was ist Binärcodierung?",
  "pageText.1fefb654": "Binärcodierung stellt UTF-8-Bytes in Basis-2-Notation dar und verwendet nur Nullen und Einsen.",
  "pageText.e0fbf5c5": "Wie viele Bits hat ein Zeichen?",
  "pageText.a3c61b13": "Jedes UTF-8-Byte wird durch acht Bits dargestellt. ASCII-Zeichen verwenden ein Byte; Zeichen wie Buchstaben mit Akzenten oder Emojis können mehrere Bytes benötigen.",
  "pageText.6f9da256": "Kann ich Binärwerte wieder in Text umwandeln?",
  "pageText.6e36ed1b": "Ja. Der Decodiermodus akzeptiert vollständige 8-Bit-Binärbytes mit optionalem Leerraum zwischen Gruppen und wandelt gültige UTF-8-Bytes wieder in Text um.",
  "pageText.a76ed5ae": "Was macht dieser Binärcodierer und -decodierer?",
  "pageText.208a45fa": "Dieses Tool wandelt Text in die Binärdarstellung seiner UTF-8-Bytes um und decodiert Binärbytes wieder in Text. Jede Ausgabegruppe enthält acht Bits. Leerzeichen zwischen Bytegruppen machen das Ergebnis lesbar und können beim Decodieren entfernt oder beibehalten werden. Die Konvertierung läuft im Browsercode; der Text muss daher zur Verarbeitung nicht hochgeladen werden.",
  "pageText.f49b8901": "Text-zu-Binär-Beispiele",
  "pageText.3a3355ac": "Der Buchstabe A ist das UTF-8-Byte 65 und wird deshalb zu 01000001. Das Zeichen é verwendet die beiden UTF-8-Bytes C3 und A9; seine Binärform lautet daher 11000011 10101001. Dieser Unterschied ist wichtig: Das Tool stellt codierte Bytes dar, nicht einen festen 8-Bit-Wert für jedes sichtbare Zeichen.",
  "pageText.0288b438": "Binäre Textcodierung unterscheidet sich vom Umrechnen einer Dezimalzahl in Basis 2. Die Texteingabe 10 codiert die Zeichen 1 und 0 als zwei UTF-8-Bytes. Verwenden Sie den Zahlenbasiskonverter, wenn Sie Zahlen zwischen Basen umrechnen möchten.",
  "pageText.19833ccd": "Validierung bei Binär-zu-Text",
  "pageText.58060cff": "Der Decodiermodus ignoriert Leerraum zwischen Gruppen, verlangt aber ausschließlich die Ziffern 0 und 1 sowie eine vollständige Anzahl von 8-Bit-Bytes. Unvollständige Bytes, andere Zeichen oder nicht gültige UTF-8-Bytefolgen erzeugen einen Fehler statt eines irreführenden Teilergebnisses.",
  "pageText.49543137": "Binärcodierung ist eine Darstellung, keine Verschlüsselung oder Komprimierung. Jeder mit den Binärbytes kann sie decodieren; die Bitzeichenfolge kann länger als der ursprünglich sichtbare Text sein.",
  "pageText.c90dd9ea": "Was ist eine Base64-Daten-URI?",
  "pageText.39ff7dd5": "Eine Daten-URI bettet Dateiinhalte direkt in HTML oder CSS ein, in der Form data:image/png;base64,<encoded bytes>. Der Browser decodiert sie an Ort und Stelle; das Bild benötigt somit keine eigene HTTP-Anfrage.",
  "pageText.bae37a7c": "Wann sollte ich Base64-Bilder verwenden?",
  "pageText.4baed32c": "Für kleine Icons, winzige Platzhalter und Demos in einer einzelnen Datei. Größere Bilder sollten als normale Dateien bereitgestellt werden, da Base64 die Größe um etwa 33 % erhöht und eingebettete Bilder nicht separat gecacht werden können.",
  "pageText.fd65cb89": "Warum ist die Base64-Zeichenfolge größer als meine Bilddatei?",
  "pageText.dc1302a7": "Base64 stellt je drei Bytes mit vier Zeichen dar; die Ausgabe ist daher etwa ein Drittel größer als die Datei. Das Tool zeigt Original- und Base64-Größe an, damit Sie beurteilen können, ob sich das Einbetten lohnt.",
  "pageText.44cee614": "Welche Bildformate werden unterstützt?",
  "pageText.690da2e0": "Jede Datei, die Ihr Browser mit einem image/*-MIME-Typ erkennt, einschließlich PNG, JPEG, GIF, WebP und SVG. Weitere Formate wie AVIF oder ICO funktionieren, wenn der Browser dafür einen Bildtyp meldet. Dateien ohne Bildtyp werden abgelehnt.",
  "pageText.4f220e7a": "Wie wandle ich Base64 wieder in ein Bild um?",
  "pageText.86d8a616": "Verwenden Sie das Tool „Base64 zu Bild“ oder schreiben Sie die Bytes in Node.js mit fs.writeFileSync('image.png', Buffer.from(base64String, 'base64')) auf die Festplatte.",
  "pageText.0472d6fa": "Wird mein Bild auf einen Server hochgeladen?",
  "pageText.b951075e": "Nein. Die Datei wird mit der FileReader-API des Browsers gelesen und auf Ihrem Gerät codiert. Es wird nichts an einen Server gesendet.",
  "pageText.8d3141eb": "Daten-URI und reines Base64 im Vergleich",
  "pageText.441f0d6b": "Eine Daten-URI fasst MIME-Typ und codierte Bytes zu einer Zeichenfolge zusammen, die Browser überall akzeptieren, wo eine URL erwartet wird, etwa data:image/png;base64,iVBORw0KGgo... Die Base64-Option entfernt das Präfix data:image/png;base64, und gibt nur die codierten Bytes zurück. Das erwarten die meisten JSON-APIs, Datenbanken und Upload-Endpunkte, wenn der Inhaltstyp in einem eigenen Feld gespeichert wird. Der MIME-Typ der Daten-URI stammt aus dem Dateityp, den Ihr Browser für die ausgewählte Datei meldet.",
  "pageText.9c060b5e": "Das Ergebnis einbetten",
  "pageText.92456569": "HTML: <img src=\"data:image/png;base64,...\" alt=\"Logo\" width=\"32\" height=\"32\">. Verwenden Sie wie bei jedem Bild aussagekräftigen Alternativtext und explizite Maße.",
  "pageText.56968f15": "CSS: background-image: url(\"data:image/png;base64,...\"); mit der Daten-URI in Anführungszeichen.",
  "pageText.d617fb16": "JSON: Die reine Base64-Zeichenfolge neben einem contentType-Feld speichern und auf dem Server decodieren.",
  "pageText.693f282c": "Markdown: ![alt](data:image/png;base64,...) funktioniert in manchen Renderern. Viele gehostete Plattformen blockieren jedoch Daten-URIs in Markdown. Testen Sie deshalb die spätere Darstellung.",
  "pageText.f8d06727": "Wann Base64-Bilder helfen und wann sie schaden",
  "pageText.1e364f5e": "Die Codierung vergrößert die Daten um etwa 33 %. Ein eingebettetes Bild kann außerdem nicht separat gecacht werden: Es wird erneut heruntergeladen, sobald sich die enthaltende HTML- oder CSS-Datei ändert, und verlangsamt deren Parsing. Einbetten lohnt sich bei sehr kleinen Ressourcen wie Icons, 1×1-Platzhaltern oder eigenständigen Demoseiten. Für Fotos und alles über wenigen Kilobytes ist eine normale Bilddatei mit Cache-Headern meist schneller. Bei SVG ist eine URL-codierte Daten-URI oft kürzer als Base64; das Tool „SVG zu CSS-Daten-URI“ erzeugt eine solche.",
  "pageText.e43aa790": "Was mit Ihrer Datei geschieht",
  "pageText.c4f14710": "Die Datei wird genau so codiert, wie sie gespeichert ist. Es gibt keine Größenänderung, Neukomprimierung oder Metadatenentfernung. EXIF-Daten eines JPEGs wie Kameradetails oder GPS-Koordinaten gehen daher in die Base64-Zeichenfolge ein. Komprimieren Sie das Bild oder entfernen Sie seine Metadaten vorher, wenn dies relevant ist. Es wird jeweils eine Datei konvertiert; sehr große Bilder erzeugen sehr lange Zeichenfolgen, die das Scrollen oder Kopieren verlangsamen können.",
  "pageText.49b261c7": "Was ist Unicode-Escaping?",
  "pageText.80d28e8d": "Unicode-Escaping stellt Zeichen durch hexadezimale Codepunkte dar, etwa \\u0041 für \"A\".",
  "pageText.6d708618": "Kann ich Unicode-Escape-Sequenzen online decodieren?",
  "pageText.a4bd1758": "Ja. Text mit unterstützten Sequenzen wie \\uXXXX, \\u{XXXXX} oder \\xFF einfügen und „Decodieren“ wählen. Das Tool ersetzt diese Sequenzen lokal in Ihrem Browser durch ihre Zeichen.",
  "pageText.cb96dafd": "Ist dies dasselbe wie das Entfernen von JSON-Escape-Zeichen?",
  "pageText.e061f024": "Nein. Dieses Tool behandelt hexadezimale Unicode- und Byte-Escape-Sequenzen. Verwenden Sie das JSON-String-Escape-Tool, wenn auch JSON-Escapes wie \\n, \\t, maskierte Anführungszeichen oder Backslashes als vollständiges JSON-Zeichenfolgenfragment verarbeitet werden sollen.",
  "pageText.b78ece8c": "Was macht dieser Unicode-Escape-Decodierer?",
  "pageText.66907eae": "Der Decoder wandelt erkannte hexadezimale Escape-Sequenzen in lesbare Zeichen um. Er unterstützt vierstellige Werte im JavaScript-Stil wie \\u0041, Codepunkte in geschweiften Klammern wie \\u{1F600} und zweistellige Bytewerte wie \\x41. Anderer Text bleibt unverändert; das Ergebnis lässt sich deshalb vor dem Kopieren leicht untersuchen.",
  "pageText.8b33e053": "Beispiele für Unicode-Escape-Codierung",
  "pageText.2a71ff3b": "Bei aktiviertem ASCII-Escaping wird A zu \\u0041. Zeichen oberhalb der grundlegenden mehrsprachigen Ebene verwenden Codepunkte in geschweiften Klammern; beispielsweise wird 😀 zu \\u{1F600}. Bei deaktiviertem ASCII-Escaping bleibt gewöhnlicher ASCII-Text lesbar, während Nicht-ASCII-Zeichen maskiert werden.",
  "pageText.f75a70a6": "Unicode-Escaping ändert die Schreibweise von Zeichen, nicht ihre Bedeutung. Es hilft beim Untersuchen von Protokollen, Quellcode, API-Nutzdaten oder kopiertem Text, der Escape-Notation statt dargestellter Zeichen enthält.",
  "pageText.715d4ec7": "Unicode-Escapes in JavaScript und Python decodieren",
  "pageText.25c67af7": "Für einen vollständigen JSON-Zeichenfolgenwert verwenden Sie JSON.parse() in JavaScript oder json.loads() in Python. Beide verarbeiten vierstellige JSON-Unicode-Escapes und Surrogatpaare. JSON akzeptiert weder JavaScript-Escapes in geschweiften Klammern noch \\xXX-Notation; der Online-Decoder unterstützt diese getrennten Textdarstellungen.",
  "pageText.dfad767c": "Die Beispiele erhalten Backslashes bis zum Parsing wörtlich und geben Aé😀 aus. Verwenden Sie niemals eval() zum Decodieren externer Eingaben. Ein JSON-Dokument sollte entsprechend seinem Quellformat einmal geparst werden, statt Escape-Sequenzen wiederholt zu ersetzen.",
  "pageText.b78d8193": "Unicode-Escapes, JSON und Sicherheit",
  "pageText.ec7ecc8b": "Dieser Konverter ist kein vollständiger Programmiersprachenparser. Er ersetzt die unterstützten hexadezimalen Muster, interpretiert aber nicht jede Escape-Regel aus JSON, JavaScript, regulären Ausdrücken oder Shellsyntax. Verwenden Sie einen formatspezifischen Parser, wenn eine genaue Dokumentvalidierung benötigt wird.",
  "pageText.d400aec2": "Codierung ist keine Verschlüsselung: Jeder kann einen maskierten Wert decodieren. Die Verarbeitung läuft im Browsercode. Dennoch sollten Sie keine Geheimnisse in Online-Tools eingeben, sofern die Ausführungsumgebung nicht für die Daten geeignet ist.",
  "pageText.06d6ceab": "Was bewirkt JSON-Zeichenfolgen-Escaping?",
  "pageText.a236a523": "Es wandelt Sonderzeichen wie Zeilenumbrüche, Tabulatoren und Anführungszeichen in Escape-Formen wie \\n, \\t und \\\" um.",
  "pageText.b5b32ac6": "Wann ist das nützlich?",
  "pageText.9758a1c9": "Wenn Sie Zeichenfolgen sicher in JSON-Nutzdaten, Konfigurationsdateien oder API-Anfragen einbetten müssen.",
  "pageText.23c25e0a": "Unterstützt dieses Tool reines Base64 und Daten-URI-Präfixe?",
  "pageText.47a7ae5b": "Ja. Sie können reine Base64-Zeichenfolgen (beginnend mit iVBORw0KGgo... oder /9j/...) oder vollständige data:image/png;base64,...-URIs einfügen.",
  "pageText.3e22ce2a": "Werden meine Bilder auf einen Server hochgeladen?",
  "pageText.ff8327d4": "Nein. Decodierung und Bilddarstellung laufen vollständig in Ihrem Browser mit clientseitigen Daten-URLs und Blobs.",
  "pageText.b5c81ec6": "Welches Format sollte die Hexeingabe haben?",
  "pageText.4df53de7": "Eine hexadezimale Zeichenfolge gerader Länge (z. B. 48656c6c6f), mit oder ohne Leerzeichen und Präfixe.",
  "pageText.0d4f669a": "Funktioniert die Konvertierung in beide Richtungen?",
  "pageText.448de195": "Ja! Sie können Hex in Base64 und Base64 in Hex ohne Datenverlust umwandeln.",
  "pageText.5a849fdb": "Wofür wird Base32-Codierung verwendet?",
  "pageText.300b948f": "Base32 verwendet ein Alphabet mit 32 Zeichen (A–Z, 2–7), ist unabhängig von Groß-/Kleinschreibung und vermeidet visuell mehrdeutige Zeichen. Es wird häufig für geheime 2FA-TOTP-Schlüssel und von Menschen eingegebene Verifizierungscodes verwendet.",
  "pageText.11274fca": "Was sind strukturierte JSON-LD-Daten?",
  "pageText.930ded68": "JSON-LD ist ein von Google empfohlenes Standardformat, um explizite Informationen über eine Seite bereitzustellen und ihren Inhalt für erweiterte Suchergebnisse einzuordnen.",
  "pageText.c2c8dd70": "Wie füge ich das erzeugte Schema meiner Website hinzu?",
  "pageText.beba7ce9": "Das erzeugte <script type=\"application/ld+json\">-Tag kopieren und in den HTML-<head>- oder <body>-Bereich einfügen.",
  "pageText.86ec75d3": "Bleiben meine Daten privat und geschützt?",
  "pageText.b25ac842": "Ja, die gesamte Verarbeitung läuft lokal in Ihrem Browser ohne Serverspeicherung.",
  "pageText.687b5867": "Was ist der zeitlich sortierte UUID-v7-Generator?",
  "pageText.c8e48ee7": "Zeitlich sortierte UUID-v7-Kennungen mit sicherer Browserzufälligkeit erzeugen und als Text exportieren. Das verknüpfte Tool zur UUID-v7-Zeitstempelextraktion liest die eingebettete Erstellungszeit einer Kennung.",
  "pageText.611de2a2": "Was ist eine UUID?",
  "pageText.e747103f": "UUID (Universally Unique Identifier) ist eine 128-Bit-Kennung, die ohne zentrale Vergabestelle weltweit eindeutig sein soll.",
  "pageText.5e3c112b": "Was ist UUID v4?",
  "pageText.7697e800": "UUID Version 4 wird zufällig erzeugt. Sie hat 122 Zufallsbits und sechs Bits für Versions- und Varianteninformationen.",
  "pageText.5e39d294": "Was ist UUID v7?",
  "pageText.66a6ed70": "UUID Version 7 beginnt mit einem 48-Bit-Unix-Zeitstempel in Millisekunden und verwendet weitere 74 Bits für Zufallsdaten. Werte mit zunehmenden codierten Zeitstempeln lassen sich chronologisch sortieren. Werte derselben Millisekunde sind jedoch zufällig; eine rückwärts gerichtete Systemuhrkorrektur kann die Erzeugungsreihenfolge umkehren.",
  "pageText.7a44e8ee": "Sollte ich UUID v4 oder v7 wählen?",
  "pageText.83965de1": "Wählen Sie v4 für eine undurchsichtige zufällige Kennung. Wählen Sie v7, wenn zeitliche Nähe und chronologische Datenbankindizierung hilfreich sind. Keine der Versionen sollte als Geheimnis behandelt werden.",
  "pageText.9a6b439e": "Sind die erzeugten UUIDs kryptografisch zufällig?",
  "pageText.4a129bc3": "Die Browser-Kryptografie-API liefert die 122 Zufallsbits von UUID v4 und die 74 zufälligen Nutzdatenbits von UUID v7. UUID v7 legt außerdem die Erstellungsmillisekunde offen. UUIDs sind daher Kennungen, keine Passwörter oder Tokens.",
  "pageText.35cc78ac": "Was dieser UUID-v4- und UUID-v7-Generator macht",
  "pageText.361a3991": "Dieser Generator erzeugt UUIDs der Version 4 oder 7 nach RFC 9562 vollständig im Browser. Version 4 verwendet 122 kryptografische Zufallsbits. Version 7 speichert die aktuelle Unix-Millisekunde in den ersten 48 Bits und füllt die übrigen 74 Nutzdatenbits aus crypto.getRandomValues(). Beide setzen die RFC-Versions- und Variantenfelder und verwenden die kanonische hexadezimale Struktur 8-4-4-4-12.",
  "pageText.cf240c55": "UUIDs in JavaScript und Python erzeugen",
  "pageText.6ef9489b": "JavaScript crypto.randomUUID() erzeugt UUID v4 in sicheren Browserkontexten. Python uuid.uuid4() erzeugt ebenfalls v4-IDs; uuid.uuid7() ist ab Python 3.14 in der Standardbibliothek verfügbar. Die folgenden Beispiele prüfen die Python-v7-Unterstützung, statt ihre Verfügbarkeit vorauszusetzen.",
  "pageText.42f8fbc7": "Verschiedene UUID-v7-Generatoren können IDs innerhalb einer Millisekunde unterschiedlich ordnen. Dieses Browsertool verwendet einen zufälligen Endteil; Pythons Implementierung verwendet einen Zähler. Behalten Sie eine Eindeutigkeitsbedingung in der Datenbank bei und verwenden Sie eine Kennung nicht als Autorisierungsnachweis.",
  "pageText.3368e346": "v4 oder v7 wählen",
  "pageText.5b192e0e": "UUID v4 eignet sich für eine undurchsichtige zufällige Kennung ohne Zeitstempel. UUID v7 eignet sich, wenn Datensätze chronologisch nach ihrer Erstellungsmillisekunde gruppiert werden sollen; dies kann die Indexlokalität gegenüber zufälligen v4-Werten verbessern. Die Reihenfolge folgt dem codierten Uhrwert: Zufällige Endteile derselben Millisekunde sind nicht strikt geordnet, und eine rückwärts gerichtete Systemuhrkorrektur kann die Erzeugungsreihenfolge umkehren.",
  "pageText.19989f5d": "Stapelweise Formatierung und Export",
  "pageText.d012108b": "1 bis 1.000 Werte erzeugen, Hexbuchstaben großschreiben, Bindestriche entfernen oder jeden Wert für GUID-Arbeitsabläufe in geschweifte Klammern einschließen. Das zeilenweise getrennte Ergebnis kopieren oder denselben Stapel als UTF-8-Textdatei herunterladen.",
  "pageText.4c38dc5a": "Datenbank- oder Anwendungskennungen ohne Abstimmung eines zentralen Zählers erstellen.",
  "pageText.ce17c126": "Testvorgaben, simulierte API-Antworten und Beispieldatensätze füllen.",
  "pageText.138b9843": "Korrelations-IDs an Anfragen, Jobs, Protokolle oder Nachrichten anhängen.",
  "pageText.5d4cb8de": "Bereiten Sie kleine Stapel für Importe, Prototypen und die lokale Entwicklung vor.",
  "pageText.1193c111": "Formatbeispiele",
  "pageText.d40026dd": "Ein v4-Ergebnis kann etwa 3f2504e0-4f89-41d3-9a0c-0305e82c3301 lauten; ein v7-Ergebnis enthält dagegen 7 als Versionsnibble, zum Beispiel 0190b0cc-4f71-7a8e-9c9a-6a74fbb21a92. Die Optionen für Großbuchstaben, das Weglassen von Bindestrichen und geschweifte Klammern ändern nur die Darstellung. Nachgelagerte Parser verlangen möglicherweise die kanonische Form mit Kleinbuchstaben und Bindestrichen.",
  "pageText.9dbfc526": "Die Eindeutigkeit von UUIDs beruht auf Wahrscheinlichkeiten; dieser Generator prüft kein Register und garantiert keine Eindeutigkeit. Eine UUID v7 gibt ihre Erstellungszeit in Millisekunden preis. Die Sortierung nach Erstellungsreihenfolge setzt voraus, dass die Systemuhr beim Generieren nicht zurückgeht; innerhalb derselben Millisekunde erzeugte Zufallswerte sind nicht streng monoton. Eine UUID ist eine Kennung und damit nicht automatisch ein Passwort, API-Schlüssel oder Sitzungstoken. Die Generierung erfolgt lokal im Browser. Alles, was Sie kopieren, einfügen, herunterladen, übertragen oder speichern, wird vom jeweils gewählten Ziel verarbeitet.",
  "pageText.7a6710aa": "Wie stark sollte mein Passwort sein?",
  "pageText.9be86c1e": "Verwenden Sie möglichst ein einzigartiges Passwort, das ein Passwortmanager erzeugt und speichert. Mindestens sechzehn zufällige Zeichen aus einem umfangreichen Zeichenvorrat oder eine zufällige Passphrase aus mindestens sechs Wörtern sind ein praktischer Ausgangspunkt, sofern das Zielsystem sie akzeptiert. Die Anforderungen einzelner Konten können davon abweichen.",
  "pageText.0f3affb1": "Wie werden Zufallswerte erzeugt?",
  "pageText.e7090e3e": "Der Generator verwendet crypto.getRandomValues mit Rejection Sampling, nicht Math.random. Im Modus für zufällige Zeichen enthält das Ergebnis mindestens ein Zeichen aus jedem gewählten Zeichensatz, sofern die gewünschte Länge dies zulässt. Anschließend wird die Reihenfolge sicher zufällig gemischt.",
  "pageText.db182e45": "Werden erzeugte Passwörter hochgeladen oder gespeichert?",
  "pageText.7daed653": "Nein. Generierung und Entropieschätzung erfolgen lokal; die App speichert den erzeugten Wert nicht. Beim Kopieren kann er dennoch im Verlauf der Betriebssystem-Zwischenablage landen. Erweiterungen können Seiteninhalte beobachten, und gemeinsam genutzte Geräte erfordern besondere Vorsicht.",
  "pageText.8c8e3b19": "So funktioniert die sichere Passwortgenerierung",
  "pageText.567ac86d": "Der Modus für zufällige Zeichen wählt mit dem kryptografischen Zufallszahlengenerator des Browsers aus den aktivierten Kleinbuchstaben, Großbuchstaben, Ziffern und Symbolen. Rejection Sampling vermeidet Modulo-Verzerrungen. Im Passphrasenmodus wird jedes Wort unabhängig aus der langen EFF-Wortliste ausgewählt. Dieser Modus unterstützt sechs bis zwölf Wörter mit einem frei gewählten Trennzeichen.",
  "pageText.296f3bc2": "Passwort oder Passphrase wählen",
  "pageText.926afe7a": "Verwenden Sie für jedes Konto einen einzigartigen Wert. Durch wiederverwendete Passwörter kann ein einziges Datenleck Zugriff auf mehrere Dienste ermöglichen.",
  "pageText.f3d81905": "Wählen Sie möglichst den längsten Wert, den das Zielsystem zuverlässig unterstützt. Die Länge trägt meist mehr zur Sicherheit bei als vorhersehbare Ersetzungen wie a durch @.",
  "pageText.01bfc425": "Verwenden Sie den Passphrasenmodus, wenn Sie den Wert eintippen oder vorlesen müssen, und den Modus für zufällige Zeichen, wenn ein Passwortmanager ihn speichert und automatisch einfügt.",
  "pageText.27fbadfc": "Aktivieren Sie, sofern verfügbar, die Mehrfaktor-Authentifizierung, insbesondere für E-Mail-, Finanz-, Cloud- und Administratorkonten.",
  "pageText.1bede603": "Entropieschätzung und Grenzen des Datenschutzes",
  "pageText.23ca65c7": "Die angezeigte Entropie ist eine theoretische Schätzung auf Grundlage unabhängiger, gleichverteilter Entscheidungen aus dem gewählten Zeichenvorrat oder der Wortliste. Sie ist keine Zusage über die Zeit zum Knacken und berücksichtigt keinen kompromittierten Browser, kein kompromittiertes Gerät und keine kompromittierte Zwischenablage, keinen Passwortmanager, Zieldienst oder Wiederherstellungsprozess. Der Generator gleicht Passwörter nicht mit Datenbanken bekannter Datenlecks ab, da dafür ein gesondertes Konzept für datenschutzfreundliche Abfragen erforderlich wäre.",
  "pageText.293386a3": "Was ist Lorem Ipsum?",
  "pageText.e7e9a310": "Lorem ipsum ist lateinisch wirkender Platzhaltertext, der in Grafikdesign, Webdesign und Verlagswesen Flächen füllt, bevor der eigentliche Inhalt vorliegt.",
  "pageText.fc868312": "Warum verwendet man Lorem Ipsum?",
  "pageText.fc0c8095": "Die natürlich wirkende Mischung aus kurzen und langen Wörtern zeigt, wie ein Layout mit echtem Text umgeht, ohne die Leser durch dessen Inhalt abzulenken.",
  "pageText.fc9ee235": "Was bedeutet lorem ipsum?",
  "pageText.42643988": "In dieser Form nichts. Es ist ein veränderter Auszug aus Ciceros De finibus bonorum et malorum, in dem „dolorem ipsum“ „den Schmerz selbst“ bedeutet. Wörter wurden gekürzt und verändert; deshalb ist „Lorem“ kein echtes lateinisches Wort.",
  "pageText.864e8e98": "Wie lang ist jeder erzeugte Absatz?",
  "pageText.da65818f": "Jeder Absatz besteht aus 3 bis 7 Sätzen mit jeweils 5 bis 15 Wörtern, also ungefähr 15 bis 105 Wörtern pro Absatz. Verwenden Sie den Wortmodus, wenn Sie eine genaue Wortzahl benötigen.",
  "pageText.e4695071": "Kann ich Lorem Ipsum mit HTML-Tags erzeugen?",
  "pageText.a44e126f": "Die Ausgabe ist reiner Text; zwischen Absätzen steht eine Leerzeile. Setzen Sie jeden Absatz selbst in <p>-Tags, wenn Sie ihn in HTML einfügen.",
  "pageText.2fc5f8d2": "Woher Lorem Ipsum stammt",
  "pageText.372fc06e": "Lorem ipsum stammt aus De finibus bonorum et malorum, einer Abhandlung über Ethik, die Cicero 45 v. Chr. verfasste. Der bekannte Anfang Lorem ipsum dolor sit amet, consectetur adipiscing elit stammt aus einem Abschnitt, der mit Neque porro quisquam est qui dolorem ipsum quia dolor sit amet beginnt. Wörter wurden gekürzt, verändert und umgestellt, sodass das Ergebnis wie Latein aussieht, aber nichts bedeutet. Schriftsetzer und Designer verwenden seit Jahrzehnten Varianten als Blindtext, weil die Wortlängen einen realistischen Rhythmus ohne bedeutungsvollen Inhalt ergeben.",
  "pageText.50efd43e": "So stellt dieser Generator Text zusammen",
  "pageText.78c6a4d6": "Wörter werden zufällig aus einer festen Liste mit Lorem-Ipsum-Vokabular gewählt. Jeder Klick auf „Generieren“ liefert daher ein anderes Ergebnis.",
  "pageText.cdfdd915": "Sätze haben 5 bis 15 Wörter, beginnen mit einem Großbuchstaben und enden mit einem Punkt.",
  "pageText.8a5faad3": "Absätze haben 3 bis 7 Sätze und werden durch eine Leerzeile getrennt.",
  "pageText.5b9b38b3": "Wenn „Mit Lorem ipsum ... beginnen“ aktiviert ist, beginnt die Absatz- und Satzausgabe mit Lorem ipsum dolor sit amet, consectetur adipiscing elit., die Wortausgabe mit Lorem ipsum.",
  "pageText.d069a303": "Der Wortmodus liefert genau die angeforderte Anzahl von Wörtern, durch Leerzeichen getrennt und ohne Satzzeichen.",
  "pageText.cfa7bbd6": "Unter der Ausgabe werden die Gesamtzahlen für Wörter, Zeichen, Sätze und Absätze angezeigt.",
  "pageText.5fc47ebf": "Platzhaltertext sinnvoll einsetzen",
  "pageText.3a4e06f6": "Lorem ipsum eignet sich zum Prüfen von Zeilenlänge, Zeilenumbrüchen und vertikalem Rhythmus, verdeckt aber Probleme, die echter Inhalt sichtbar macht. Vor der Veröffentlichung eines Designs:",
  "pageText.039ee6ef": "Prüfen Sie es mit realistischem Text, einschließlich der längsten zu erwartenden Überschrift, des längsten Namens oder Produkttitels.",
  "pageText.d1b357c8": "Prüfen Sie übersetzte Texte: Deutsch oder Finnisch ist häufig länger als Englisch; Chinesisch oder Japanisch hat andere Zeilenumbrüche.",
  "pageText.016f7d53": "Durchsuchen Sie vor der Veröffentlichung die Codebasis nach lorem und ipsum, damit kein Platzhaltertext in die Produktion gelangt.",
  "pageText.e449bc7c": "Verwenden Sie Lorem Ipsum nicht in Alternativtexten und barrierefreien Namen. Bildschirmleseprogramme lesen es laut vor.",
  "pageText.2baf95ba": "Erzeugen Sie für datenreiche Entwürfe wie Benutzertabellen oder Produktkarten stattdessen realistische Beispieldatensätze mit einem Testdatengenerator. Lorem ipsum prüft keine Namen, Zahlen, Datumsangaben oder langen Zeichenfolgen ohne Umbruch, etwa URLs.",
  "pageText.7ef81d93": "Was ist ein QR-Code?",
  "pageText.95dfb03e": "Ein QR-Code (Quick Response) ist ein zweidimensionaler Barcode, der Text wie eine URL, eine Kontaktkarte oder eine WLAN-Konfiguration speichert. Smartphone-Kameras und Scanner-Apps decodieren ihn und bieten eine Aktion an, etwa das Öffnen des Links.",
  "pageText.94540be7": "Welche Daten kann ich codieren?",
  "pageText.62ffa087": "Beliebigen Text. Die Vorlagen verwenden Standardformate für URLs, E-Mail (mailto:), Telefon (tel:), SMS (sms:), WLAN (WIFI:) und vCard-Kontakte, die Smartphones erkennen und verarbeiten.",
  "pageText.a6c7c2f4": "Laufen diese QR-Codes ab?",
  "pageText.6544ed40": "Nein. Es sind statische Codes: Der Inhalt ist im Muster selbst gespeichert, ohne einen Umleitungsdienst, der abgeschaltet werden könnte. Ein URL-Code funktioniert so lange wie die URL.",
  "pageText.d7525538": "Kann ich Scans verfolgen oder den Link später ändern?",
  "pageText.6fb75242": "Bei einem statischen Code nicht. Wenn Sie das Ziel nach dem Druck ändern möchten, codieren Sie eine kurze URL auf einer Domain, die Sie kontrollieren, und ändern Sie dort die Weiterleitung. Die Protokolle Ihres eigenen Servers können dann die Besuche zählen.",
  "pageText.3b2f43fc": "Sollte ich PNG oder SVG herunterladen?",
  "pageText.034404ba": "Verwenden Sie SVG für den Druck und für Designs, deren Größe geändert wird: Es skaliert ohne Unschärfe. Verwenden Sie PNG für Dokumente, Folien und Werkzeuge, die SVG nicht akzeptieren. Wählen Sie die Größe 1024 px, wenn Sie das Bild vergrößern möchten.",
  "pageText.229bdf99": "Wie erstelle ich einen WLAN-QR-Code?",
  "pageText.072a9bd1": "Wählen Sie die WiFi-Vorlage und bearbeiten Sie WIFI:T:WPA;S:MyNetwork;P:MyPassword;;. T ist der Sicherheitstyp (WPA, WEP oder nopass), S der Netzwerkname und P das Passwort. Maskieren Sie ; , : und \\ im Namen oder Passwort mit einem Rückstrich.",
  "pageText.af7b54ae": "Statische QR-Codes ohne Ablaufdatum",
  "pageText.e1f656b0": "Dieser Generator erstellt statische QR-Codes: Ihr Inhalt wird direkt in das Muster codiert, und zwischen Scan und Ziel liegt kein weiterer Dienst. Der Code funktioniert, solange sein Inhalt gültig ist. Scans werden weder verfolgt noch gezählt. Allerdings lässt sich ein gedruckter statischer Code nicht ändern. Wenn Sie das Ziel später ändern können möchten, richten Sie den Code auf eine URL, die Sie kontrollieren, und verwalten Sie die Weiterleitung selbst.",
  "pageText.49c87d45": "Nutzdatenformate der Vorlagen",
  "pageText.9e3fedef": "URL: https://example.com. Geben Sie das Schema an, damit Scanner die Adresse als Link behandeln.",
  "pageText.dfb00b58": "E-Mail: mailto:hello@example.com. Fügen Sie ?subject=Hello hinzu, um eine Betreffzeile vorzubelegen.",
  "pageText.bd51c65e": "Telefon: tel:+1234567890 im internationalen Format mit Ländervorwahl.",
  "pageText.9df90887": "SMS: sms:+1234567890?body=Hello. Die Unterstützung für den vorbelegten Nachrichtentext variiert zwischen Smartphones.",
  "pageText.3f10e94f": "WLAN: WIFI:T:WPA;S:MyNetwork;P:MyPassword;; verbindet mit einem Netzwerk, ohne dass das Passwort eingetippt werden muss.",
  "pageText.fb848228": "vCard: Ein Block BEGIN:VCARD ... END:VCARD mit Feldern wie FN, TEL und EMAIL speichert einen Kontakt.",
  "pageText.0945d9b3": "Fehlerkorrektur und Größe wählen",
  "pageText.a73ec8ff": "Die Fehlerkorrektur fügt Redundanz hinzu, damit ein Code auch gelesen werden kann, wenn Teile verschmutzt, beschädigt oder verdeckt sind. Die vier Stufen stellen ungefähr 7 % (L), 15 % (M, die Voreinstellung), 25 % (Q) oder 30 % (H) des Symbols wieder her. Höhere Stufen und längere Inhalte erzeugen dichtere Codes mit mehr und kleineren Modulen. Für zuverlässiges Scannen brauchen sie eine größere Druckfläche. Das absolute Maximum beträgt 2.953 Bytes bei Stufe L, doch kurze Inhalte lassen sich deutlich zuverlässiger scannen. Halten Sie URLs daher kurz. Verwenden Sie M für Bildschirme und saubere Drucke sowie Q oder H für Etiketten, die abgenutzt werden können.",
  "pageText.d601415e": "Farben, Kontrast und Ruhezone",
  "pageText.21c831a0": "Scanner erwarten dunkle Module auf hellem Hintergrund mit starkem Kontrast. Vermeiden Sie daher blasse Vordergrundfarben und helle Codes auf dunklem Hintergrund (invertierte Codes), die manche Scanner-Apps nicht lesen können. Das erzeugte Bild hat einen Rand von 1 Modul. Die QR-Spezifikation verlangt eine Ruhezone von 4 Modulen. Lassen Sie deshalb zusätzliche freie Fläche um den Code, wenn Sie ihn in ein unruhiges oder farbiges Design einfügen. Testen Sie den endgültigen gedruckten oder exportierten Code vor der Veröffentlichung mit mehreren Smartphones.",
  "pageText.b744dab3": "Was ist ein URL-Slug?",
  "pageText.24831d41": "Ein URL-Slug ist der Teil einer URL, der eine bestimmte Seite in lesbarer Form bezeichnet. In /blog/my-first-post ist beispielsweise „my-first-post“ der Slug.",
  "pageText.afaa82d8": "Warum sind Slugs für SEO wichtig?",
  "pageText.a7281b59": "SEO-freundliche Slugs helfen Suchmaschinen, Ihre Inhalte zu verstehen, und verbessern die Klickrate, weil Nutzer erkennen können, worum es auf der Seite geht.",
  "pageText.95ac698b": "Welche Arten von Farbverläufen werden unterstützt?",
  "pageText.1f3e5ff6": "Dieses Werkzeug unterstützt lineare Farbverläufe mit einstellbarem Winkel sowie radiale Farbverläufe in Kreis- oder Ellipsenform.",
  "pageText.6593c0c4": "Kann ich den Farbverlauf als Bild exportieren?",
  "pageText.09d7598c": "Ja. Neben dem Kopieren des CSS-Codes können Sie den Farbverlauf als PNG-Bild herunterladen.",
  "pageText.be1336e0": "Was sind Meta-Tags?",
  "pageText.406252f6": "Meta-Tags sind HTML-Elemente, die Metadaten über eine Webseite bereitstellen. Sie helfen Suchmaschinen, Ihre Inhalte zu verstehen, und steuern die Darstellung der Seite in Suchergebnissen.",
  "pageText.a60cca39": "Was sind Open-Graph-Tags?",
  "pageText.f806060d": "Open-Graph-Tags steuern, wie Ihre Inhalte beim Teilen auf sozialen Plattformen wie Facebook, LinkedIn und anderen angezeigt werden.",
  "pageText.3c5f494e": "Wie funktionieren mehrere box-shadow-Ebenen?",
  "pageText.0f2afa64": "CSS box-shadow akzeptiert durch Kommas getrennte Schattendefinitionen. Früher in der Liste angegebene Ebenen werden über später angegebenen Ebenen dargestellt.",
  "pageText.a5cd6aad": "Was ist Glassmorphismus in CSS?",
  "pageText.00c0cd52": "Glassmorphismus kombiniert halbtransparente Hintergrundfarben mit backdrop-filter: blur() und dezenten hellen Rändern, um Milchglas nachzubilden.",
  "pageText.b6a562cf": "Welche 5 Teile hat ein Standard-Cron-Ausdruck?",
  "pageText.4cdd4865": "Standard-Cron-Ausdrücke bestehen aus 5 Feldern: Minute (0–59), Stunde (0–23), Tag des Monats (1–31), Monat (1–12) und Wochentag (0–6, wobei 0 für Sonntag steht).",
  "pageText.f069ffbc": "Was bedeutet */15 in Cron?",
  "pageText.44fd98aa": "Der Schrittwert */15 an der Minutenposition bedeutet „alle 15 Minuten“, zum Beispiel um :00, :15, :30 und :45.",
  "pageText.adadf25c": "Welche Testdaten kann ich erzeugen?",
  "pageText.4b6a1433": "Sie können realistische Beispieldatensätze für Benutzer (mit Namen, E-Mail-Adressen, Telefonnummern und Rollen), Produkte (mit SKUs, Preisen und Bewertungen), Bestellungen (mit Währungen und Status), Unternehmen und Blogbeiträge erzeugen.",
  "pageText.a0f6807f": "Kann ich die erzeugten Testdaten herunterladen?",
  "pageText.5a2779c7": "Ja. Sie können das JSON direkt in die Zwischenablage kopieren oder mit einem Klick als .json-Datei herunterladen.",
  "pageText.a82a3ba7": "Welche Größen werden erzeugt?",
  "pageText.6ab32280": "Das Werkzeug erzeugt PNG-Symbole in 16x16 (Standard-Browsertab), 32x32 (Retina-Browsertab), 48x48 (Desktop-Verknüpfung), 180x180 (iOS Apple Touch Icon), 192x192 (Android-App) und 512x512 (PWA-Startbildschirm).",
  "pageText.1a11e506": "Werden meine hochgeladenen Bilder an einen Server gesendet?",
  "pageText.631bc8d7": "Nein. Sämtliche Größenänderungen und Bilddarstellungen erfolgen im Browser über HTML5 Canvas. Ihre Bilder verlassen Ihren Computer nicht.",
  "pageText.6016f5b9": "Welche Vorlagen enthält dieser .gitignore-Generator?",
  "pageText.9a2e6ae1": "Der Generator enthält Standardregeln für Node.js/TypeScript, Python, Go, Rust, Java/Gradle/Maven, React/Next.js/Vite, Vue/Nuxt, macOS (.DS_Store), Windows, Linux, VSCode und JetBrains-IDEs.",
  "pageText.26b1e47a": "Kann ich eigene Ausschlussmuster hinzufügen?",
  "pageText.b9bb3e9f": "Ja. Sie können im Editor eigene Regelzeilen eingeben, die automatisch mit den gewählten Plattformvorlagen kombiniert werden.",
  "pageText.99c478a9": "Wie funktionieren CSS-Blobs ohne SVG?",
  "pageText.330806ef": "CSS-Blobs verwenden die border-radius-Syntax mit 8 Werten (horizontale Radien / vertikale Radien), um rein mit CSS asymmetrische, geschwungene organische Formen zu erstellen.",
  "pageText.4f7db90d": "Kann ich die Form als skalierbare Vektorgrafik (SVG) herunterladen?",
  "pageText.cd8236b5": "Ja. Sie können den unveränderten SVG-Vektormarkup kopieren oder die Form als eigenständige .svg-Datei herunterladen.",
  "pageText.15c7f36d": "Unterstützt das Werkzeug die Spaltenausrichtung links, mittig und rechts?",
  "pageText.1f6c30ea": "Ja. Mit den Ausrichtungsschaltflächen über jeder Spalte können Sie die Textausrichtung einzeln einstellen (:---, :---:, ---:).",
  "pageText.17171603": "Kann ich Zeilen und Spalten dynamisch hinzufügen oder entfernen?",
  "pageText.81d98d62": "Ja. Klicken Sie auf „+ Spalte hinzufügen“ oder „+ Zeile hinzufügen“, um die Tabelle zu erweitern, oder entfernen Sie einzelne Zeilen und Spalten mit den Papierkorbsymbolen.",
  "pageText.a3b7c9aa": "Warum SVG-Platzhalter statt externer Platzhalter-URLs verwenden?",
  "pageText.36e2f853": "SVG-Platzhalter benötigen keine HTTP-Netzwerkanfragen, laden auch offline sofort und sind mit etwa 300 Bytes kleine Daten-URIs, die direkt in HTML/CSS eingebettet werden.",
  "pageText.98afe7f8": "Kann ich den Beschriftungstext im Bild anpassen?",
  "pageText.7156e33f": "Ja. Sie können beliebigen eigenen Text angeben, etwa „Hero-Banner“ oder „Avatar 128x128“, oder das Feld leer lassen, damit automatisch die Abmessungen angezeigt werden.",
  "pageText.0ddadffc": "Kann ich erzeugte ASCII-Banner in GitHub-README-Dateien verwenden?",
  "pageText.fa3ae5eb": "Ja. Setzen Sie die Ausgabe in Ihrer README.md in einen Markdown-Codeblock (```), damit die Zeichen in allen Browsern mit einer Schrift fester Zeichenbreite ausgerichtet bleiben.",
  "pageText.92b39fd3": "Welche Schriftstile werden unterstützt?",
  "pageText.d1c00c5d": "Klassisches Standard-ASCII mit Schrägstrichen, senkrechten Strichen und Unterstrichen sowie moderne ausgefüllte Unicode-Blockzeichen (█) für eine klare Darstellung.",
  "pageText.a19cad93": "Warum ULID oder UUID v7 statt UUID v4 wählen?",
  "pageText.f6c311f2": "Anders als zufällige UUID v4 beginnen ULID und UUID v7 mit einem Millisekunden-Zeitstempel. Das verhindert die Fragmentierung von B-Baum-Indizes und beschleunigt INSERT-Vorgänge in Datenbanken erheblich.",
  "pageText.dbf5188e": "Sind erzeugte ULIDs vor Kollisionen sicher?",
  "pageText.e4c22fd6": "Ja. Jede ULID enthält neben dem 48-Bit-Zeitstempel 80 Bits kryptografisch erzeugten Zufall, sodass die Wahrscheinlichkeit einer Kollision praktisch null ist.",
  "pageText.434b3c01": "Wie werden die Farbstufen berechnet?",
  "pageText.fef3b562": "Der Generator passt HSL-Helligkeitskurven an die Standard-Helligkeitsverteilung von Tailwind CSS an: von 50 bei etwa 96 % Helligkeit bis 950 bei etwa 6 % Helligkeit.",
  "pageText.6fd82787": "Welche Schreibweisen stehen zur Verfügung?",
  "pageText.64f57bec": "Standard mit Doppelpunkten (00:1A:2B:3C:4D:5E), Bindestrichen (00-1A-2B-3C-4D-5E), Cisco-Punkten (001a.2b3c.4d5e) und ununterbrochenen Hexadezimalzeichen.",
  "pageText.0665d60c": "Warum sollte ich EXIF-Daten entfernen?",
  "pageText.4514458b": "Mit Smartphones aufgenommene Fotos enthalten häufig genaue GPS-Koordinaten und Gerätekennungen, die beim öffentlichen Teilen Ihre Privatsphäre gefährden.",
  "pageText.42405f57": "Verringert das Entfernen von EXIF-Daten die Bildqualität?",
  "pageText.4d60a474": "Nein. Es werden nur Metadaten-Tags entfernt; die Bildpixel bleiben unverändert.",
  "pageText.21ef5814": "Wie prüfe ich die Prüfsumme einer heruntergeladenen Datei?",
  "pageText.224c058f": "Wählen Sie die Datei aus und fügen Sie die vollständige erwartete Prüfsumme des Herausgebers oder einer anderen vertrauenswürdigen unabhängigen Quelle ein. Warten Sie, bis die Hash-Berechnung abgeschlossen ist, und prüfen Sie dann das Ergebnis auf Übereinstimmung oder Abweichung.",
  "pageText.ae63ea0f": "Wird meine Datei auf einen Server hochgeladen?",
  "pageText.eebc3c64": "Ausgewählte Dateien werden lokal in den Browserspeicher eingelesen und für diese Berechnung nicht hochgeladen. SHA-1, SHA-256, SHA-384 und SHA-512 verwenden Web Crypto; MD5 und CRC32 verwenden JavaScript-Implementierungen.",
  "pageText.0096052f": "Bedeutet eine übereinstimmende Prüfsumme, dass die Datei sicher oder authentisch ist?",
  "pageText.85e0eb7f": "Eine Übereinstimmung bedeutet, dass die berechnete Prüfsumme dem erwarteten Wert entspricht. Sie beweist weder die Unbedenklichkeit der Datei noch die Identität des Herausgebers. Beziehen Sie die erwartete Prüfsumme aus einer vertrauenswürdigen unabhängigen Quelle. Bei MD5 und SHA-1 ist die Kollisionsresistenz gebrochen, und CRC32 ist nicht kryptografisch. Verwenden Sie für Integritätsprüfungen bevorzugt SHA-256.",
  "pageText.e7ddf90b": "Kann ich sehr große Dateien im Browser hashen?",
  "pageText.5a7687ac": "Die gewählte Datei wird vollständig in den Arbeitsspeicher eingelesen. Verfügbarer Speicher und Geräteleistung begrenzen die praktisch mögliche Dateigröße. Verwenden Sie für große Downloads ein lokales Prüfsummenwerkzeug im Terminal oder das Python-Beispiel mit blockweiser Verarbeitung in der Anleitung zur SHA-256-Prüfung.",
  "pageText.36576d77": "Einen Prüfsummenvergleich für abc nachstellen",
  "pageText.c0f11add": "Wählen Sie „abc-Beispiel laden“, um genau die drei UTF-8-Bytes abc ohne Leerzeichen oder abschließenden Zeilenumbruch zu hashen. Sie können auch eine lokale Textdatei mit genau diesen Bytes auswählen.",
  "pageText.45f16187": "Die SHA-256-Prüfsumme lautet ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad. Fügen Sie diesen vollständigen Wert in das Feld für die erwartete Prüfsumme ein, um eine Übereinstimmung zu sehen. Ändern Sie eine Hexadezimalziffer, um nach Abschluss der Hash-Berechnung eine Abweichung zu sehen.",
  "pageText.38407fa7": "Dieselbe Eingabe ergibt MD5 900150983cd24fb0d6963f7d28e17f72 und CRC32 352441c2. Die Ergebnisse enthalten auch SHA-1, SHA-384 und SHA-512. Ein Zeilenumbruch oder eine andere Codierung verändert die Bytes und ihre Prüfsummen.",
  "pageText.a8f9e0fa": "Was ist MD5?",
  "pageText.197bb98c": "MD5 (Message Digest 5) ist eine kryptografische Hashfunktion, die einen Hashwert von 128 Bit (16 Bytes) erzeugt.",
  "pageText.380ae33f": "Ist MD5 sicher?",
  "pageText.200b2951": "MD5 gilt für kryptografische Zwecke nicht mehr als sicher, ist aber weiterhin für Prüfsummen und nicht sicherheitskritische Anwendungen nützlich.",
  "pageText.eb024fef": "Lässt sich ein MD5-Hash zurück in Text umwandeln?",
  "pageText.f3a4be7f": "Nein. MD5 ist ein Einweg-Hash und keine umkehrbare Verschlüsselung. Als MD5-Decoder bezeichnete Dienste raten meist mögliche Eingaben und vergleichen deren Hashwerte. Dieses Werkzeug erzeugt Hashwerte und führt keine Rückwärtssuche durch.",
  "pageText.de23ad8f": "Was macht dieser MD5-Hashgenerator?",
  "pageText.71308743": "Dieser MD5-Hashgenerator wandelt Text oder eine ausgewählte Datei in den in RFC 1321 definierten 128-Bit-Message-Digest um und stellt ihn als 32 Hexadezimalzeichen dar. Text wird in UTF-8-Bytes umgewandelt; im Dateimodus werden die Bytes der Datei gehasht. Klein- und Großbuchstaben sind Darstellungsoptionen für denselben Digest. Die Berechnung erfolgt im Browsercode; für die Hash-Berechnung ist daher kein Hochladen auf einen Server erforderlich.",
  "pageText.e043d2b7": "MD5-Beispiel und Dateiprüfsumme",
  "pageText.00f057ca": "Für die Eingabe aus genau drei Zeichen abc, ohne Anführungszeichen, Leerzeichen oder abschließenden Zeilenumbruch, lautet das Ergebnis 900150983cd24fb0d6963f7d28e17f72. RFC 1321 veröffentlicht diesen Testvektor. Die Darstellung in Großbuchstaben ändert nur die Schreibweise, nicht die Bits des Digests.",
  "pageText.294638f4": "Wählen Sie für eine Dateiprüfsumme eine Datei und vergleichen Sie alle 32 Hexadezimalzeichen mit einem erwarteten Wert. Eine Abweichung beweist, dass die Dateibytes von den Bytes abweichen, aus denen der erwartete Digest berechnet wurde. Eine Übereinstimmung kann das Erkennen versehentlicher Fehler unterstützen, doch die Quelle des erwarteten Werts ist entscheidend. Ein übereinstimmender MD5-Hash ist kein Beweis gegen einen absichtlichen Austausch.",
  "pageText.bd0d278c": "Lässt sich MD5 entschlüsseln, und wann sollte man es verwenden?",
  "pageText.0962ea5c": "Dies ist ein MD5-Generator, kein Dienst zum Entschlüsseln von MD5 oder zur Hash-Rückwärtssuche. Hashen ist keine Verschlüsselung, und ein Digest fester Größe enthält keine wiederherstellbare Kopie der Eingabe. Versuche, einen Digest umzukehren, raten normalerweise mögliche Eingaben und hashen sie zum Vergleich.",
  "pageText.cf9f06aa": "RFC 6151 erklärt MD5 für nicht mehr akzeptabel, wenn Kollisionsresistenz erforderlich ist, etwa bei digitalen Signaturen. Verlassen Sie sich nicht auf MD5, um absichtliche Manipulationen zu erkennen. Der RFC erlaubt MD5-Prüfsummen, die ausschließlich dem Schutz vor Fehlern dienen. Anwendungen müssen jedoch angeben, welche Sicherheitsleistung sie gegebenenfalls davon erwarten.",
  "pageText.953bfb55": "Die Berechnung im Browser verringert die Notwendigkeit, Text oder Dateien zum Hashen zu übertragen, macht MD5 aber nicht kryptografisch sicher. Geben Sie keine Passwörter oder anderen Geheimnisse auf einer Online-Hashseite ein.",
  "pageText.101f9c75": "Was ist SHA256?",
  "pageText.16259758": "SHA256 (Secure Hash Algorithm mit 256 Bit) ist eine kryptografische Hashfunktion, die einen Hashwert von 256 Bit (32 Bytes) erzeugt.",
  "pageText.9afb2ad2": "Ist SHA256 sicher?",
  "pageText.0af6e6d2": "SHA-256 eignet sich weiterhin für viele Integritätsanwendungen. Ein Digest ohne Schlüssel authentifiziert jedoch seine Quelle nicht und ist keine Passwort-Hashfunktion. Verwenden Sie für die Dateiprüfung eine vertrauenswürdige erwartete Prüfsumme und für Passwörter eine speziell dafür entwickelte Hashfunktion.",
  "pageText.c16f7e5d": "Wie prüfe ich eine Dateiprüfsumme?",
  "pageText.14edcc5a": "Wählen Sie die Datei und tragen Sie einen SHA-256-Wert mit 64 Zeichen aus einer vertrauenswürdigen unabhängigen Quelle in das Feld für die erwartete Prüfsumme ein. Das Werkzeug zeigt an, ob der erzeugte und der erwartete Digest übereinstimmen.",
  "pageText.7490e417": "Kann ein SHA-256-Hash zurück in Text decodiert werden?",
  "pageText.74338944": "Nein. SHA-256-Hashen ist keine umkehrbare Verschlüsselung; aus einem Digest lässt sich die ursprüngliche Eingabe daher nicht durch Decodieren wiederherstellen. Dieses Werkzeug erzeugt und vergleicht SHA-256-Werte. Es knackt keine Passwörter und führt keine Hash-Rückwärtssuche durch.",
  "pageText.cd1de6c5": "Was macht dieser SHA-256-Generator?",
  "pageText.a17f5535": "Dieser SHA-256-Generator berechnet den in NIST FIPS 180-4 festgelegten 256-Bit-Message-Digest für Text oder eine gewählte Datei und stellt ihn als 64 Hexadezimalzeichen dar. Im Textmodus wandelt der Browser Zeichen in UTF-8-Bytes um. Der Dateimodus berechnet den Digest aus den gewählten Bytes. Klein- und Großbuchstaben sind Darstellungsoptionen für denselben Wert.",
  "pageText.d7c2f3d3": "SHA-256 ist nicht umkehrbar: Ein Hash lässt sich nicht zum ursprünglichen Text oder zur ursprünglichen Datei decodieren. Geben Sie Text ein oder wählen Sie eine Datei, um einen Digest zu erzeugen. Vergleichen Sie den Digest einer Datei mit einer vertrauenswürdigen erwarteten Prüfsumme, um sie zu prüfen.",
  "pageText.40dc4945": "SHA-256-Beispiel und Dateiprüfung",
  "pageText.59582d9c": "Für die Eingabe aus genau drei Zeichen abc, ohne Anführungszeichen, Leerzeichen oder abschließenden Zeilenumbruch, lautet das Ergebnis ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad. Ein Zeilenumbruch, andere Groß- und Kleinschreibung oder eine andere Codierung verändert die Eingabebytes und führt zu einer anderen Berechnung.",
  "pageText.af255369": "Erzeugen Sie zum Prüfen einer Datei deren SHA-256-Wert und tragen Sie den erwarteten Digest mit 64 Zeichen aus einer vertrauenswürdigen Quelle ein. Der Vergleich meldet eine Übereinstimmung oder Abweichung. Eine Abweichung beweist, dass sich die Bytes von den für den erwarteten Digest verwendeten Bytes unterscheiden. Eine Übereinstimmung bestätigt den Vergleich; die Quelle des erwarteten Werts bleibt dennoch entscheidend.",
  "pageText.57ea438c": "SHA-256 in JavaScript und Python berechnen",
  "pageText.2f2bbf6b": "Die Web-Crypto-Funktion digest in JavaScript arbeitet mit Bytes. Verwenden Sie TextEncoder für UTF-8-Text oder arrayBuffer() einer File für den exakten Dateiinhalt. Das Beispiel hasht abc in beiden Formen und protokolliert denselben Digest. digest() im Browser benötigt einen sicheren Kontext und liest die Eingabe in den Arbeitsspeicher.",
  "pageText.a0a974f1": "Pythons hashlib kann einen Digest schrittweise aktualisieren. Das Dateibeispiel liest eine vorhandene download.zip im Binärmodus in Blöcken von einem Megabyte. Passen Sie den Pfad an Ihre Datei an und vergleichen Sie den vollständigen Digest mit dem vertrauenswürdigen erwarteten Wert.",
  "pageText.5379ecfa": "Lässt sich SHA-256 entschlüsseln, und was beweist es?",
  "pageText.43df41c5": "Dies ist ein SHA-256-Generator, kein Dienst zum Entschlüsseln oder zur Hash-Rückwärtssuche. Ein Digest verdichtet die Eingabe zu einem Ergebnis mit festen 256 Bit. Er ist keine verschlüsselte oder verlustfreie Kopie, aus der sich das Original decodieren lässt. Um ein wahrscheinliches Original zu finden, muss man mögliche Eingaben raten und zum Vergleich hashen.",
  "pageText.139d7ac4": "FIPS 180-4 legt SHA-256 als sicheren Hashalgorithmus fest und beschreibt Hashwerte als Bausteine für Anwendungen wie digitale Signaturen und schlüsselbasierte Nachrichtenauthentifizierung. Dieser Generator ohne Schlüssel signiert keine Daten, authentifiziert keinen Absender und verschlüsselt keine Inhalte. Betrachten Sie einen Digest, der neben einer nicht vertrauenswürdigen Datei bereitgestellt wird, nicht als unabhängigen Herkunftsnachweis.",
  "pageText.a06060d1": "Die Hash-Berechnung für Text und Dateien erfolgt im Browsercode und benötigt kein Hochladen auf einen Server. Diese Datenschutzeigenschaft macht einen Hash nicht zu einer Verschlüsselung. Geben Sie keine Geheimnisse in ein Online-Werkzeug ein, sofern dessen Ausführungsumgebung nicht für Ihre Daten geeignet ist.",
  "pageText.51a1b9be": "Was ist SHA512?",
  "pageText.84a4301e": "SHA512 (Secure Hash Algorithm mit 512 Bit) ist eine kryptografische Hashfunktion, die einen Hashwert von 512 Bit (64 Bytes) erzeugt. Er wird üblicherweise als Hexadezimalzahl mit 128 Stellen dargestellt.",
  "pageText.790c6ec3": "Ist SHA512 sicher?",
  "pageText.6d855b6b": "Ja. SHA512 gilt derzeit für kryptografische Zwecke als sehr sicher und wird für die meisten Anwendungen empfohlen.",
  "pageText.815e4dcd": "Was ist HMAC?",
  "pageText.ff3b2cf9": "HMAC ist ein schlüsselbasierter Nachrichtenauthentifizierungscode, der eine kryptografische Hashfunktion mit einem gemeinsamen Geheimnis kombiniert, um Integrität und Authentizität einer Nachricht zu prüfen.",
  "pageText.09e2e0ba": "Ist HMAC eine Verschlüsselung?",
  "pageText.abec3974": "Nein. HMAC verbirgt die Nachricht nicht. Es ermöglicht Beteiligten mit einem gemeinsamen Geheimnis, Änderungen zu erkennen und die Nachrichtenquelle zu authentifizieren.",
  "pageText.3c4deb2f": "Welche Algorithmen und Ausgabeformate werden unterstützt?",
  "pageText.b389a303": "Das Werkzeug unterstützt HMAC mit SHA-256, SHA-384 oder SHA-512 und zeigt oder prüft Signaturen als Hexadezimalwert oder in Standard-Base64.",
  "pageText.8f405a3a": "HMAC-Signaturen erzeugen und prüfen",
  "pageText.b25fc0c3": "Geben Sie die exakten Nachrichtenbytes ein, die Ihr Text repräsentiert, sowie ein gemeinsames Geheimnis, die erwartete SHA-2-Variante und die Signaturcodierung. „Generieren“ erzeugt eine Signatur; „Prüfen“ berechnet sie mit denselben Eingaben erneut und vergleicht die decodierten Bytes. Ein anderer Zeilenumbruch, eine andere Zeichencodierung, ein anderes Geheimnis, ein anderer Algorithmus oder eine andere Ausgabecodierung verändert das Ergebnis.",
  "pageText.422f4458": "Typische Anwendungen für Webhooks und APIs",
  "pageText.f0d6dd20": "Stellen Sie beim Debuggen einer Integration eine Webhook-Signatur nach.",
  "pageText.d0483022": "Vergleichen Sie einen lokal berechneten HMAC mit der Signatur eines vertrauenswürdigen Absenders.",
  "pageText.44fd46de": "Wandeln Sie dieselben HMAC-Bytes zwischen Hexadezimal- und Base64-Darstellung um.",
  "pageText.2cfc6b71": "Bestätigen Sie, dass Änderungen an der Nachricht zum Fehlschlagen der Signaturprüfung führen.",
  "pageText.843858f3": "Sicherheitsgrenze",
  "pageText.ab6a34ae": "HMAC erfordert ein starkes gemeinsames Geheimnis, das sicher übermittelt und gespeichert wird. Dieses Browserwerkzeug eignet sich für Testdaten. Produktionsgeheimnisse sollten jedoch in kontrollierten Anwendungsumgebungen bleiben. HMAC authentifiziert Daten; es verschlüsselt sie nicht und ist kein Verfahren zur Passwortspeicherung. Die Signaturprüfung übernimmt die Web-Crypto-API des Browsers, statt die Signaturbytes im JavaScript der Anwendung zu vergleichen.",
  "pageText.cb69e8df": "Was ist PKCE?",
  "pageText.abc745c5": "PKCE ist eine OAuth-Erweiterung, die eine Autorisierungsanfrage an einen geheimen Code-Verifier bindet, den der Client besitzt. Dadurch sinkt das Risiko, dass Autorisierungscodes abgefangen werden.",
  "pageText.bb3fb7f1": "Welche Challenge-Methode verwendet dieses Werkzeug?",
  "pageText.334f8104": "Es verwendet S256: den SHA-256-Hash des Code-Verifiers, codiert als Base64url ohne Auffüllzeichen. Die Methode plain wird bewusst nicht erzeugt.",
  "pageText.c069d885": "Kann ich den erzeugten Wert in der Produktion verwenden?",
  "pageText.ddc8fb76": "Die Werte nutzen sichere Browser-Zufallswerte und gültige PKCE-Zeichen. Verifier für die Produktion sollten Sie jedoch in dem OAuth-Client erzeugen und aufbewahren, der den Token-Austausch abschließt.",
  "pageText.4c2764af": "So wird das PKCE-S256-Paar erzeugt",
  "pageText.71336ec6": "Ein PKCE-Client erzeugt einen Code-Verifier mit hoher Entropie, hasht seinen exakten ASCII-Wert mit SHA-256 und sendet das Base64url-Ergebnis ohne Auffüllzeichen als Code-Challenge. Die Autorisierungsanfrage enthält code_challenge und code_challenge_method=S256. Die spätere Token-Anfrage sendet den ursprünglichen code_verifier, damit der Autorisierungsserver dieselbe Challenge ableiten und vergleichen kann.",
  "pageText.3d8fba00": "Verifier-Regeln und Prüfung",
  "pageText.2aa00a1d": "„Generieren“ erzeugt 43 bis 128 Zeichen aus dem in RFC 7636 definierten Satz nicht reservierter Zeichen. Dafür werden sichere Zufallsbytes mit Rejection Sampling verwendet.",
  "pageText.9cb7c772": "„Ableiten“ akzeptiert einen vorhandenen Verifier nur, wenn sein vollständiger Wert die Längen- und Zeichenregeln erfüllt.",
  "pageText.ae7f5d42": "„Prüfen“ leitet S256 erneut ab und vergleicht das Ergebnis mit einer Base64url-Challenge aus genau 43 Zeichen.",
  "pageText.587e6e12": "Leerraum ist relevant. Kopieren Sie den Verifier exakt und bewahren Sie ihn nur für den dazugehörigen Autorisierungsvorgang auf.",
  "pageText.1fadc2f8": "PKCE verhindert, dass ein Autorisierungscode ohne den zugehörigen Verifier eingelöst wird. Es ersetzt weder die Prüfung der Weiterleitungs-URI, von OAuth state oder OIDC nonce noch TLS, sichere Tokenspeicherung oder die Prüfung durch den Autorisierungsserver. Generierung und Hash-Berechnung erfolgen lokal in diesem Browser. Zwischenablageverlauf, Erweiterungen, Protokolle oder ein gemeinsam genutztes Gerät können kopierte Werte trotzdem offenlegen.",
  "pageText.cc61fb43": "Warum ergibt dasselbe Passwort jedes Mal einen anderen Hash?",
  "pageText.47fdbb41": "Bcrypt erzeugt für jeden Hash einen neuen zufälligen Salt und speichert Salt und Kostenfaktor im codierten Ergebnis. Deshalb können verschiedene Hashwerte dasselbe Passwort verifizieren, ohne dass eine separate Salt-Spalte erforderlich ist.",
  "pageText.fd8efc8a": "Was steuert der Bcrypt-Kostenfaktor?",
  "pageText.e24b8eb9": "Der Kostenfaktor ist ein Arbeitsfaktor zur Basis zwei. Eine Erhöhung um eins verdoppelt ungefähr den Rechenaufwand. Bestimmen Sie den Produktionswert durch Messungen auf Ihrer eigenen Authentifizierungsinfrastruktur, statt eine im Browser gemessene Zeit zu übernehmen.",
  "pageText.c5646e46": "Warum werden Passwörter mit mehr als 72 UTF-8-Bytes abgewiesen?",
  "pageText.35d8cc67": "Bcrypt verarbeitet nur die ersten 72 Bytes. Das Abweisen längerer Eingaben verhindert, dass zwei sichtbar unterschiedliche Passwörter unbemerkt als dieselbe abgeschnittene Bytefolge behandelt werden.",
  "pageText.a3c91e25": "Was Bcrypt-Generator und -Prüfer machen",
  "pageText.523e4066": "„Generieren“ erzeugt einen zufälligen Salt, wendet Bcrypt mit dem gewählten Kostenfaktor an und gibt die standardisierte modulare Hashzeichenfolge mit Version, Kostenfaktor, Salt und Prüfsumme zurück. „Prüfen“ liest diese Parameter aus einem vorhandenen Hash und führt Bcrypt erneut aus, bevor es meldet, ob das eingegebene Testpasswort passt. Bcrypt ist absichtlich langsam, anders als schnelle Prüfsummen-Hashes wie MD5 oder SHA-256.",
  "pageText.52fbc8aa": "Kostenfaktor, Salt und die 72-Byte-Grenze",
  "pageText.a94e797a": "Die Oberfläche bietet für Browser geeignete Kostenfaktoren von 8 bis 14. Höhere Werte können auf langsameren Geräten deutlich länger dauern.",
  "pageText.3541abdb": "Jeder erzeugte Hash verwendet einen neuen kryptografisch zufälligen Salt. Wiederholtes Generieren sollte daher keine identischen Zeichenfolgen liefern.",
  "pageText.8bd98451": "Speichern Sie den vollständigen codierten Hash. Salt und Kostenfaktor sind bereits enthalten und werden bei der Prüfung automatisch verwendet.",
  "pageText.107d624e": "Das Werkzeug zählt UTF-8-Bytes statt JavaScript-Zeichen und weist Werte ab, die Bcrypts Verarbeitungsgrenze von 72 Bytes überschreiten.",
  "pageText.4b0c23bf": "Grenzen der sicheren Verwendung",
  "pageText.e9f75848": "Verwenden Sie diese Seite mit künstlichen Entwicklungs- oder QA-Daten. Passwort-Hashing in der Produktion gehört in einen vertrauenswürdigen serverseitigen Authentifizierungsablauf mit Ratenbegrenzung, sicherer Übertragung, Überwachung von Datenlecks und einer dokumentierten Strategie für Aktualisierungen. Ein erfolgreicher Vergleich beweist nur, dass ein Passwort zu einem codierten Hash passt. Er beurteilt weder Passwortstärke noch Kontosicherheit oder die Eignung des gewählten Kostenfaktors für Ihre Server.",
  "pageText.10893cde": "Lokale Verarbeitung und Kompatibilität",
  "pageText.0f1e91b6": "Die Bcrypt-Implementierung wird erst nach dem Start einer Operation geladen. Hash-Berechnung und Vergleich erfolgen in diesem Browser. Der Prüfer akzeptiert die Standardformen $2a$, $2b$ und $2y$ innerhalb der Kostenfaktorgrenze. Zwischenablageprogramme, Erweiterungen, Bildschirmfreigaben oder ein bereits kompromittiertes Gerät können Werte dennoch offenlegen. Fügen Sie daher keine echten Benutzerzugangsdaten ein.",
  "pageText.dfdb1834": "Beweist das Decodieren, dass ein Zertifikat vertrauenswürdig ist?",
  "pageText.54a44265": "Nein. Das Parsen zeigt codierte Felder und kann prüfen, ob sich ein Zertifikat mit seinem eigenen öffentlichen Schlüssel verifizieren lässt. Vertrauen erfordert außerdem eine gültige Kette zu einer akzeptierten Wurzel, Prüfungen von Zweck und Namen, Richtlinien, Gültigkeitszeit und häufig Nachweise über Widerruf oder Transparenz.",
  "pageText.5cbb68de": "Kann ich eine vollständige PEM-Zertifikatskette einfügen?",
  "pageText.99a5e254": "Ja. Das Werkzeug extrahiert und decodiert bis zu zehn CERTIFICATE-Blöcke in der Reihenfolge der Eingabe. Es ordnet sie nicht um und beweist nicht, dass jedes Zertifikat das nächste signiert hat.",
  "pageText.00fb6a40": "Werden private Schlüssel akzeptiert?",
  "pageText.339287f5": "Nein. Die Eingabe akzeptiert PEM-CERTIFICATE-Blöcke oder Base64-codierte DER-Zertifikate. Texte mit privaten Schlüsseln oder Zertifikatsanträgen werden abgewiesen. Fügen Sie keine privaten Schlüssel in Browserwerkzeuge ein.",
  "pageText.eac22252": "Aus einem X.509-Zertifikat ausgelesene Felder",
  "pageText.27c40514": "Der Decoder liest ASN.1 DER, das direkt als Base64 oder innerhalb der PEM-Begrenzungen nach RFC 7468 vorliegt. Er zeigt die Distinguished Names von Inhaber und Aussteller, Seriennummer, Gültigkeitsbeginn und -ende, Signatur- und Public-Key-Algorithmen, unterstützte alternative Inhabernamen, Erweiterungs-OIDs, Bytegröße und einen SHA-256-Digest der exakten Zertifikatsbytes.",
  "pageText.6739d969": "Gültigkeit und Selbstsignatur sind begrenzte Prüfungen",
  "pageText.020adbca": "„Derzeit gültig“ bedeutet, dass die Browseruhr zwischen notBefore und notAfter liegt. Es bestätigt weder Vertrauenswürdigkeit noch vorgesehenen Verwendungszweck.",
  "pageText.d1665ea2": "„Selbst ausgestellt“ bedeutet, dass Inhaber- und Ausstellername übereinstimmen. „Kryptografisch selbst signiert“ erfordert zusätzlich, dass die Signatur mit dem öffentlichen Schlüssel des Zertifikats verifiziert werden kann.",
  "pageText.75c63764": "Nicht unterstützte Browser-Kryptografie kann das Ergebnis der Selbstsignaturprüfung offenlassen, selbst wenn die Zertifikatsstruktur decodiert werden kann.",
  "pageText.7a7b0159": "Ein SHA-256-Fingerabdruck identifiziert exakte DER-Bytes für den Vergleich. Er wird nur dann zum Vertrauensmerkmal, wenn er aus einem unabhängigen vertrauenswürdigen Kanal stammt.",
  "pageText.087c5028": "Prüfungen, die weiterhin ein TLS- oder PKI-Prüfer durchführen muss",
  "pageText.08a73601": "Diese Seite erstellt keine Kette gegen die Wurzelzertifikate des Betriebssystems oder Browsers, ruft keine Zwischenzertifikate ab, prüft weder Schlüsselverwendung noch Richtlinien für einen bestimmten Zweck, gleicht keinen Hostnamen ab, fragt weder OCSP noch CRLs ab, untersucht keine Certificate-Transparency-Protokolle und stellt keine Serververbindung her. Diese Entscheidungen erfordern den Vertrauensspeicher, den Verbindungskontext und die Prüfrichtlinien des tatsächlichen Clients.",
  "pageText.314bab46": "Was ist BIP-39?",
  "pageText.9fba1f54": "BIP-39 (Bitcoin Improvement Proposal 39) beschreibt die Umsetzung einer mnemonischen Wortfolge, also einer Gruppe leicht merkbarer Wörter, zur Erzeugung deterministischer Krypto-Wallets.",
  "pageText.bc10db69": "Ist es sicher, hier Seed-Phrasen zu erzeugen?",
  "pageText.6f73837c": "Alle Generierungs- und Entropieberechnungen verwenden window.crypto.getRandomValues() und erfolgen vollständig lokal in Ihrem Browser. Seed-Phrasen werden niemals über das Netzwerk übertragen.",
  "pageText.6d97a1a7": "Werden die privaten Schlüssel an Ihren Server gesendet?",
  "pageText.791c3f3c": "Nein. Die Schlüsselpaare werden mit window.crypto.subtle direkt auf Ihrem Gerät erzeugt. Die privaten Schlüssel verlassen Ihren Browser nicht.",
  "pageText.4cc18af6": "In welchem Format werden Schlüssel exportiert?",
  "pageText.26a068ea": "Öffentliche Schlüssel werden im SPKI-PEM-Format (-----BEGIN PUBLIC KEY-----) und private Schlüssel im PKCS#8-PEM-Format (-----BEGIN PRIVATE KEY-----) exportiert.",
  "pageText.14b643ed": "Welcher Algorithmus wird für .htpasswd in der Produktion empfohlen?",
  "pageText.e63436c8": "Bcrypt ($2y$) wird für Produktionsumgebungen ausdrücklich empfohlen, da es einen robusten Schutz vor Brute-Force- und Wörterbuchangriffen bietet.",
  "pageText.438a3aaa": "Wird mein Klartextpasswort an einen Server gesendet?",
  "pageText.71f70564": "Nein. Die Hash-Berechnung erfolgt vollständig lokal in Ihrem Browser über die Web-Crypto-API. Ihre Passwörter gelangen nicht an einen Server.",
  "pageText.c83dd430": "Wie funktioniert ein zeitbasiertes Einmalpasswort (TOTP)?",
  "pageText.682b1360": "TOTP (RFC 6238) berechnet einen sechsstelligen Prüfcode aus einer HMAC-SHA1-Signatur mit einem gemeinsamen Base32-Geheimnis und dem aktuellen 30-Sekunden-Intervall der Unixzeit.",
  "pageText.2c69c124": "Ist das mit Google Authenticator, Authy und 1Password kompatibel?",
  "pageText.9e7b7687": "Ja. Die erzeugten geheimen Schlüssel und otpauth://-URIs folgen dem offenen Standard, den Google Authenticator, Microsoft Authenticator, 1Password und Bitwarden unterstützen.",
  "pageText.84c27538": "Ist es sicher, Passwörter in diesem Prüfer zu testen?",
  "pageText.004d56b7": "Ja. Sämtliche kryptografischen Prüfungen erfolgen vollständig lokal in Ihrem Webbrowser. Klartextpasswörter und Hashwerte werden niemals an einen Server übertragen.",
  "pageText.a32149fa": "Welche Bcrypt-Versionen werden unterstützt?",
  "pageText.c4c394d4": "Unterstützt werden Standard-Bcrypt-Zeichenfolgen im Modular Crypt Format mit den Präfixen $2a$, $2b$ und $2y$ und einem Kostenfaktor von 4 bis 31.",
  "pageText.78492a05": "Welche HMAC-Signaturalgorithmen werden unterstützt?",
  "pageText.3bff48a8": "Unterstützt werden HS256 (HMAC-SHA256), HS384 (HMAC-SHA384) und HS512 (HMAC-SHA512) über die native Web-Cryptography-API des Browsers.",
  "pageText.59a40ee3": "Werden meine Signaturgeheimnisse sicher verwahrt?",
  "pageText.e7d3f45b": "Ja. Die gesamte kryptografische Signaturgenerierung erfolgt vollständig lokal in Ihrem Browser. Geheimnisse und Nutzdaten werden niemals an einen Server gesendet.",
  "pageText.546b483c": "Was ist Passwortentropie?",
  "pageText.843a4831": "Passwortentropie ist ein mathematisches Maß in Bits für unvorhersehbare Information, das auf der Größe des Zeichensatzes und der Passwortlänge beruht.",
  "pageText.090cc30f": "Kann ich mein Passwort hier sicher eingeben?",
  "pageText.d27c1402": "Ja. Die Analyse erfolgt vollständig lokal in Ihrem Browser mit reinem JavaScript und wird niemals über das Internet übertragen.",
  "pageText.842979bb": "Was ist Regex?",
  "pageText.bf8dc030": "Reguläre Ausdrücke (Regex) sind Muster, mit denen Zeichenkombinationen in Zeichenfolgen gefunden werden. Sie dienen zum Suchen, Ersetzen und Prüfen von Text.",
  "pageText.aa2308ec": "Welche Regex-Variante wird unterstützt?",
  "pageText.e2719d0a": "Dieser Tester verwendet die JavaScript-RegExp-Engine und unterstützt die in Ihrem Browser verfügbare ECMAScript-Syntax und deren Flags. Ungültige Muster werden als Syntaxfehler gemeldet.",
  "pageText.b74b7f86": "Welche Regex-Flags kann ich testen?",
  "pageText.cf4c1cc1": "Sie können die von Ihrem Browser unterstützten Standard-JavaScript-Flags testen, darunter globale Suche, Groß-/Kleinschreibungsunabhängigkeit, Mehrzeilenmodus, dotAll, Unicode und sticky-Suche.",
  "pageText.7f047dab": "Was dieser JavaScript-Regex-Tester macht",
  "pageText.dc90d609": "Dieser Tester kompiliert Muster und Flags mit der JavaScript-RegExp-Engine des Browsers, wendet sie auf den eingegebenen Text an, markiert jeden Treffer und zeigt dessen Anfangsindex und Erfassungsgruppen. Geben Sie das Muster ohne umgebende Schrägstrichbegrenzer ein. Fügen Sie g hinzu, um alle Treffer zu sammeln; ohne g liefert JavaScript nur den ersten Treffer. Prüfen Sie anhand von Trefferzahl und Indizes, ob wiederholte Treffer an den erwarteten Stellen auftreten.",
  "pageText.abd7f336": "Typische Anwendungsfälle",
  "pageText.9dc106a2": "Entwerfen Sie Prüfregeln für Kennungen, Datumsangaben, Protokollzeilen oder andere Texte mit festgelegtem Format.",
  "pageText.1d045840": "Extrahieren Sie wiederholte Werte wie E-Mail-ähnliche Zeichenfolgen, Ticketnummern oder benannte Felder.",
  "pageText.6220ec6f": "Vergleichen Sie die Beachtung der Groß- und Kleinschreibung mit i oder Zeilenanker mit m.",
  "pageText.f40aadec": "Prüfen Sie Erfassungsgruppen, bevor Sie ein Muster in JavaScript- oder TypeScript-Code übernehmen.",
  "pageText.1908e453": "Durchgerechnetes Beispiel",
  "pageText.d2821f39": "Muster: \\b([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\\.[A-Za-z]{2,})\\b. Flags: gi. Testtext: \"Contact Ada at ada@example.com or SUPPORT@EXAMPLE.ORG.\" Das Ergebnis sind zwei markierte Treffer. Erfassungsgruppe 1 enthält jeweils den lokalen Teil, Gruppe 2 die Domain. Das Flag g setzt die Suche nach dem ersten Treffer fort; i macht die Groß- und Kleinschreibung unerheblich.",
  "pageText.d1106dba": "Dieses Werkzeug folgt der im aktuellen Browser verfügbaren ECMAScript-Syntax für reguläre Ausdrücke. Spezifische Konstrukte aus PCRE, Python, .NET oder Java können fehlschlagen oder sich anders verhalten. Ein Treffer beweist nur, dass das Muster passt, nicht, dass eine E-Mail-Adresse, URL, Datumsangabe oder ein anderer Wert semantisch gültig ist. Mehrdeutige verschachtelte Quantifizierer können bei langen Eingaben aufwendiges Backtracking verursachen. Musterprüfung und Testtext bleiben im Browser. Vermeiden Sie dennoch sensible Produktionsdaten auf gemeinsam genutzten Geräten.",
  "pageText.17c97676": "Warum Regex-Zeichen maskieren?",
  "pageText.c7a9a784": "Zeichen wie ., *, +, ?, (, ), [, ], {, }, ^, $, | und der Rückstrich haben in einem regulären Ausdruck eine strukturelle Bedeutung. Ein vorangestellter Rückstrich bewirkt, dass das erzeugte Musterfragment diese Zeichen wörtlich erfasst.",
  "pageText.b46e6b9b": "Wann sollte ich dieses Werkzeug verwenden?",
  "pageText.bbf26d2d": "Verwenden Sie es, bevor Sie vertrauenswürdigen oder nicht vertrauenswürdigen wörtlichen Text in einen größeren regulären JavaScript-Ausdruck einfügen. Die Maskierung verhindert, dass der eingefügte Text die Musterstruktur verändert. Der umgebende Ausdruck kann trotzdem ineffizient oder falsch sein.",
  "pageText.6df59a98": "Interpretiert das Aufheben der Maskierung Sequenzen wie \\n oder \\d?",
  "pageText.9a3e444a": "Nein. Es macht nur die von diesem Werkzeug erzeugten Maskierungen von Metazeichen und Schrägstrichen rückgängig. Regex-Tokens und Zeichenfolgen-Escapes mit möglicherweise anderer Bedeutung bleiben bewusst erhalten.",
  "pageText.f457f978": "Was „Regex maskieren“ erzeugt",
  "pageText.6ac46463": "Die Maskierungsoperation stellt JavaScript-Regex-Metazeichen einen Rückstrich voran und maskiert außerdem / für die bequeme Verwendung in einem /pattern/-Literal. Beispielsweise wird price (USD) + tax? zu price \\(USD\\) \\+ tax\\?. Das Ergebnis ist ein Musterfragment. Flags, Anker, Erfassungsgruppen und der umgebende Ausdruck bleiben Ihre Verantwortung.",
  "pageText.00aef4ad": "Sicherheitsgrenze dynamischer Muster",
  "pageText.dcb7c0ee": "Maskieren Sie nur den wörtlichen Textanteil. Maskieren Sie keine Operatoren, die Sie absichtlich darum setzen, etwa ^, $ oder eine Erfassungsgruppe.",
  "pageText.3f76d13b": "Die Maskierung verhindert das Einschleusen von Regex-Syntax aus diesem Fragment. Sie verhindert jedoch kein katastrophales Backtracking, das an anderer Stelle im endgültigen Muster entsteht.",
  "pageText.c4d0eb41": "JavaScript-RegExp-Syntax unterscheidet sich von PCRE, Python, .NET, Java und anderen Engines. Testen Sie das endgültige Muster in derselben Laufzeitumgebung, in der es ausgeführt wird.",
  "pageText.8dd960d4": "Wird das Muster in eine JavaScript-Zeichenfolge eingesetzt, ist die Maskierung im Quellcode eine zusätzliche, von der Regex-Maskierung getrennte Ebene.",
  "pageText.90550320": "Grenzen beim Aufheben der Maskierung und beim Datenschutz",
  "pageText.ccd0ec75": "Das Aufheben der Maskierung ist bewusst zurückhaltend: Ein Rückstrich wird nur vor Satzzeichen entfernt, die die Maskierungsoperation behandelt. Es parst keinen vollständigen regulären Ausdruck und wandelt Tokens wie \\d, \\b, \\n oder Unicode-Escapes nicht in Text um. Die Verarbeitung bleibt im Browser. Der Umgang mit der Zwischenablage und dem Zielcode liegt außerhalb des Werkzeugs.",
  "pageText.a0a4fe42": "Wie funktioniert der Textvergleich?",
  "pageText.e1159d8d": "Er vergleicht die beiden Eingaben zeilenweise, kennzeichnet hinzugefügte, entfernte und geänderte Zeilen und hebt anschließend kleinere Änderungen innerhalb bearbeiteter Zeilen hervor.",
  "pageText.e5a7ece5": "Kann ich mit diesem Werkzeug Code vergleichen?",
  "pageText.4f90c315": "Ja. Fügen Sie Code, Konfigurationen oder Fließtext in die beiden Editoren ein. Verwenden Sie „Leerraum ignorieren“ oder „Groß-/Kleinschreibung ignorieren“, wenn diese Unterschiede unerheblich sind.",
  "pageText.74bef405": "Kann ich zwei Dateien vergleichen?",
  "pageText.c6806514": "Öffnen Sie jede Datei in einem Editor, kopieren Sie den Inhalt und fügen Sie ihn in die Bereiche „Original“ und „Geändert“ ein. Der Vergleich arbeitet mit Text, sodass jedes reine Textformat geeignet ist, etwa JSON, YAML, CSV und Quellcode.",
  "pageText.e1647322": "Ignoriert „Leerraum ignorieren“ auch Leerzeilen?",
  "pageText.88417b29": "Nein. Es fasst Folgen von Leerzeichen und Tabulatoren zusammen und entfernt Leerraum am Anfang und Ende jeder Zeile vor dem Vergleich. Einrückungen und abschließende Leerzeichen zählen dadurch nicht mehr als Änderungen. Eine hinzugefügte oder entfernte Leerzeile erscheint jedoch weiterhin als Änderung.",
  "pageText.80c2c0e8": "Wie unterscheidet sich das von git diff?",
  "pageText.612015ce": "Beide ermitteln die längste gemeinsame Folge unveränderter Zeilen. Dieses Werkzeug ordnet zusätzlich ähnliche entfernte und hinzugefügte Zeilen als Änderungen einander zu und markiert die genau geänderten Zeichen. Das macht kurze Bearbeitungen leichter lesbar. Für Commits und Patches bleibt git diff maßgeblich.",
  "pageText.083d5e45": "Wird mein Text hochgeladen?",
  "pageText.5e441495": "Nein. Der Vergleich erfolgt in Ihrem Browser; keine der Eingaben wird an einen Server gesendet.",
  "pageText.8ab4cd08": "Zwei Zeichenfolgen oder längere Dokumente vergleichen",
  "pageText.19e9243c": "Fügen Sie links den ursprünglichen und rechts den überarbeiteten Text ein. Der Vergleich aktualisiert sich, sobald Sie eine Eingabe bearbeiten. Die geteilte Ansicht zeigt zugehörige Zeilen nebeneinander und scrollt beide Bereiche gemeinsam. Die vereinte Ansicht zeigt einen durchgehenden Vergleich, in dem auf jede entfernte Zeile ihr Ersatz folgt. Wenn Sie die Eingaben vertauscht eingefügt haben, tauscht die entsprechende Schaltfläche sie aus.",
  "pageText.06dc44b8": "So werden Änderungen erkannt",
  "pageText.40ccc1ca": "Das Werkzeug ermittelt zunächst die längste gemeinsame Teilfolge von Zeilen und kennzeichnet jede Zeile als unverändert, hinzugefügt oder entfernt. In jedem Änderungsblock werden hinreichend ähnliche entfernte und hinzugefügte Zeilen als bearbeitete Zeilen einander zugeordnet. Eine bearbeitete Zeile erscheint so als eine Änderung statt als Löschung und Einfügung. Anschließend werden diese Zeilen genauer verglichen: Zeilen mit weniger als 80 Zeichen zeichenweise, längere Zeilen wortweise, sofern „Zeichenebene“ nicht aktiviert ist, um die genaue Zeichenansicht zu erzwingen. Eine Übersicht zählt hinzugefügte, entfernte, bearbeitete und unveränderte Zeilen.",
  "pageText.3ba03012": "Optionen für unübersichtliche Vergleiche",
  "pageText.fa1650de": "„Leerraum ignorieren“ fasst Folgen von Leerzeichen und Tabulatoren zusammen und entfernt Leerraum am Zeilenanfang und -ende. Neue Einrückungen und abschließende Leerzeichen zählen dadurch nicht als Änderungen. a b und ab werden dabei nicht als gleich behandelt.",
  "pageText.40e7b499": "„Groß-/Kleinschreibung ignorieren“ vergleicht Zeilen unabhängig von Groß- und Kleinbuchstaben. Das hilft etwa bei SQL-Schlüsselwörtern oder Namen von Umgebungsvariablen.",
  "pageText.6c540dae": "„Nur Änderungen anzeigen“ blendet unveränderte Zeilen aus. „Zeilen umbrechen“ hält lange Zeilen ohne horizontales Scrollen lesbar.",
  "pageText.15884c41": "Aus Windows-Dateien kopierter Text kann am Ende jeder Zeile ein Wagenrücklaufzeichen enthalten. Aktivieren Sie „Leerraum ignorieren“, wenn gleich aussehende Zeilen als geändert gemeldet werden.",
  "pageText.4010b374": "Unterschiede prüfen und teilen",
  "pageText.796a0a49": "„Vergleich kopieren“ erzeugt eine reine Textauflistung: Unveränderte Zeilen beginnen mit zwei Leerzeichen, entfernte mit - und hinzugefügte mit +.",
  "pageText.97594ef5": "Die Kopie entspricht der aktuellen Ansicht. Wenn „Nur Änderungen anzeigen“ aktiviert ist, werden daher nur die geänderten Zeilen kopiert.",
  "pageText.314e11fa": "Durch „Groß-/Kleinschreibung ignorieren“ oder „Leerraum ignorieren“ ausgeblendete Unterschiede werden nicht aufgelistet. Prüfen Sie deshalb die Optionen, bevor Sie das Ergebnis teilen.",
  "pageText.5b3a3d4f": "Was ist Markdown?",
  "pageText.d5d009f0": "Markdown ist eine einfache Auszeichnungssprache zum Erstellen formatierter Texte in einem reinen Texteditor. Sie wird häufig für Dokumentationen, README-Dateien und das Verfassen von Inhalten verwendet.",
  "pageText.bde3ab4d": "Kann ich das HTML exportieren?",
  "pageText.ed93a679": "Ja. Sie können das bereinigte Fragment kopieren oder ein eigenständiges HTML-Dokument mit einfachen responsiven Stilen herunterladen. Prüfen Sie exportierten Markup und Links, bevor Sie sie in einem anderen Sicherheitskontext veröffentlichen.",
  "pageText.0098beeb": "Ist eine Vorschau von unverarbeitetem HTML in Markdown sicher?",
  "pageText.1737e56a": "Die gerenderte Ausgabe wird mit DOMPurify bereinigt. Skripte, Formulare, iframes, style-Attribute und andere Elemente mit hohem Risiko werden entfernt. Verlinkte Bilder sind standardmäßig blockiert. Wenn Sie sie aktivieren, können deren Hosts kontaktiert werden; das Öffnen eines Links kontaktiert weiterhin dessen Ziel.",
  "pageText.bee7691f": "Was die Markdown-Vorschau unterstützt",
  "pageText.441669ae": "Der Renderer verwendet GitHub Flavored Markdown mit Unterstützung für harte Zeilenumbrüche. Überschriften, Hervorhebungen, Links, Bilder, nummerierte und unnummerierte Listen, Aufgabenlisten, Tabellen, Zitatblöcke, Inline-Code, abgegrenzte Codeblöcke, Durchstreichungen und horizontale Linien lassen sich während der Eingabe anzeigen. Die HTML-Ansicht zeigt das erzeugte bereinigte Fragment, statt Markdown als Code auszuführen.",
  "pageText.03de3ac0": "Grenzen von Bereinigung und Veröffentlichung",
  "pageText.a8213d5f": "DOMPurify entfernt vor der Vorschau oder dem Export Skripte, Formulare, Frames, eingebettete Objekte, style-Elemente, style-Attribute und anderen unzulässigen Markup.",
  "pageText.1e94d374": "Die Bereinigung hängt vom Kontext ab. Bereinigen oder rendern Sie die Ausgabe erneut sicher, wenn eine andere Anwendung sie verändert, mit Vorlagen kombiniert oder in einen anderen Kontext als HTML einfügt.",
  "pageText.c384685e": "Eine Syntaxhervorhebung erfolgt nicht. Sprachbezeichnungen abgegrenzter Codeblöcke bleiben nur als Markup-Hinweise erhalten.",
  "pageText.7f8e5143": "Verlinkte Bilder werden durch einen sichtbaren Platzhalter ersetzt, sofern Sie sie nicht ausdrücklich erlauben. Relative Links und andere Ressourcen werden weiterhin entsprechend der Seite aufgelöst, auf der das exportierte HTML geöffnet wird.",
  "pageText.9ab93c5c": "Hinweis zu Datenschutz und externen Ressourcen",
  "pageText.da04b65a": "Markdown-Verarbeitung und Bereinigung erfolgen lokal; dieses Werkzeug lädt den Text nicht hoch. Verlinkte Bilder sind standardmäßig blockiert. Wenn Sie sie aktivieren, kann der Browser die Bildhosts kontaktieren und Verbindungsmetadaten wie Ihre IP-Adresse offenlegen. Die Vorschau setzt no-referrer- und Lazy-Loading-Hinweise. Das Öffnen eines Links, der Zwischenablageverlauf, heruntergeladene Dateien, Browsererweiterungen und der Ort, an dem Sie exportiertes HTML veröffentlichen, sind separate Datenwege.",
  "pageText.fd136c59": "Welche Schreibweisen werden unterstützt?",
  "pageText.972118df": "Dieses Werkzeug unterstützt camelCase, PascalCase, kebab-case, snake_case, CONSTANT_CASE, space case und dot.case.",
  "pageText.8e8d253c": "Was ist camelCase?",
  "pageText.0c0fc023": "camelCase verbindet Wörter ohne Trennzeichen, beginnt mit einem Kleinbuchstaben und schreibt den ersten Buchstaben jedes folgenden Wortes groß, etwa userProfileId. Das ist die übliche Schreibweise für JavaScript- und Java-Variablen.",
  "pageText.fab0fc0e": "Was ist der Unterschied zwischen snake_case und kebab-case?",
  "pageText.ffa6d712": "Beide verwenden Kleinbuchstaben. snake_case trennt Wörter durch Unterstriche (user_profile_id) und ist in Python und SQL verbreitet. kebab-case verwendet Bindestriche (user-profile-id) und ist in URLs und CSS verbreitet. In den meisten Sprachen eignet es sich nicht für Variablennamen, weil - den Minusoperator bezeichnet.",
  "pageText.83ad6918": "Warum wird TEXT IN GROSSBUCHSTABEN ungewöhnlich in camelCase umgewandelt?",
  "pageText.20a709bd": "camelCase und PascalCase behalten vorhandene Großbuchstaben bei, sodass HELLO_WORLD zu hELLOWORLD wird. Wandeln Sie die Eingabe zuerst in snake_case oder space case um (hello_world) und das Ergebnis anschließend in camelCase, um helloWorld zu erhalten.",
  "pageText.8b5b532b": "Welche Schreibweise sollte ich für Umgebungsvariablen verwenden?",
  "pageText.d1aa7699": "CONSTANT_CASE, etwa DATABASE_URL. Großbuchstaben, Ziffern und Unterstriche sind die portable Konvention für Namen von Umgebungsvariablen auf Unix-ähnlichen Systemen.",
  "pageText.45c5778c": "Welche Schreibweise eignet sich am besten für URLs?",
  "pageText.a79aed09": "kebab-case. Durch Bindestriche getrennte Wörter in Kleinbuchstaben sind gut lesbar. Google empfiehlt Bindestriche statt Unterstrichen zur Worttrennung in URLs.",
  "pageText.05244f1a": "Namenskonventionen und ihre Einsatzgebiete",
  "pageText.a6b96046": "camelCase (userProfileId): Variablen und Funktionen in JavaScript und Java sowie JSON-Schlüssel in vielen APIs.",
  "pageText.fdfeef9a": "PascalCase (UserProfileId): Klassennamen, TypeScript-Typen, React-Komponenten und C#-Member.",
  "pageText.664a685d": "snake_case (user_profile_id): Variablen und Funktionen in Python und Ruby sowie SQL-Spaltennamen.",
  "pageText.88ba7528": "CONSTANT_CASE (USER_PROFILE_ID): Konstanten und Umgebungsvariablen.",
  "pageText.d95625b3": "kebab-case (user-profile-id): URL-Slugs, CSS-Klassennamen, HTML-Attribute und Kommandozeilen-Flags.",
  "pageText.0eab35c7": "dot.case (user.profile.id): Konfigurationsschlüssel und IDs für Übersetzungsnachrichten.",
  "pageText.6428569e": "space case (user profile id): einfache Wörter in Kleinbuchstaben für Beschriftungen oder die weitere Bearbeitung.",
  "pageText.a1ccbb20": "So werden Wörter erkannt",
  "pageText.eb52946f": "Der Konverter trennt Wörter an Leerzeichen, Bindestrichen, Unterstrichen und Punkten sowie dort, wo auf einen Kleinbuchstaben ein Großbuchstabe folgt. user_profile-id, userProfileId und User Profile Id ergeben deshalb dasselbe snake_case-Ergebnis: user_profile_id. Ziffern bleiben mit dem benachbarten Wort verbunden. api-v2 response wird daher in camelCase zu apiV2Response und in snake_case zu api_v2_response.",
  "pageText.3ec8336a": "Zu prüfende Sonderfälle",
  "pageText.7af4b6f9": "Folgen von Großbuchstaben zählen als ein Wort: XMLHttpRequest wird zu xmlhttp-request, nicht zu xml-http-request. Fügen Sie Trennzeichen ein (XML Http Request), wenn die Abkürzung aufgeteilt werden soll.",
  "pageText.ac6701e0": "camelCase und PascalCase behalten vorhandene Großbuchstaben bei. Wandeln Sie Eingaben in GROSSBUCHSTABEN daher zuerst in snake_case und dann in camelCase um.",
  "pageText.4ac21c06": "Satzzeichen außer - _ . und Leerzeichen bleiben erhalten: Hello World! wird in camelCase zu helloWorld!. Entfernen Sie Zeichen, die in Kennungen nicht erlaubt sind.",
  "pageText.0bc340ed": "Zeilenumbrüche zählen als Leerraum. Mehrzeilige Eingaben werden daher zu einer einzigen Kennung verbunden. Wandeln Sie jeweils nur einen Namen um.",
  "pageText.83b3cb6b": "Nur A–Z werden als Wortgrenzen durch Großbuchstaben erkannt. Ein Großbuchstabe mit Akzent wie É innerhalb eines Wortes beginnt daher kein neues Wort.",
  "pageText.c7cb896c": "Namen in Code umwandeln",
  "pageText.e93e8bdd": "JavaScript: lodash bietet camelCase, kebabCase und snakeCase. Lodash schreibt zunächst jedes Wort klein, weshalb camelCase('HELLO_WORLD') dort helloWorld liefert.",
  "pageText.2245868e": "APIs: Lassen Sie Nutzdatenschlüssel vom Serializer zuordnen, statt sie von Hand umzubenennen, etwa mit Jackson PropertyNamingStrategies.SNAKE_CASE in Java oder einem Alias-Generator in Pydantic.",
  "pageText.30d85b7e": "Refactoring: Benennen Sie Kennungen mit dem Umbenennungsbefehl Ihres Editors um statt durch Suchen und Ersetzen, damit Verweise in anderen Dateien ebenfalls aktualisiert werden.",
  "pageText.a7bd2d40": "Was wird gezählt?",
  "pageText.51bef002": "Wörter, Zeichen mit und ohne Leerzeichen, Zeilen, Sätze und Absätze sowie eine geschätzte Lesezeit. Alle Zahlen aktualisieren sich während der Eingabe.",
  "pageText.051f4a91": "Wie wird die Lesezeit berechnet?",
  "pageText.87fbca18": "Die Wortzahl wird durch eine durchschnittliche Lesegeschwindigkeit von 200 Wörtern pro Minute geteilt und auf die nächste volle Minute aufgerundet. 450 Wörter werden deshalb als 3 Minuten angezeigt.",
  "pageText.b3ed5e8b": "Enthält die Zeichenzahl Leerzeichen?",
  "pageText.b1bd314d": "Die Angabe „Zeichen“ enthält Leerzeichen, Tabulatoren und Zeilenumbrüche. „Zeichen ohne Leerzeichen“ schließt sämtlichen Leerraum aus. Prüfen Sie vor dem Kürzen, welche Angabe ein Formular oder eine Stilrichtlinie meint.",
  "pageText.1dd1b66b": "Warum zählt ein Emoji als zwei Zeichen?",
  "pageText.75918985": "Zeichen werden wie bei der JavaScript-Zeichenfolgenlänge in UTF-16-Codeeinheiten gezählt. Die meisten Emojis und manche seltenen Symbole benötigen zwei Codeeinheiten und erhöhen die Gesamtzahl deshalb um 2. Kombinierte Emojis wie Familien- oder Flaggenfolgen können mehr beitragen.",
  "pageText.d65fcd89": "Warum ist die Satzzahl höher als erwartet?",
  "pageText.2fc1b39a": "Sätze werden an ., ! und ? getrennt. Abkürzungen wie e.g. oder Dr., Dezimalzahlen wie 3.14 und URLs erzeugen zusätzliche Trennungen. Betrachten Sie die Satzzahl daher als Schätzung.",
  "pageText.1a163ec9": "Wird mein Text gespeichert oder hochgeladen?",
  "pageText.0fef5a83": "Nein. Das Zählen erfolgt in Ihrem Browser. Es wird nichts an einen Server gesendet, und der Text wird beim Verlassen der Seite nicht gespeichert.",
  "pageText.b58e5ca1": "So wird jede Zahl berechnet",
  "pageText.27c1e98e": "Wörter: durch Leerraum getrennte Zeichenfolgen. Wörter mit Bindestrich und Kontraktionen wie well-known oder don't zählen als ein Wort. Eine allein stehende Zahl oder ein Gedankenstrich zählt ebenfalls als Wort.",
  "pageText.b7cde3d8": "Zeichen: jedes Zeichen einschließlich Leerzeichen und Zeilenumbrüchen. „Zeichen ohne Leerzeichen“ schließt sämtlichen Leerraum aus, einschließlich Tabulatoren und Zeilenumbrüchen.",
  "pageText.ac4f81d6": "Zeilen: die Anzahl der Zeilenumbrüche plus eins, einschließlich Leerzeilen.",
  "pageText.dccbe9b3": "Sätze: Textabschnitte, die mit ., ! oder ? enden. Abkürzungen und Dezimalzahlen erzeugen zusätzliche Trennungen.",
  "pageText.ac9536dd": "Absätze: Textblöcke, die durch mindestens eine Leerzeile getrennt sind. Ein einzelner Zeilenumbruch beginnt keinen neuen Absatz.",
  "pageText.c2e627fb": "Lesezeit: Wortzahl geteilt durch 200, auf die nächste volle Minute aufgerundet.",
  "pageText.817a0ebe": "Warum sich Zahlen zwischen Werkzeugen unterscheiden",
  "pageText.ddc50b04": "Textverarbeitungen und Websites verwenden keine einheitliche Definition von Wort oder Zeichen. Manche trennen Wörter mit Bindestrich, ignorieren Zahlen oder behandeln einen langen Gedankenstrich zwischen Wörtern als Trennzeichen. Zeichenbegrenzungen unterscheiden sich noch stärker: Dieses Werkzeug zählt die JavaScript-Zeichenfolgenlänge, bei der die meisten Emojis als zwei zählen. Systeme, die Bytes zählen, etwa manche Datenbankspalten, oder Unicode-Codepunkte, melden für denselben Text andere Gesamtzahlen. Bei Sprachen ohne Leerzeichen wie Chinesisch und Japanisch zählt jede durch Leerraum getrennte Zeichenfolge als ein Wort. Verwenden Sie dafür die Zeichenzahl. Leerraum am Anfang und Ende fügt keine Wörter hinzu, erhöht aber die Zeichenzahl.",
  "pageText.8d394a34": "Text gegen häufige Grenzen prüfen",
  "pageText.14f2e128": "SMS: Ein Segment fasst 160 Zeichen des GSM-7-Alphabets oder 70, wenn die Nachricht Zeichen außerhalb dieses Alphabets enthält, etwa Emojis.",
  "pageText.3ea61033": "Suchvorschauen: Title-Tags werden häufig unter etwa 60 Zeichen und Meta-Beschreibungen bei etwa 150 bis 160 Zeichen gehalten, da Suchmaschinen längere Texte nach Darstellungsbreite kürzen.",
  "pageText.b63f3eaf": "Beiträge in sozialen Medien: Plattformen wie X verwenden eigene Zählregeln, zum Beispiel eine besondere Gewichtung für Links und Emojis. Prüfen Sie deshalb die endgültige Länge im Beitragseditor der Plattform.",
  "pageText.9eea4352": "Aufsätze und Artikel: Wortbegrenzungen beziehen sich gewöhnlich auf den Haupttext. Prüfen Sie, ob Titel, Quellenangaben und Fußnoten mitzählen.",
  "pageText.2ad739ba": "Wie funktioniert das Erkennen von Duplikaten?",
  "pageText.a0e337c4": "Das Werkzeug vergleicht jede Zeile und behält nur das erste Vorkommen. Sie können die Beachtung der Groß- und Kleinschreibung sowie das Entfernen von Leerraum am Anfang und Ende ein- oder ausschalten.",
  "pageText.465a3722": "Was passiert mit Leerzeilen?",
  "pageText.818a7fb1": "Leerzeilen bleiben an ihren ursprünglichen Positionen erhalten.",
  "pageText.ee732984": "Wie funktioniert die Sortierung?",
  "pageText.05cacbdc": "Zeilen werden alphabetisch durch einen Unicode-Zeichenvergleich sortiert. Sie können aufsteigende oder absteigende Reihenfolge wählen.",
  "pageText.f14a257f": "Beachtet die Sortierung Groß- und Kleinschreibung?",
  "pageText.5bc0fcf2": "Standardmäßig unterscheidet die Sortierung nicht zwischen Groß- und Kleinbuchstaben. Sie können die Beachtung der Groß- und Kleinschreibung in den Optionen aktivieren.",
  "pageText.e0ce4b55": "Warum unterscheidet sich die UTF-8-Bytezahl von der Zeichenzahl?",
  "pageText.cea04185": "Standard-ASCII-Zeichen benötigen jeweils 1 Byte. Buchstaben mit Akzenten, etwa é und ç, benötigen 2 Bytes, Emojis wie 🚀 und 🎉 benötigen 4 Bytes in UTF-8.",
  "pageText.58a712ea": "Wie funktioniert die Prüfung von Datenbankspaltengrenzen?",
  "pageText.41e8b156": "Sie können Spaltentypen wie VARCHAR(64), VARCHAR(255) oder TEXT auswählen, um zu sehen, wie viele Bytes verbleiben, bevor Datenbank-Zeilengrenzen überschritten werden.",
  "pageText.ae565f86": "Behandelt die englische Titelschreibung kurze englische Präpositionen korrekt?",
  "pageText.24671ad1": "Ja. Wörter wie \"to\", \"a\", \"an\", \"the\", \"in\", \"for\" und \"and\" bleiben gemäß den Regeln des Chicago Manual of Style an den entsprechenden Stellen kleingeschrieben.",
  "pageText.979a2e10": "Welche unsichtbaren Zeichen werden erkannt?",
  "pageText.1c5cc230": "Leerzeichen ohne Breite (U+200B), verbindende Zeichen ohne Breite (U+200D), nicht verbindende Zeichen ohne Breite (U+200C), Byte-Reihenfolgemarkierungen (U+FEFF), bedingte Trennstriche (U+00AD) und Schreibrichtungsmarkierungen.",
  "pageText.07f01c24": "Was macht der cURL-zu-Axios-Konverter?",
  "pageText.d549d86a": "Er wandelt cURL-Befehle aus dem Terminal in übersichtliche Axios-Codebeispiele für JavaScript oder TypeScript um.",
  "pageText.9968e572": "Ja. Die gesamte Umwandlung erfolgt lokal in Ihrem Browser.",
  "pageText.6d5cdf50": "Wie wandle ich Fetch in cURL um?",
  "pageText.daf0662a": "Fügen Sie Ihren fetch()-Code ein. Das Werkzeug gibt automatisch den formatierten cURL-Befehl aus.",
  "pageText.5847b1ec": "Unterstützt es Header und POST-Anfragetexte?",
  "pageText.5ad9f567": "Ja. Header, HTTP-Methoden und JSON-Anfragetexte werden vollständig geparst und beibehalten.",
  "pageText.8215376e": "Wie funktioniert die Umwandlung von JSON in XML?",
  "pageText.92a5e19e": "JSON-Schlüssel und -Werte werden rekursiv in gültige XML-Elemente und -Attribute umgewandelt.",
  "pageText.5ed08f30": "Kann ich das XML-Wurzel-Tag anpassen?",
  "pageText.4df315df": "Ja. Sie können den Namen des Wurzel-Tags und der Tags für Array-Einträge beliebig festlegen.",
  "pageText.293797b5": "Kann ich direkt aus Excel oder Google Sheets einfügen?",
  "pageText.168c9958": "Ja. Kopieren Sie beliebige Tabellenzellen und fügen Sie sie direkt in den Editor ein.",
  "pageText.e63c6336": "Werden Zahlen und boolesche Werte automatisch erkannt?",
  "pageText.e46b649e": "Ja. Zahlenwerte sowie true/false-Werte werden automatisch in native JSON-Typen umgewandelt.",
  "pageText.a6ffb0f2": "Werden verschachtelte JSON-Objekte unterstützt?",
  "pageText.9c66d528": "Ja. Verschachtelte Objekte werden automatisch mit Schlüsseln in Punktschreibweise abgeflacht.",
  "pageText.8faf9499": "Kann ich als CSV oder TSV exportieren?",
  "pageText.ee9682fe": "Ja. Wählen Sie durch Kommas, Tabulatoren oder Semikolons getrennte Werte.",
  "pageText.a1264c1a": "Ist es sicher, private Fotos umzuwandeln?",
  "pageText.fba7c3f6": "Ja. Die gesamte Bildverarbeitung erfolgt lokal in Ihrem Browser mit HTML5 Canvas. Ihre Fotos verlassen Ihr Gerät nicht.",
  "pageText.2192ee7b": "Welche Formate werden unterstützt?",
  "pageText.893d1681": "PNG, JPEG, WebP, AVIF, BMP und ICO.",
  "pageText.7ae5d66d": "Kann ich die Bilder vor dem Erstellen der PDF neu anordnen?",
  "pageText.c48f2df7": "Ja. Mit den Pfeilschaltflächen auf den Vorschaubildern können Sie die Seitenreihenfolge festlegen.",
  "pageText.1028470b": "Werden meine Bilder auf einen Server hochgeladen?",
  "pageText.43031004": "Nein. Das PDF-Dokument wird vollständig auf der Clientseite in Ihrem Browser erzeugt.",
  "pageText.cafd399d": "Ist das dasselbe wie ein JSON-zu-Golang-Struct-Generator?",
  "pageText.60309daa": "Ja. Go wird oft Golang genannt. Dieses Werkzeug erzeugt Struct-Definitionen mit json-Tags aus beliebigen JSON-Beispielen, einschließlich verschachtelter Objekte und Arrays.",
  "pageText.02bd6e0d": "Kann ich den Namen des Wurzelmodells wählen?",
  "pageText.53e10075": "Ja. Legen Sie den Namen des Wurzelmodells über dem Editor fest. Verschachtelte Objekte werden nach ihren JSON-Schlüsseln benannt. Ein Array aus Objekten auf der obersten Ebene wird anhand seines ersten Elements modelliert.",
  "pageText.5a4c5407": "Enthält die Ausgabe die derive-Makros von serde?",
  "pageText.fa083659": "Ja. Jede Struct leitet Serialize und Deserialize sowie Debug, Clone und Default ab und verwendet serde-rename-Attribute, um die ursprünglichen JSON-Schlüssel beizubehalten. Fügen Sie die Crates serde und serde_json zu Ihrem Projekt hinzu.",
  "pageText.9c425ac2": "Erzeugt der Generator Structs oder Klassen?",
  "pageText.7fc8b986": "Structs. Jedes JSON-Objekt wird zu einer Struct, die Codable und Identifiable erfüllt. Verschachtelte Objekte werden zu verschachtelten Struct-Typen. Prüfen Sie Eigenschaftsnamen und optionale Werte, bevor Sie sie in einer App verwenden.",
  "pageText.8f6dab1d": "Für welche Kotlin-Serialisierungsbibliothek ist die Ausgabe vorgesehen?",
  "pageText.57ebd790": "kotlinx.serialization. Jede erzeugte Datenklasse erhält @Serializable und jede Eigenschaft @SerialName, sodass die JSON-Feldnamen erhalten bleiben.",
  "pageText.cce3877b": "Kann ich C#-Records statt Klassen erzeugen?",
  "pageText.d0862846": "Ja. Wechseln Sie den Ausgabestil zu „Record“, um positionale Records mit [property: JsonPropertyName]-Attributen zu erhalten. Wählen Sie „Klasse“ für veränderliche Klassen mit get- und set-Eigenschaften. Verschachtelte Objekte werden in beiden Stilen zu eigenen Typen.",
  "pageText.ffb3fe14": "Erzeugt der Konverter Ingress- oder ConfigMap-Ressourcen?",
  "pageText.cd91ea98": "Nein. Für jeden erkannten Compose-Dienst erzeugt er ein anfängliches Deployment und einen ClusterIP-Service mit Platzhalter-Image-Tags und Port 80. Passen Sie Images, Ports, Umgebung und Volumes an und ergänzen Sie selbst Ingress, ConfigMaps, Secrets, Probes und Ressourcenlimits, bevor Sie die Manifeste auf einen Cluster anwenden.",
  "pageText.9eac6229": "Was ist ein Unix-Zeitstempel?",
  "pageText.1487701c": "Ein Unix-Zeitstempel ist die Anzahl der Sekunden, die seit dem 1. Januar 1970 (UTC), der sogenannten Unix-Epoche, vergangen sind.",
  "pageText.0789772f": "Sollte ich Sekunden oder Millisekunden verwenden?",
  "pageText.a0e3b7cc": "Unix-Werkzeuge und viele Server-APIs verwenden gewöhnlich Sekunden, während JavaScript Date.now() Millisekunden liefert. Ein aktueller Wert hat daher etwa 10 Stellen in Sekunden und 13 Stellen in Millisekunden. Wählen Sie die Einheit ausdrücklich, statt sie anhand der Stellenzahl zu erraten.",
  "pageText.2eb9e432": "Wie werden Zeitzonen behandelt?",
  "pageText.3d5ad092": "Die Zeitstempelausgabe wird als ISO-8601-Wert in UTC sowie als lokaler Wert in der Browserzeitzone angezeigt. Geben Sie beim Umwandeln von Text in einen Zeitstempel Z oder einen ausdrücklichen Offset an, wenn der gemeinte Zeitpunkt eindeutig sein muss.",
  "pageText.1bc9c5b5": "So funktioniert die Umwandlung von Unix-Zeitstempeln",
  "pageText.0fe51e8a": "Ein Unix-Zeitstempel bezeichnet einen Zeitpunkt relativ zu 1970-01-01T00:00:00Z. Der Konverter akzeptiert eine Ganzzahl in der gewählten Einheit Sekunden oder Millisekunden, wandelt sie in eine ISO-8601-Zeichenfolge in UTC um und formatiert denselben Zeitpunkt zusätzlich in der lokalen Browserzeitzone. Die Rückumwandlung parst eine Datumszeichenfolge und liefert die gewählte Epocheneinheit.",
  "pageText.2dc0bf0f": "Beispiel für Sekunden und Millisekunden",
  "pageText.aae8bcfb": "Die Zeitstempel 1704110400 Sekunden und 1704110400000 Millisekunden bezeichnen denselben Zeitpunkt: 2024-01-01T12:00:00.000Z. Eine falsche Einheit verschiebt den Wert weit außerhalb des beabsichtigten Datums oder macht ihn ungültig. Negative Zeitstempel können unterstützte Daten vor der Unix-Epoche darstellen.",
  "pageText.eee856bc": "Verarbeitungsgrenzen und Genauigkeit",
  "pageText.6d9f9cca": "Die Zeitstempeleingabe muss eine vorzeichenbehaftete sichere JavaScript-Ganzzahl sein. Brüche, Exponentialschreibweise und Ganzzahlen außerhalb des sicheren Bereichs werden abgewiesen.",
  "pageText.38a39d56": "Datumszeichenfolgen ohne Z oder ausdrücklich angegebenen numerischen Offset können in der lokalen Browserzeitzone interpretiert werden. Geben Sie für reproduzierbare Umwandlungen einen Offset an.",
  "pageText.8673caf8": "JavaScript Date arbeitet innerhalb seines unterstützten Kalenderbereichs und bildet keine Schaltsekunden ab.",
  "pageText.77f27ab3": "Die Umwandlung erfolgt lokal. Die angezeigte Ortszeit hängt von der Zeitzoneneinstellung des Geräts und den im Browser verfügbaren historischen Regeln ab.",
  "pageText.9dce9428": "Was ist eine HEX-Farbe?",
  "pageText.808cc6b3": "Eine HEX-Farbe schreibt die Rot-, Grün- und Blaukanäle als jeweils zweistellige Hexadezimalzahlen nach einem #, jeweils von 00 bis FF. #FF5733 bedeutet Rot 255, Grün 87 und Blau 51.",
  "pageText.e9871c7d": "Was ist der Unterschied zwischen RGB und HSL?",
  "pageText.33296696": "RGB definiert eine Farbe über ihre Anteile an rotem, grünem und blauem Licht. HSL beschreibt dieselbe Farbe als Farbtonwinkel, Sättigungsprozentsatz und Helligkeitsprozentsatz. Damit lassen sich hellere, dunklere oder gedämpfte Varianten leichter erzeugen.",
  "pageText.e28100f8": "Wie wandle ich HEX in RGB um?",
  "pageText.fe0c27b9": "Teilen Sie die sechs Stellen in Paare und wandeln Sie jedes aus Basis 16 um: erste Stelle mal 16 plus zweite Stelle. #1E90FF ergibt 1E = 30, 90 = 144, FF = 255, also rgb(30, 144, 255).",
  "pageText.84f954db": "Warum wird #FFF nicht akzeptiert?",
  "pageText.ee7c794e": "Das HEX-Feld erwartet sechs Stellen. Erweitern Sie die dreistellige Kurzform durch Verdoppeln jeder Stelle: #FFF wird zu #FFFFFF und #0AF zu #00AAFF.",
  "pageText.b67270be": "Kann ich Farben mit Transparenz umwandeln?",
  "pageText.4f6be07c": "Mit diesem Werkzeug nicht. Es wandelt deckende Farben um; achtstellige HEX-, rgba()- und hsla()-Werte werden daher nicht unterstützt. Wandeln Sie hier den Farbanteil um und fügen Sie den Alphawert selbst hinzu, etwa rgb(59 130 246 / 50%).",
  "pageText.9ce1a868": "Was ist eine Komplementärfarbe?",
  "pageText.086acf39": "Die gegenüberliegende Farbe im Farbkreis: dieselbe Sättigung und Helligkeit, aber ein um 180 Grad gedrehter Farbton. Der Palettenbereich erzeugt sie zusammen mit analogen, triadischen und geteilten komplementären Varianten.",
  "pageText.e95a3278": "Der Zusammenhang zwischen HEX, RGB und HSL",
  "pageText.b8e6ba16": "Alle drei Formate beschreiben dieselben sRGB-Farben. RGB gibt Rot-, Grün- und Blaukanäle von 0 bis 255 an. HEX schreibt dieselben Kanäle als jeweils zweistellige Hexadezimalpaare. #3B82F6 ist daher rgb(59, 130, 246): 3B = 59, 82 = 130, F6 = 246. HSL beschreibt die Farbe als Farbton (einen Winkel von 0 bis 360 im Farbkreis), Sättigung von 0 bis 100 % und Helligkeit von 0 bis 100 %. Dasselbe Blau ist hsl(217, 91%, 60%). HSL ist praktisch für Varianten: Behalten Sie Farbton und Sättigung bei und ändern Sie nur die Helligkeit, um einen helleren oder dunkleren Ton zu erhalten.",
  "pageText.9bb0180e": "Formate von Hand umwandeln",
  "pageText.20dfb288": "Für HEX zu RGB teilen Sie die sechs Hexadezimalstellen in drei Paare und wandeln jedes Paar aus Basis 16 um. Für #FF5733 gilt: FF = 15 x 16 + 15 = 255, 57 = 5 x 16 + 7 = 87 und 33 = 3 x 16 + 3 = 51. Das ergibt rgb(255, 87, 51). Für RGB zu HEX wandeln Sie jeden Kanal in Hexadezimaldarstellung um und ergänzen einstellige Werte mit einer führenden Null. rgb(0, 128, 255) wird so zu #0080FF. Die HSL-Umwandlung erfordert mehr Berechnungen; hier spart ein Konverter Zeit.",
  "pageText.c627f2e0": "Rundung und Hin- und Rückumwandlungen",
  "pageText.9f7b1c2c": "HSL-Werte werden auf ganze Zahlen gerundet, und jeder RGB-Kanal hat nur 256 Stufen. Mehrere nahe beieinanderliegende HSL-Werte ergeben daher dieselbe RGB-Farbe. Eine Umwandlung von HSL zu RGB und zurück kann einen Wert deshalb um eins verschieben. Wenn exakte Werte wichtig sind, verwenden Sie HEX oder RGB als maßgeblichen Ausgangswert, denn daraus rendert der Browser die Farbe.",
  "pageText.d798a9e9": "Unterstützte Ein- und Ausgaben",
  "pageText.b62d0366": "HEX-Eingaben benötigen sechs Stellen, mit oder ohne führendes #.",
  "pageText.809bb2a0": "RGB- und HSL-Felder akzeptieren ganze Zahlen und begrenzen sie auf ihre gültigen Bereiche.",
  "pageText.9800df6a": "Alphakanäle, benannte Farben wie rebeccapurple, CMYK und neuere CSS-Farbräume wie oklch() werden nicht umgewandelt.",
  "pageText.34fe3200": "Kopierte Werte verwenden CSS-Syntax, etwa #3B82F6, rgb(59, 130, 246) und hsl(217, 91%, 60%). Sie lassen sich daher direkt in ein Stylesheet einfügen.",
  "pageText.03fd111c": "Palettenfelder drehen den Farbton: komplementär um 180 Grad, analog um plus oder minus 30, triadisch um 120 und 240 sowie geteilt komplementär um 150 und 210. Klicken Sie auf ein Farbfeld, um seinen HEX-Wert zu kopieren und zu laden.",
  "pageText.ad112684": "Welcher Bereich wird unterstützt?",
  "pageText.3ed8b237": "Römische Zahlen können Werte von 1 bis 3999 darstellen. Darüber hinaus ist eine besondere Schreibweise erforderlich.",
  "pageText.646816d5": "Wie werden Zahlen gebildet?",
  "pageText.2ae173d7": "Römische Zahlen verwenden mit den Buchstaben I, V, X, L, C, D, M additive Schreibweise (VI = 6) und subtraktive Schreibweise (IV = 4).",
  "pageText.4c9566cb": "Akzeptiert der Konverter Formen wie IIII oder IC?",
  "pageText.7dbeba2f": "Nein. Der Decoder akzeptiert die kanonische Schreibweise römischer Zahlen. 4 muss daher IV und 99 XCIX lauten. Unübliche oder fehlerhafte Formen erzeugen einen Validierungsfehler.",
  "pageText.661774c4": "Wie funktioniert der Konverter für römische Zahlen?",
  "pageText.a2601719": "Im Modus Zahl zu römischer Zahl wird eine ganze Dezimalzahl mit den üblichen subtraktiven Paaren IV, IX, XL, XC, CD und CM auf standardisierte römische Zeichen abgebildet. Im Modus römische Zahl zu Zahl werden die Zeichen gelesen, ihr Wert berechnet und vor der Ausgabe geprüft, ob die Eingabe die kanonische Schreibweise dieses Werts ist.",
  "pageText.3ab2deeb": "Beispiele zur Umwandlung römischer Zahlen",
  "pageText.0cd38bbc": "Die Zahl 4 wird zu IV, 49 zu XLIX, 1994 zu MCMXCIV und 2026 zu MMXXVI. Im umgekehrten Modus werden dieselben römischen Werte wieder zu 4, 49, 1994 und 2026.",
  "pageText.e190ddca": "Bei der subtraktiven Schreibweise steht in den erlaubten Paaren ein kleineres Zeichen vor einem größeren. IX bedeutet beispielsweise 9 und CM 900. Andere Werte werden additiv gebildet. VIII bedeutet daher 5 + 1 + 1 + 1, also 8.",
  "pageText.f97dd159": "Wertebereich und Prüfregeln",
  "pageText.0edecea6": "Dieser Konverter unterstützt ganze Zahlen von 1 bis 3999, den üblichen Bereich ohne Überstriche oder erweiterte Schreibweise. Null, negative Werte, Dezimalbrüche und Zahlen über 3999 werden abgewiesen, statt ihnen ein unübliches Ergebnis zuzuweisen.",
  "pageText.8e949328": "Bei römischen Eingaben ist die Groß- und Kleinschreibung unerheblich, doch sie müssen die kanonische Standardform verwenden. Der Konverter weist unzulässige Wiederholungen und unübliche Kurzformen wie IIII oder IC ab. Diese strenge Prüfung hilft, eine anerkannte römische Zahl von einer Zeichenfolge zu unterscheiden, die lediglich römische Zahlbuchstaben enthält.",
  "pageText.bcefa6b3": "Welche Zahlenbasen werden unterstützt?",
  "pageText.7414cdc4": "Dieses Werkzeug unterstützt Dezimal (Basis 10), Hexadezimal (Basis 16), Oktal (Basis 8) und Binär (Basis 2).",
  "pageText.b72bd2ab": "Wie verwende ich Präfixe?",
  "pageText.0e908091": "Sie können Präfixe wie 0x für Hexadezimal, 0o für Oktal und 0b für Binär verwenden. Sie werden automatisch berücksichtigt.",
  "pageText.fc1aa399": "Kann es Ganzzahlen größer als Number.MAX_SAFE_INTEGER umwandeln?",
  "pageText.1a04613d": "Ja. Die Umwandlung verwendet BigInt und prüft die gesamte Eingabe. Große Ganzzahlen bleiben dadurch erhalten, statt gerundet zu werden. Eingaben sind auf 10.000 Stellen begrenzt, damit der Browser reaktionsfähig bleibt. Brüche werden bewusst nicht unterstützt.",
  "pageText.6c46d667": "Kann das Werkzeug URLs ohne Protokoll parsen?",
  "pageText.211d4985": "Ja. Wenn kein Protokoll angegeben ist, versucht das Werkzeug, die Eingabe unter der Annahme von HTTPS zu parsen.",
  "pageText.a249117f": "Unterstützt es wiederholte Abfrageparameter?",
  "pageText.3fa7bebe": "Ja. Wiederholte Abfrageparameter bleiben erhalten und werden als Arrays zurückgegeben.",
  "pageText.974f66ef": "Kann ich eine vollständige URL parsen?",
  "pageText.d840a415": "Ja. Sie können eine vollständige URL einfügen. Das Werkzeug extrahiert und parst den Teil mit der Abfragezeichenfolge.",
  "pageText.de982fa1": "Werden wiederholte Schlüssel unterstützt?",
  "pageText.aacf5366": "Ja. Beim Parsen bleiben wiederholte Schlüssel als Arrays erhalten.",
  "pageText.5ec1335a": "Sind Werte in einer .env-Datei immer Zeichenfolgen?",
  "pageText.f1c07be7": "Umgebungsvariablen sind an der Prozessgrenze Zeichenfolgen. Die optionale Typerkennung erleichtert die JSON-Ausgabe und wandelt nur eindeutige boolesche Werte, Zahlen in JSON-Schreibweise und null um. Lassen Sie sie deaktiviert, wenn Zeichenfolgen exakt erhalten bleiben müssen.",
  "pageText.a47731b1": "Was passiert, wenn ein Schlüssel mehrfach definiert ist?",
  "pageText.683572e4": "Die letzte Definition gewinnt, wie bei vielen dotenv-Implementierungen üblich. Der Konverter zeigt eine Warnung mit beiden Zeilennummern, damit das Duplikat nicht verborgen bleibt.",
  "pageText.837b99bd": "Erweitert dieses Werkzeug Variablen wie ${HOST}?",
  "pageText.40d37465": "Nein. Es parst Werte, interpoliert aber bewusst keine Variablen, führt keine Shell-Ausdrücke aus, liest keine Dateien und kontaktiert keinen Server. Das Erweiterungsverhalten unterscheidet sich zwischen dotenv-Ladern und sollte in der Ziellaufzeit getestet werden.",
  "pageText.2c76582a": "Was der .env- und JSON-Konverter unterstützt",
  "pageText.4f2d45bf": "Im Modus .env zu JSON akzeptiert der Parser Leerzeilen, Kommentare, optionale export-Präfixe, übliche Namen von Umgebungsvariablen, Werte ohne Anführungszeichen sowie Werte in einfachen, doppelten oder Backtick-Anführungszeichen. Escape-Sequenzen für Zeilenumbruch, Wagenrücklauf, Tabulator, Anführungszeichen und Rückstrich in doppelt angeführten Werten werden decodiert. Angeführte Werte können mehrere Zeilen umfassen; Inline-Kommentare außerhalb der Anführungszeichen werden entfernt.",
  "pageText.c5c8e5b3": "Typerkennung und Umgang mit Duplikaten",
  "pageText.1f8452da": "Standardmäßig bleibt jeder geparste Umgebungswert eine Zeichenfolge. Das entspricht der Bereitstellung von Prozessvariablen durch Betriebssysteme.",
  "pageText.6b7c8875": "Die optionale Typerkennung wandelt true, false, null und eindeutige Zahlen in JSON-Schreibweise um. Werte wie 0012 bleiben Zeichenfolgen, damit führende Nullen erhalten bleiben.",
  "pageText.49af1e34": "Wenn ein Schlüssel mehrfach vorkommt, wird der letzte Wert ausgegeben. Eine Warnung weist auf die doppelten Definitionen hin.",
  "pageText.108380d1": "Die JSON-Ausgabe verwendet ein gegen Prototypmanipulation geschütztes Wörterbuch. Besondere Namen wie __proto__ bleiben dadurch gewöhnliche Datenschlüssel.",
  "pageText.f9bf5831": "So wird JSON als dotenv-Text geschrieben",
  "pageText.7723ffc4": "Der Modus JSON zu .env erfordert ein Objekt auf der obersten Ebene mit gültigen Umgebungsvariablennamen als Schlüsseln. Zeichenfolgen werden doppelt angeführt und maskiert. Zahlen und boolesche Werte werden als Literale geschrieben. null wird mit einer Warnung zur leeren Zeichenfolge, und Arrays oder verschachtelte Objekte werden zu angeführten JSON-Zeichenfolgen. Prüfen Sie strukturierte Werte, da die empfangende Anwendung entscheidet, ob und wie sie erneut geparst werden.",
  "pageText.601a8514": "Datenschutz und Unterschiede zwischen Dialekten",
  "pageText.232534d5": "Die Umwandlung erfolgt im Browser; dieses Werkzeug lädt keine Feldwerte hoch. Dotenv-Syntax ist eine Konvention mit Unterschieden zwischen Implementierungen. Interpolation, Befehlsersetzung, Behandlung von export und Maskierungsregeln können zwischen Node.js, Docker, Shells und Framework-spezifischen Ladern variieren. Prüfen Sie die erzeugte Datei mit genau der Laufzeitumgebung, die sie verarbeitet. Verwenden Sie bereinigte Beispiele statt Produktionszugangsdaten.",
  "pageText.5de3368a": "Wie behandelt das Werkzeug SVG-Attribute in React?",
  "pageText.cff1c703": "Alle HTML-/SVG-Attribute mit Bindestrichen, etwa stroke-width, fill-rule und clip-path, werden in gültiges React-camelCase umgewandelt: strokeWidth, fillRule und clipPath. class wird zu className.",
  "pageText.8b4e6d97": "Unterstützt es TypeScript und forwardRef?",
  "pageText.a1b09414": "Ja. Sie können TypeScript-Interfaces, forwardRef-Wrapper und Standard-Prop-Spreads mit einem Klick ein- und ausschalten.",
  "pageText.354d5c2b": "Wie funktioniert CSS clamp()?",
  "pageText.b2935b68": "Die Funktion clamp(min, preferred, max) legt einen bevorzugten Wert anhand der Viewportbreite (vw) fest und begrenzt ihn zwischen Minimum und Maximum.",
  "pageText.b872cb54": "Warum fließende Typografie verwenden?",
  "pageText.4477ab71": "Fließende Typografie skaliert Text gleichmäßig über verschiedene Bildschirmgrößen, ohne sprunghaft zwischen festen Media-Query-Grenzen zu wechseln.",
  "pageText.5025653d": "Welche docker-run-Flags werden unterstützt?",
  "pageText.1aff160c": "Der Konverter parst unter anderem -p/--publish, -v/--volume, -e/--env, --name, --restart, --network, -w/--workdir, -u/--user, --privileged und Argumente für Containerbefehle.",
  "pageText.edeb7b4c": "Ist die Ausgabe für modernes Docker Compose gültig?",
  "pageText.34af0ae3": "Ja. Das erzeugte YAML folgt dem Format der aktuellen Docker-Compose-Spezifikation.",
  "pageText.657d05ae": "Welche SQL-Dialekte werden unterstützt?",
  "pageText.9519e5df": "Der Konverter unterstützt die Dialekte PostgreSQL, MySQL, SQLite und Microsoft SQL Server.",
  "pageText.81282e94": "Wie werden Datentypen erkannt?",
  "pageText.35a0c93d": "Zahlen, boolesche Werte, ISO-Datumszeichenfolgen, Objekte und Textlängen werden über alle Zeilen hinweg analysiert, um passende Spaltendatentypen zu bestimmen.",
  "pageText.7abbc1c1": "Was ist die Standard-Basisschriftgröße für die REM-Berechnung?",
  "pageText.6b49dd1e": "Die Standard-Wurzelschriftgröße des Browsers beträgt 16px (1rem = 16px). Sie können diese Basis im Werkzeug anpassen, wenn Ihr CSS html { font-size: 62.5%; } für eine 10px-Basis oder eine andere Skalierung setzt.",
  "pageText.3ea4c69b": "Was ist der Unterschied zwischen REM und EM?",
  "pageText.f8a454cb": "REM (Root EM) bezieht sich auf die font-size des Wurzelelements <html>. EM bezieht sich dagegen auf die font-size des unmittelbar übergeordneten Containers.",
  "pageText.2d5d624d": "Unterstützt dieses Werkzeug TSV (durch Tabulatoren getrennte Werte)?",
  "pageText.8dd82b44": "Ja. Sie können durch Kommas oder Tabulatoren getrennte Daten direkt aus Tabellenprogrammen wie Excel oder Google Sheets kopieren und einfügen.",
  "pageText.6e30c9b1": "Kann ich Markdown-Tabellen zurück in CSV umwandeln?",
  "pageText.e858f5f7": "Ja. Klicken Sie auf „MD ➔ CSV synchronisieren“, um die Markdown-Tabelle wieder als standardmäßige kommagetrennte Werte zu parsen.",
  "pageText.ccff8026": "Wie werden Tabellenüberschriften erkannt?",
  "pageText.d4655a54": "Der Konverter verwendet automatisch die erste Zeile mit <th>- oder <td>-Elementen als Schlüssel für die resultierenden JSON-Objekte.",
  "pageText.79df7ff1": "Kann ich statt Objekten ein reines 2D-Array ausgeben?",
  "pageText.9dd05233": "Ja. Wechseln Sie das Ausgabeformat zu „2D-Array (Zeilen und Spalten)“, um ein einfaches Matrix-Array ohne benannte Schlüssel zu erhalten.",
  "pageText.939b6803": "Unterstützt dieses Werkzeug INSERT-Anweisungen mit mehreren Zeilen?",
  "pageText.0495ce61": "Ja. Der Konverter verarbeitet mehrzeilige Anweisungen wie INSERT INTO table (col1, col2) VALUES (a, b), (c, d) problemlos.",
  "pageText.444bfcdc": "Bleiben Datentypen wie Zahlen, boolesche Werte und NULL erhalten?",
  "pageText.b9a181b3": "Ja. Zahlen, boolesche Literale (TRUE/FALSE) und NULL-Werte werden automatisch geparst und in native JSON-Datentypen umgewandelt.",
  "pageText.40323ee8": "Wie wird das Seitenverhältnis gekürzt?",
  "pageText.cdbef1c9": "Der Rechner bestimmt den größten gemeinsamen Teiler (ggT) von Breite und Höhe, um das einfachste ganzzahlige Verhältnis zu erhalten. Beispielsweise wird 1920x1080 zu 16:9 gekürzt.",
  "pageText.bc6781c7": "Wie verwende ich die proportionale Größenänderung?",
  "pageText.b80cad0b": "Geben Sie Ihre ursprüngliche Breite und Höhe ein und danach die neue Zielbreite, um die exakte proportionale Zielhöhe automatisch zu berechnen.",
  "pageText.4b28a4e9": "Welche HTML-Elemente werden unterstützt?",
  "pageText.276d9f0c": "Der Konverter unterstützt Überschriften <h1>-<h6>, Fettdruck <strong>/<b>, Kursivschrift <em>/<i>, Links <a>, Bilder <img>, Zitate <blockquote>, Listen <ul>/<ol>/<li>, Codeblöcke <code>/ <pre> und horizontale Linien <hr>.",
  "pageText.6e1afb74": "Werden HTML-Entitäten decodiert?",
  "pageText.ba39602f": "Ja. Übliche Entitäten wie &amp;, &lt;, &gt;, &quot; und &#39; werden in gewöhnliche Zeichen umgewandelt.",
  "pageText.3799edfe": "Behält dieser Konverter Tags für die Codesyntax bei?",
  "pageText.c2365433": "Ja. Codeblöcke (```javascript ... ```) werden zu <pre><code class=\"language-javascript\"> mit korrekt maskierten Zeichen umgewandelt.",
  "pageText.8708ffd7": "Kann ich die erzeugte HTML-Ausgabe herunterladen?",
  "pageText.c459e434": "Ja. Klicken Sie auf das Downloadsymbol, um das umgewandelte Dokument direkt als .html-Datei zu speichern.",
  "pageText.be3a3c63": "Wie genau wird die Datumsdifferenz berechnet?",
  "pageText.d3b0d64f": "Die Berechnungen sind auf Millisekunden genau und basieren auf der nativen JavaScript-Date-API und standardmäßigen UTC-Zeitstempeln.",
  "pageText.af8c07b0": "Kann ich zwischen Zeiteinheiten umrechnen, etwa Stunden in Sekunden?",
  "pageText.8b865303": "Ja. Im interaktiven Bereich zur Einheitenumrechnung können Sie beliebige Mengen gleichzeitig zwischen Millisekunden, Sekunden, Minuten, Stunden und Tagen umrechnen.",
  "pageText.a9fedf31": "Wie werden XML-Attribute in JSON umgewandelt?",
  "pageText.1c4c4809": "Attribute erhalten im JSON-Objekt das Präfix \"@\", etwa @id=\"101\", damit sie bei der Rückumwandlung in XML vollständig erhalten bleiben.",
  "pageText.fa379db8": "Kann ich die Umwandlungsrichtung von JSON zu XML wechseln?",
  "pageText.994016b7": "Ja. Klicken Sie auf „Zu JSON ➔ XML wechseln“, um ein beliebiges gültiges JSON-Objekt wieder in ein formatiertes XML-Dokument umzuwandeln.",
  "pageText.8d1c8c14": "Maskiert dieses Werkzeug einfache Anführungszeichen innerhalb von Werten?",
  "pageText.d9f1c9ca": "Ja. Einfache Anführungszeichen innerhalb von Werten, etwa in O'Connor, werden automatisch durch Verdoppeln maskiert ('' in Standard-SQL), um Syntaxfehler zu verhindern.",
  "pageText.3f01da3d": "Kann ich Zahlenlisten ohne Anführungszeichen formatieren?",
  "pageText.4b94fcb9": "Ja. Wählen Sie „Keine Anführungszeichen (Zahlen / IDs)“ im Auswahlfeld für den Anführungszeichenstil, um Ganzzahl- und Zahlenlisten zu formatieren.",
  "pageText.3d22bc27": "Unterstützt dieses Werkzeug transparente Hintergründe?",
  "pageText.41464a2f": "Ja. PNG und WebP unterstützen vollständige Alphatransparenz. Sie können auch einen deckenden weißen oder schwarzen Hintergrund wählen.",
  "pageText.c16e4c4a": "Wie funktionieren Auflösungsskalierungen wie 2x und 4x?",
  "pageText.e151b8c5": "Das SVG-Vektorbild wird direkt auf ein skaliertes HTML5 Canvas gerendert. So entsteht eine scharfe, pixelgenaue Ausgabe für hohe Pixeldichte ohne Verpixelung.",
  "pageText.b2fcc05a": "Werden meine PDF-Dokumente auf einen Server hochgeladen?",
  "pageText.aea89d9c": "Nein. Der gesamte Decodierungs- und Darstellungsprozess erfolgt lokal in Ihrem Browser mit Blob-URLs und HTML5-iframes in einer Sandbox.",
  "pageText.2a1e46ea": "Werden Präfixe wie data:application/pdf;base64 unterstützt?",
  "pageText.28866c6e": "Ja. Der Konverter erkennt und entfernt automatisch Daten-URI-Präfixe und zusätzlichen Leerraum aus Ihrer Base64-Eingabe.",
  "pageText.9c3e5e8b": "Welche HTML-Attribute werden umgewandelt?",
  "pageText.5c0146bd": "`class` wird zu `className`, `for` zu `htmlFor`, Inline-Stile werden in Objektsyntax umgewandelt (`style={{ width: \"100px\" }}`), und SVG-Attribute wie `stroke-width` werden zu `strokeWidth`.",
  "pageText.1636cff7": "Welche Datenbankdialekte werden unterstützt?",
  "pageText.1763f21a": "PostgreSQL mit doppelt angeführten Kennungen, MySQL mit Kennungen in Backticks sowie allgemeines Standard-SQL.",
  "pageText.bc4069b3": "Wie werden verschachtelte Objekte in GraphQL behandelt?",
  "pageText.38249950": "Verschachtelte JSON-Objekte werden in eigenständige GraphQL-`type`-Definitionen ausgelagert und automatisch über den Feldnamen referenziert.",
  "pageText.d1268a9b": "Erkennt dieses Werkzeug Zahlen und boolesche Werte in TSV automatisch?",
  "pageText.657e3a11": "Ja. Zahlenwerte und boolesche Zeichenfolgen (true/false) werden automatisch in native JSON-Primitivwerte umgewandelt.",
  "pageText.ab767ca9": "Was ist der Unterschied zwischen NDJSON und JSON?",
  "pageText.ac640a73": "NDJSON enthält pro Zeile ein gültiges JSON-Objekt ohne umgebende Array-Klammern. Dadurch eignet es sich ideal zum Streamen großer Protokolldatensätze.",
  "pageText.d53f6e6d": "Was ist Punycode?",
  "pageText.932ba104": "Punycode ist eine in RFC 3492 definierte Codierungssyntax, die Unicode-Zeichen in ASCII-Zeichenfolgen mit dem Präfix \"xn--\" übersetzt. So funktionieren Domains mit nicht englischen Zeichen in älteren DNS-Systemen.",
  "pageText.749281f3": "Spielt das Werkzeug echte Morsezeichen als Töne ab?",
  "pageText.80d0a9ba": "Ja. Mit der Web-Audio-API erzeugt das Werkzeug direkt in Ihrem Browser standardmäßige Sinustöne mit 650 Hz und präzisen Zeitabständen für Punkte und Striche.",
  "pageText.5e8710c7": "Welche Apache-Direktiven werden unterstützt?",
  "pageText.883d775d": "Unterstützt werden RewriteRule mit den Flags R=301 und L, Redirect 301, DirectoryIndex und Header set.",
  "pageText.e91fd411": "Wie groß kann die CSV-Datei sein?",
  "pageText.55e80dd0": "Da die Verarbeitung lokal im Browserspeicher erfolgt, kann das Werkzeug Tausende Zeilen ohne Verzögerung verarbeiten.",
  "pageText.948016f8": "Wie werden SQL-Datentypen auf TypeScript abgebildet?",
  "pageText.73d3bf81": "INTEGER/FLOAT/DECIMAL werden auf number abgebildet, VARCHAR/TEXT/UUID auf string, BOOLEAN auf boolean und TIMESTAMP/DATE auf Date | string.",
  "pageText.b445da7f": "Wie werden verschachtelte Objekte zu .env-Schlüsseln abgeflacht?",
  "pageText.6c4dff36": "Verschachtelte Schlüssel werden mit Unterstrichen verbunden und großgeschrieben. Beispielsweise wird `{ database: { host: \"...\" } }` zu `DATABASE_HOST=\"...\"`.",
  "pageText.a7ac2f25": "Werden Kommas und Anführungszeichen innerhalb von Tabellenzellen behandelt?",
  "pageText.ad06bce3": "Ja. Zellen mit Kommas oder Sonderzeichen werden mit doppelten Anführungszeichen nach RFC 4180 korrekt maskiert.",
  "pageText.c0439e2b": "Welche SQL-Dialekte werden unterstützt?",
  "pageText.9c661bd6": "Standard-SQL, MySQL, MariaDB, PostgreSQL, SQLite, SQL Server (T-SQL), Oracle PL/SQL, BigQuery, Snowflake und Trino/Presto. Wählen Sie den Dialekt Ihrer Abfrage, damit dessen spezifische Syntax erkannt wird.",
  "pageText.898566a5": "Kann ich SQL minimieren?",
  "pageText.bf763dfa": "Ja. „Minimieren“ fasst Leerraum zu einzelnen Leerzeichen zusammen und entfernt Leerzeichen um Kommas, Klammern, = und Semikolons. Kommentare werden nicht entfernt. Löschen Sie daher vorher -- Kommentare, sonst wird alles danach in derselben Zeile ebenfalls auskommentiert.",
  "pageText.17bb729b": "Ändert die Formatierung die Wirkung meiner Abfrage?",
  "pageText.dfdbf373": "Nein. Die Formatierung verändert nur Leerraum und die Groß- und Kleinschreibung von Schlüsselwörtern. Kennungen, Zeichenfolgenliterale und die Reihenfolge der Klauseln bleiben unverändert. Die Abfrage wird niemals ausgeführt.",
  "pageText.e673de04": "Warum erhalte ich einen Parsefehler?",
  "pageText.f3989307": "Der gewählte Dialekt erkennt einen Teil der Syntax nicht, oder ein Anführungszeichen oder eine Klammer hat kein passendes Gegenstück. Wechseln Sie zu dem Dialekt, für den die Abfrage geschrieben wurde. Vorlagensyntax wie {{ }} aus dbt oder Jinja lässt sich möglicherweise nicht parsen.",
  "pageText.34719ea5": "Kann ich mit Tabulatoren einrücken?",
  "pageText.81ba983d": "Die Ausgabe verwendet immer Leerzeichen. Als Einrückung stehen 2 Leerzeichen, 4 Leerzeichen oder eine Tabulatorbreite von 8 Leerzeichen zur Verfügung.",
  "pageText.568926d9": "Wird mein SQL an einen Server gesendet?",
  "pageText.4517bb93": "Nein. Die Formatierung erfolgt in Ihrem Browser mit der JavaScript-Bibliothek sql-formatter. Es wird keine Datenbankverbindung hergestellt.",
  "pageText.9945834b": "Was der Formatierer ändert",
  "pageText.0cac9d90": "Der Formatierer zerlegt Ihr SQL für den gewählten Dialekt in Tokens und baut das Layout neu auf. Jede Hauptklausel (SELECT, FROM, JOIN, WHERE, GROUP BY, ORDER BY, LIMIT) beginnt in einer eigenen Zeile. Spaltenlisten und Bedingungen werden darunter eingerückt; mehrere Anweisungen werden durch Leerzeilen getrennt. Beispielsweise wird select id, name from users where active = 1 order by name zu einer Abfrage mit SELECT, FROM, WHERE und ORDER BY in separaten Zeilen sowie id und name unter SELECT eingerückt. Schlüsselwörter werden je nach Option groß- oder kleingeschrieben. Kennungen, Literale und die Klauselreihenfolge werden nicht verändert. Die Abfrage wird nicht gegen ein Datenbankschema geprüft.",
  "pageText.679a0218": "Den richtigen Dialekt wählen",
  "pageText.0dad3f3a": "Dialekte unterscheiden sich bei Anführungszeichen, Operatoren und Parametern. Der Formatierer erkennt nur die Syntax des gewählten Dialekts. Wenn die Formatierung fehlschlägt oder die Ausgabe falsch aussieht, prüfen Sie zuerst, ob der Dialekt zur Datenbank passt. Beispiele für dialektspezifische Syntax:",
  "pageText.94b6656c": "PostgreSQL: :: für Typumwandlungen, Positionsparameter wie $1 und Funktionskörper mit Dollar-Quoting.",
  "pageText.2c576f60": "SQL Server (T-SQL): [Kennungen in eckigen Klammern], TOP und @variables.",
  "pageText.8af13c1a": "MySQL und MariaDB: Kennungen wie `backtick` in Backticks.",
  "pageText.ea0458f2": "BigQuery: Namen wie project.dataset.table in Backticks sowie STRUCT- oder ARRAY-Typen.",
  "pageText.3fb5a202": "Minimieren ist eine Textumwandlung",
  "pageText.fcad398d": "„Minimieren“ fasst jede Folge von Leerraum zu einem einzelnen Leerzeichen zusammen und entfernt Leerzeichen um Kommas, Klammern, = und Semikolons. Es arbeitet mit reinem Text statt geparstem SQL. Das hat zwei Folgen: Erstens werden Kommentare nicht entfernt. Da ein -- Kommentar bis zum Zeilenende reicht, kann das Zusammenfassen der ganzen Abfrage in einer Zeile alles dahinter auskommentieren. Entfernen Sie -- Kommentare daher vor dem Minimieren oder wandeln Sie sie in /* */ um. Zweitens werden auch wiederholte Leerzeichen in Zeichenfolgenliteralen zusammengefasst. Vergleichen Sie das Ergebnis deshalb mit dem Original, wenn Abstände in Zeichenfolgen wichtig sind.",
  "pageText.1191c370": "Kommentare und mehrere Anweisungen",
  "pageText.3cf0e67e": "Beim Formatieren bleibt ein -- Kommentar am Ende einer Codezeile auf dieser Zeile; ganzzeilige Kommentare bleiben an ihrer Position. Mehrere durch Semikolons getrennte Anweisungen werden nacheinander mit Leerzeilen dazwischen formatiert. So können Sie ein vollständiges Migrations- oder Initialdatenskript einfügen und Anweisung für Anweisung prüfen.",
  "pageText.367d147f": "Wie stark kann CSS verkleinert werden?",
  "pageText.62ddee05": "Das hängt von Ihrem Stylesheet ab. Entfernen Sie Kommentare und zusätzlichen Leerraum und vergleichen Sie dann die vom Werkzeug angezeigten Größen von Original und Ausgabe. Bereits kompaktes CSS ändert sich möglicherweise kaum.",
  "pageText.95c1ec0d": "Ist das minimierte CSS gültig?",
  "pageText.5857bc9f": "Die Minimierung verwendet einen CSS-Parser und deaktiviert die Umstrukturierung von Regeln. Prüfen Sie die Ausgabe dennoch auf Ihren eigenen Seiten, bevor Sie sie bereitstellen.",
  "pageText.ed466d2a": "Verändert die Minimierung das Verhalten meines CSS?",
  "pageText.d268f9c7": "Das sollte sie nicht. Die Umstrukturierung von Regeln ist deaktiviert. Selektoren werden daher nicht zusammengeführt und Regeln nicht umgeordnet, sodass die Kaskade wie geschrieben erhalten bleibt. Es werden nur gleichwertige kürzere Formen verwendet, etwa #fff für #ffffff.",
  "pageText.0f9b8560": "Bleiben Lizenzkommentare erhalten?",
  "pageText.3a2460c3": "Nur wenn Sie „Kommentare entfernen“ ausschalten. Ist die Option aktiv, wird jeder Kommentar entfernt, einschließlich /*! */-Lizenzhinweisen. Ist sie ausgeschaltet, bleiben alle Kommentare an ihrer Position.",
  "pageText.f6ab050a": "Kann ich die CSS-Minimierung rückgängig machen?",
  "pageText.f9981fd3": "Mit „Lesbar formatieren“ fügen Sie Zeilenumbrüche und Einrückungen wieder hinzu. Ursprüngliche Kommentare und die exakte Formatierung lassen sich nach dem Entfernen nicht wiederherstellen.",
  "pageText.e39c55b7": "Wird mein CSS hochgeladen?",
  "pageText.5c9957b9": "Nein. CSSO läuft in Ihrem Browser. Das Stylesheet wird deshalb auf Ihrem Gerät minimiert und nicht an einen Server gesendet.",
  "pageText.9649813f": "CSS minimieren, ohne die Build-Konfiguration zu ändern",
  "pageText.de9a37b9": "Fügen Sie ein Stylesheet ein, entscheiden Sie, ob Kommentare entfernt werden sollen, und wählen Sie „Minimieren“. CSSO parst das CSS in einen Syntaxbaum und gibt es kompakt aus, statt Zeichen mit regulären Ausdrücken zu löschen. Die Umstrukturierung von Regeln ist ausgeschaltet: Selektoren werden nicht zusammengeführt und Regeln nicht verschoben. Die angezeigte Verkleinerung vergleicht Zeichenzahlen. Sie schätzt daher den eingesparten Text, nicht die komprimierte Netzwerk-Übertragungsgröße.",
  "pageText.67066e30": "Was kleiner wird",
  "pageText.05d17ac2": "Leerraum, Zeilenumbrüche und Einrückungen zwischen Tokens werden entfernt.",
  "pageText.190686bf": "Das letzte Semikolon jedes Deklarationsblocks entfällt: .a { color: red; } wird zu .a{color:red}.",
  "pageText.c6a90a1b": "Farben werden, soweit möglich, in einer gleichwertigen kürzeren Form geschrieben. Beispielsweise wird #ffffff zu #fff.",
  "pageText.5abe9013": "Einheiten von Längen mit dem Wert null entfallen. margin: 0px 0px wird deshalb zu margin:0 0.",
  "pageText.8fb6a9bc": "Wenn „Kommentare entfernen“ aktiviert ist, werden alle Kommentare gelöscht, einschließlich /*! */-Lizenzhinweisen.",
  "pageText.354dff68": "Selektoren und Werte bleiben ansonsten wie geschrieben. Ungenutzte Regeln werden nicht erkannt oder entfernt, da der Minimierer das HTML nicht kennt, das das Stylesheet verwendet.",
  "pageText.704bf1fa": "Die Ausgabe sicher verwenden",
  "pageText.2ebe9c56": "Kopieren Sie das minimierte CSS in einen Test-Build und prüfen Sie die betroffenen Seiten bei den relevanten Bildschirmgrößen.",
  "pageText.ab5ace02": "Behalten Sie erforderliche Lizenzkommentare bei, indem Sie „Kommentare entfernen“ vor dem Minimieren ausschalten.",
  "pageText.889b86fa": "Verwenden Sie „Lesbar formatieren“ als Lesehilfe. Prüfen Sie komplexes CSS nach der Formatierung, da diese getrennt von der parserbasierten Minimierung erfolgt.",
  "pageText.4040b973": "Minimierung ergänzt die Serverkomprimierung, statt sie zu ersetzen: gzip oder Brotli verkleinern auch die minimierte Datei bei der Übertragung weiter.",
  "pageText.8111e866": "Wann stattdessen ein Build-Werkzeug sinnvoll ist",
  "pageText.4d2afabc": "Wenn Ihr Projekt bereits einen Bundler oder ein Framework verwendet, wird die CSS-Minimierung gewöhnlich dort konfiguriert, etwa mit Lightning CSS, cssnano oder esbuild, und bei jedem Build ausgeführt. Dieses Werkzeug eignet sich für einzelne Stylesheets, CMS- oder Theme-Dateien, in Widgets von Drittanbietern eingefügtes CSS und schnelle Prüfungen der Auswirkungen eines Minimierers auf eine bestimmte Regel. Stylesheets im Dokumentkopf blockieren das Rendering, bis sie geladen sind. Kleinere Dateien beschleunigen deshalb die erste Darstellung bei langsamen Verbindungen. Das Entfernen ungenutzter Regeln spart allerdings oft mehr als die Minimierung allein.",
  "pageText.d083d747": "Welche Optimierungen werden angewendet?",
  "pageText.e796e2d2": "Terser entfernt Leerraum, optionale Semikolons und Kommentare, wertet konstante Ausdrücke vorab aus, entfernt unerreichbaren Code und vereinfacht Bedingungen. Optionale Einstellungen entfernen console.*-Aufrufe und debugger-Anweisungen und verkürzen true und false zu !0 und !1.",
  "pageText.6feece85": "Sollte ich das für die Produktion verwenden?",
  "pageText.f02032e4": "Dieses Werkzeug verwendet Terser zur parsergestützten JavaScript-Minimierung. Für Produktions-Builds sollten Sie die Minimierung weiterhin in einen Bundler wie Webpack, Rollup oder esbuild integrieren.",
  "pageText.9996cfd4": "Kann die Minimierung meinen Code beschädigen?",
  "pageText.1d35f0cc": "Terser wendet nur Umwandlungen an, die das Verhalten gültigen JavaScripts erhalten. Probleme entstehen meist durch Code, der seinen eigenen Quelltext untersucht, etwa mit Function.prototype.toString(), oder durch entfernte console-Aufrufe, die tatsächlich Arbeit ausgeführt haben. Testen Sie die Ausgabe vor der Bereitstellung.",
  "pageText.a33aea1e": "Wie entferne ich console.log aus JavaScript?",
  "pageText.851f8ba7": "Aktivieren Sie „console.* entfernen“ und minimieren Sie den Code. Jeder console-Methodenaufruf wird einschließlich seiner Argumente entfernt, auch console.error und console.warn. Setzen Sie in einem Build compress.drop_console in den Terser-Optionen.",
  "pageText.e005a375": "Warum werden meine Variablennamen nicht verkürzt?",
  "pageText.1c73417a": "Die Namensverkürzung ist ausgeschaltet. Die Ausgabe behält daher lesbare Kennungen zum Debuggen ohne Source Maps. Bundler aktivieren die Namensverkürzung gewöhnlich für die Produktion, um weitere Bytes einzusparen.",
  "pageText.a4388952": "Kann ich TypeScript oder JSX minimieren?",
  "pageText.8bff2c76": "Nein. Terser parst nur JavaScript. Typannotationen und JSX erzeugen daher einen Syntaxfehler. Kompilieren Sie den Code zuerst mit tsc, esbuild, Babel oder SWC und minimieren Sie anschließend die JavaScript-Ausgabe.",
  "pageText.56b9f99f": "Was der Minimierer mit Ihrem Code macht",
  "pageText.55103bdf": "Terser parst den Code in einen Syntaxbaum, führt Komprimierungsschritte aus und gibt das Ergebnis ohne unnötigen Leerraum aus. Die Komprimierung wertet Konstanten vorab aus, entfernt unerreichbaren Code und ungenutzte lokale Variablen, verkürzt Bedingungen und verbindet Anweisungen, wo dies sicher ist. Da der Code geparst statt mit regulären Ausdrücken bearbeitet wird, bleiben Zeichenfolgen, reguläre Ausdrücke und Vorlagenliterale erhalten. Zum Beispiel wird function add(a, b) { return a + b; } // sum zu function add(a,b){return a+b}, und const ok = true; wird bei aktiviertem „Boolesche Werte verkürzen“ zu const ok=!0;.",
  "pageText.0ee8f397": "Die Optionen erklärt",
  "pageText.0a5da22e": "Kommentare entfernen: entfernt jeden Kommentar, einschließlich /*! */-Lizenzhinweisen. Schalten Sie es aus, um alle Kommentare zu behalten, etwa wenn eine Lizenz verlangt, dass der Hinweis beim Code bleibt.",
  "pageText.3fbd5c3f": "console.* entfernen: entfernt Aufrufe wie console.log, console.warn und console.error einschließlich ihrer Argumente. Verlassen Sie sich daher nicht auf Seiteneffekte innerhalb dieser Aufrufe.",
  "pageText.d5ef0e31": "debugger entfernen: löscht debugger-Anweisungen.",
  "pageText.0f7a6693": "Boolesche Werte verkürzen: schreibt true und false als !0 und !1 und vereinfacht boolesche Ausdrücke.",
  "pageText.281f8120": "Was dieses Werkzeug nicht macht",
  "pageText.c178c0f1": "Es benennt keine Variablen um, da die Namensverkürzung ausgeschaltet ist. Die Ausgabe ist dadurch größer als ein typisches Produktionsbundle, aber leichter zu debuggen.",
  "pageText.c4a6b403": "Es erzeugt keine Source Maps und bündelt keine Importe aus anderen Dateien.",
  "pageText.d46a72e1": "Es akzeptiert nur JavaScript. TypeScript und JSX müssen zuerst kompiliert werden.",
  "pageText.059e3a00": "Es transpiliert moderne Syntax nicht für ältere Browser. Optionale Verkettung, Klassenfelder und ähnliche Funktionen bleiben wie geschrieben. Verwenden Sie bei Bedarf Babel oder esbuild mit einer Zielumgebung.",
  "pageText.f406cb39": "„Lesbar formatieren“ ist ein einfacher Neuformatierer, der nach Klammern und Semikolons Zeilenumbrüche einfügt. Er dient dem schnellen Lesen, kann Kommentare und reguläre Ausdrücke falsch behandeln und ersetzt Prettier nicht.",
  "pageText.853950f8": "Die Größenstatistik verstehen",
  "pageText.07b3482d": "Original- und minimierte Größe sind Zeichenzahlen des Texts; die prozentuale Verkleinerung vergleicht sie. Die tatsächliche Einsparung bei der Übertragung ist meist kleiner, weil Server JavaScript üblicherweise mit gzip oder Brotli komprimieren. Dabei werden Leerraum und wiederholte Kennungen bereits verkleinert. Messen Sie die komprimierte Größe Ihrer Build-Datei, wenn Sie genaue Zahlen benötigen.",
  "pageText.c9a86f33": "Was macht der Formatierer?",
  "pageText.7b99d384": "Der Formatierer zerlegt Tags, Kommentare und Text in Tokens und fügt dann Einrückungen und Zeilenumbrüche um erkannte Blockstrukturen ein. Er ist eine Lesehilfe, kein HTML-Parser, Validator, Bereinigungswerkzeug oder Browser-Renderer.",
  "pageText.8c60e5e5": "Kann ich die Einrückungsgröße wählen?",
  "pageText.f45f1451": "Ja. Sie können 2, 4 oder 8 Leerzeichen für die Einrückung wählen.",
  "pageText.b5dc2f5c": "Behebt die Formatierung ungültiges oder unsicheres HTML?",
  "pageText.6bd5634a": "Nein. Sie repariert keine unpassenden Tags, prüft keine Attribute, entfernt keine Skripte und beweist nicht die Sicherheit des Markups. Verwenden Sie einen HTML-Validator und eine zum Kontext passende Bereinigung, wenn Korrektheit oder nicht vertrauenswürdige Inhalte eine Rolle spielen.",
  "pageText.6853bf2a": "Was der HTML-Formatierer ändert",
  "pageText.59f55f70": "Der Formatierer verteilt gewöhnliche Block-Tags auf lesbare Zeilen, belässt eine bekannte Menge von Inline-Elementen beim umgebenden Text, erhält Kommentare und rückt verschachtelte Strukturen mit der gewählten Anzahl von Leerzeichen ein. Der Ausgabebereich zeigt auch Zeichen- und Zeilenzahlen, damit Sie das Ergebnis mit der Eingabe vergleichen können.",
  "pageText.5bc49953": "Formatierer im Vergleich zu Parser oder Validator",
  "pageText.28eb81f1": "Formatierung ändert Leerraum und Layout. Sie erstellt kein Browser-DOM und wendet den HTML-Parsing-Algorithmus nicht an.",
  "pageText.a285b9fa": "Nicht zusammenpassende, ausgelassene oder fehlerhafte Tags werden nicht repariert und können irreführende Einrückungen erzeugen.",
  "pageText.506549f7": "Skripte, Event-Handler-Attribute, unsichere URLs und andere aktive Inhalte bleiben als Text erhalten. Formatierung ist keine Bereinigung.",
  "pageText.525714f9": "Eingebettete script-, style-, template-, SVG- oder Attributinhalte mit spitzen Klammern können die Grenzen des einfachen Tokenizers überschreiten. Sie sollten mit einem parsergestützten Entwicklungswerkzeug behandelt werden.",
  "pageText.4a57b0bb": "Grenzen bei Leerraum und Datenschutz",
  "pageText.3ede26b8": "Leerraum kann in vorformatiertem Text, Inline-Inhalten, Vorlagen, E-Mails und Framework-Direktiven eine Bedeutung haben. Vergleichen Sie das Verhalten im Zielbrowser oder der Vorlagen-Engine, bevor Sie Produktionsquellcode ersetzen. Die Formatierung erfolgt im Browser, und der Editor führt das eingefügte HTML nicht aus. Zwischenablageverlauf, Erweiterungen und spätere Zielorte bleiben jedoch separate Wege, auf denen Daten offengelegt werden können.",
  "pageText.bbd35cbf": "Der Minimierer entfernt HTML-Kommentare und fasst Leerraum zusammen. Sie können wählen, welche Optionen angewendet werden.",
  "pageText.f78988ed": "Wie stark kann HTML verkleinert werden?",
  "pageText.de2adbe4": "Die Minimierung reduziert die HTML-Dateigröße typischerweise um 10–30 %, abhängig von der ursprünglichen Formatierung und der Dichte der Kommentare.",
  "pageText.dc1d729a": "Welche XML-Funktionen werden unterstützt?",
  "pageText.aa014daa": "Der Tokenizer erkennt gewöhnliche Tags, selbstschließende Tags, Kommentare, CDATA-Abschnitte, Verarbeitungsanweisungen und einfache DOCTYPE-Deklarationen. Er löst keine Schemas, Namensräume, Entitäten oder externen DTD-Ressourcen auf.",
  "pageText.e249844a": "Prüft dieses Werkzeug, ob XML wohlgeformt ist?",
  "pageText.c291f4c2": "Nein. Es formatiert tokenähnlichen Markup, führt aber keine standardkonforme XML-Verarbeitung durch. Verwenden Sie einen XML-Parser oder Validator, um nicht zusammenpassende Tags, ungültige Namen, Entitätsfehler, Schemaverletzungen und Namensraumprobleme zu erkennen.",
  "pageText.40d2ec46": "Was der XML-Formatierer ändert",
  "pageText.ac2829ba": "Der Formatierer durchläuft erkennbare XML-Tags und Inhalte, verringert die Einrückung vor schließenden Tags und erhöht sie nach öffnenden Tags. Selbstschließende Tags, Kommentare, CDATA, Verarbeitungsanweisungen und einfache DOCTYPE-Tokens bleiben erhalten. Sie können zwei, vier oder acht Leerzeichen wählen, ohne das Dokument an einen Server zu senden.",
  "pageText.df3aac91": "Formatierung ist keine XML-Validierung",
  "pageText.54105db0": "Das Werkzeug prüft weder ein einzelnes Wurzelelement noch übereinstimmende Tag-Namen, zulässige Attribute, Namensraumbindungen, Entitätsdeklarationen, XSD, DTD oder fachliche Regeln.",
  "pageText.ebba6da6": "Ein formatiertes Ergebnis kann weiterhin fehlerhaftes XML sein. Prüfen Sie es mit dem Parser und Schema des Zielsystems.",
  "pageText.53dced72": "Komplexe interne DTD-Teilmengen und ungewöhnlicher Markup mit > innerhalb von Deklarationen können die Grenzen des einfachen Tokenizers überschreiten.",
  "pageText.6dda43fb": "Externe Entitäten werden nicht aufgelöst. Dadurch werden sie nicht abgerufen, aber auch davon abhängige Korrektheitsprüfungen nicht durchgeführt.",
  "pageText.97f2bab3": "Gemischter Inhalt, Signaturen und Datenschutz",
  "pageText.14bd67e8": "Der Formatierer entfernt Leerraum am Anfang und Ende von Text-Tokens und fügt Leerraum ein. Dokumente mit gemischtem Inhalt, in denen Leerzeichen semantisch relevant sind, müssen daher sorgfältig geprüft werden. Formatieren Sie kein kanonisiertes oder digital signiertes XML, da jede Byteänderung eine Signatur ungültig machen kann. Die Verarbeitung erfolgt lokal. Zwischenablageverlauf, Erweiterungen, gemeinsam genutzte Geräte und der Ort, an dem die Ausgabe eingefügt wird, bleiben separate Risiken.",
  "pageText.fe32a91d": "Wie stark verkleinert SVG-Minimierung die Datei?",
  "pageText.5d39171c": "Abhängig von der Menge an Editormetadaten aus Adobe Illustrator oder Inkscape und überflüssigen Kommentaren sinken SVG-Dateigrößen häufig um 30 % bis 70 %.",
  "pageText.96ecd07b": "Beeinträchtigt die Minimierung die sichtbare Qualität?",
  "pageText.a917f319": "Nein. Der Minimierer erhält die wesentlichen sichtbaren Vektoren und Kurven und rundet zugleich überflüssige mehrstellige Dezimalwerte für eine pixelgenaue Darstellung.",
  "pageText.b7b3cc9a": "Welche Metadaten werden bei der Optimierung entfernt?",
  "pageText.66896ba8": "Der Optimierer entfernt XML-Deklarationen, DOCTYPE-Köpfe, HTML-/XML-Kommentare und editorspezifische Attribute aus Adobe Illustrator, Figma, Inkscape und Sketch.",
  "pageText.78172982": "Kann ich das optimierte SVG vor dem Herunterladen ansehen?",
  "pageText.390681e1": "Ja. Unter dem Editor wird eine laufend aktualisierte gerenderte SVG-Vorschau angezeigt, damit Sie die Darstellungsqualität prüfen können.",
  "pageText.0b1fe2c2": "Verändert die SQL-Minimierung die Abfragelogik oder Ergebnisse?",
  "pageText.e4ef1b07": "Nein. Sie entfernt nur nicht ausführbare Kommentare und fasst Leerraum um Operatoren und Klammern zusammen.",
  "pageText.9b592f46": "Warum JSON minimieren?",
  "pageText.ed32b385": "Minimiertes JSON reduziert die Byte-Übertragungsgröße um 20 % bis 50 %. Das beschleunigt API-Antworten und senkt Speicherkosten.",
  "pageText.c0fed95c": "Wie stark kann ich meine Bildgröße reduzieren?",
  "pageText.e029d2f5": "Abhängig von Bild und Format, etwa WebP, lassen sich typischerweise 50 % bis 80 % der Dateigröße einsparen.",
  "pageText.9d6eb265": "Ja. Alles wird lokal in Ihrem Browser verarbeitet, ohne Hochladen auf einen Server.",
  "pageText.9da1e25c": "Wie funktioniert das Extrahieren einer Farbpalette?",
  "pageText.6856aaf1": "Es erfasst Stichproben der Bildpixeldaten und gruppiert Farben mit einer schnellen Farbquantisierung zu dominanten Clustern.",
  "pageText.a4364887": "Kann ich bestimmte Pixelfarben untersuchen?",
  "pageText.f7f9cfc5": "Ja. Klicken Sie in der Bildvorschau auf eine beliebige Stelle, um mit der Pipette die exakte Pixelfarbe auszuwählen.",
  "pageText.a35b5925": "Ist es sicher, sensible PDF-Dokumente zusammenzuführen?",
  "pageText.05bdd01e": "Ja. DevsTools führt PDFs mit pdf-lib vollständig lokal in Ihrem Browser zusammen. Ihre Dokumente werden niemals auf einen Server hochgeladen.",
  "pageText.61e14c97": "Kann ich die Reihenfolge der zusammengeführten PDFs ändern?",
  "pageText.8d1a28fb": "Ja. Mit den Pfeilschaltflächen nach oben und unten können Sie die Dateien vor dem Zusammenführen einfach anordnen.",
  "pageText.0d93721b": "Wie gebe ich Seitenbereiche zum Aufteilen an?",
  "pageText.a635c961": "Geben Sie Seitenbereiche wie \"1-3, 5, 8-10\" ein oder verwenden Sie die Schaltflächen für schnelle Vorlagen.",
  "pageText.478026f0": "Beeinträchtigt das Aufteilen die Dokumentqualität?",
  "pageText.343ad06a": "Nein. Vektortext, eingebettete Bilder und Schriftarten bleiben in ihrer ursprünglichen Qualität erhalten.",
  "pageText.3832da18": "Welche Modelle enthält der Vergleich?",
  "pageText.d5944039": "GPT-4o, GPT-4o-mini, o1, o3-mini, Claude 3.5 Sonnet/Haiku/Opus, Gemini 2.0 Flash, Gemini 1.5 Pro, DeepSeek V3/R1 und Llama 3.3.",
  "pageText.2c0b42c9": "Berechnet es Rabatte für Prompt-Caching?",
  "pageText.1f24b0e5": "Ja. Passen Sie den Schieberegler für den Prompt-Caching-Prozentsatz an, um die rabattierten Kosten für Eingabetokens zu sehen.",
  "pageText.b55124a7": "Unterstützt die Sandbox Tailwind CSS?",
  "pageText.3c96d97b": "Ja. Wählen Sie die Tailwind-Vorlage, um das Tailwind-CDN automatisch einzubinden.",
  "pageText.eea9bb11": "Kann ich mein Sandbox-Projekt exportieren?",
  "pageText.22043773": "Ja. Klicken Sie auf „HTML exportieren“, um ein eigenständiges HTML-Dokument in einer einzigen Datei herunterzuladen.",
  "pageText.08df7b07": "Welches Format verwendet dieses Werkzeug?",
  "pageText.d6dda949": "Dieses Werkzeug verwendet das numerische Cronie-Format mit 5 Feldern: Minute (0–59), Stunde (0–23), Tag des Monats (1–31), Monat (1–12) und Wochentag (0–7, wobei 0 und 7 Sonntag bedeuten). Monats- und Tagesnamen sowie Tilde-Zufallswerte werden nicht unterstützt.",
  "pageText.3ef8cae4": "Was bedeutet */5 * * * *?",
  "pageText.8b55b7bf": "Alle fünf Minuten ausführen: um :00, :05, :10 und so weiter bis :55 in jeder Stunde und an jedem Tag.",
  "pageText.14555971": "Wie führe ich einen Cron-Job täglich um Mitternacht aus?",
  "pageText.555d6847": "Verwenden Sie 0 0 * * *. Das erste Feld ist die Minute, das zweite die Stunde. Der Job läuft deshalb um 00:00 in der Zeitzone des Rechners, auf dem Cron ausgeführt wird.",
  "pageText.ebbbedb4": "Warum läuft mein Job an mehr Tagen als erwartet?",
  "pageText.dd287a29": "Wenn sowohl der Tag des Monats als auch der Wochentag eingeschränkt sind, führt Cron den Job aus, sobald eines der beiden Felder passt. 0 9 1 * 1 läuft am 1. jedes Monats und an jedem Montag. Setzen Sie eines der beiden Felder auf *, um nur das andere zu verwenden.",
  "pageText.4c325954": "Welche Zeitzone verwenden Cron-Jobs?",
  "pageText.1999379a": "Das klassische Crontab verwendet die Systemzeitzone des Servers, häufig UTC. Kubernetes-CronJobs können spec.timeZone setzen; GitHub-Actions-Zeitpläne laufen in UTC. Dieses Werkzeug zeigt die Ausführungen in der Zeitzone Ihres Browsers als Vorschau.",
  "pageText.05cc7746": "Unterstützt es @daily, Sekunden oder L und W?",
  "pageText.df473d06": "Nein. Makros wie @daily und @reboot, ein Sekunden- oder Jahresfeld sowie Quartz-Zeichen wie ?, L, W und # werden abgewiesen. Schreiben Sie @daily als 0 0 * * *.",
  "pageText.1fd13551": "Die fünf Cron-Felder lesen",
  "pageText.33035464": "Ein Standard-Crontab-Zeitplan hat fünf durch Leerzeichen getrennte Felder: Minute (0–59), Stunde (0–23), Tag des Monats (1–31), Monat (1–12) und Wochentag (0–7, wobei sowohl 0 als auch 7 Sonntag bedeuten). Der Befehl hinter dem Zeitplan in einer Crontab-Zeile ist kein Teil des Ausdrucks. Fügen Sie daher nur die fünf Felder ein. Beispielsweise läuft 30 2 * * 1 jeden Montag um 02:30 und 0 9 * * 1-5 von Montag bis Freitag um 09:00. Jedes Feld akzeptiert vier Operatoren:",
  "pageText.016be4a0": "* passt zu jedem Wert im Feld.",
  "pageText.0fb5d225": "Ein Komma bildet eine Liste: 0,30 im Minutenfeld führt um :00 und :30 aus.",
  "pageText.f7efe16b": "Ein Bindestrich bildet einen inklusiven Bereich: 9-17 im Stundenfeld deckt 9 bis 17 Uhr ab.",
  "pageText.0745593a": "Ein Schrägstrich ergänzt * oder einen Bereich um eine Schrittweite: */15 bedeutet alle 15 Minuten; 8-18/2 bedeutet jede zweite Stunde von 8 bis 18.",
  "pageText.1e8af08c": "Tag des Monats und Wochentag: die ODER-Regel",
  "pageText.71a25a12": "Wenn beide Tagesfelder eingeschränkt sind, führt Cron den Job aus, sobald eines passt, nicht nur, wenn beide passen. 0 0 13 * 5 läuft daher um Mitternacht am 13. jedes Monats und außerdem jeden Freitag, nicht nur an Freitag, dem 13. Wenn eines der Tagesfelder mit * beginnt, einschließlich einer Schrittweite wie */2, werden die Felder stattdessen mit UND verknüpft. Dieser Parser folgt derselben Regel wie Cronie und Vixie cron. Die Liste der nächsten Ausführungen zeigt die Wirkung sofort.",
  "pageText.c0ab4e56": "So werden die nächsten Ausführungszeiten berechnet",
  "pageText.79d9be29": "Die nächsten fünf Ausführungen werden in Ihrem Browser in der aktuellen Zeitzone Ihres Geräts berechnet. Jede Zeit wird mit Zeitzonenkürzel angezeigt. Server führen Cron meist in ihrer eigenen Zeitzone aus, häufig UTC. Ein hier um 09:00 angezeigter Job kann auf dem Server daher zu einer anderen Uhrzeit laufen. Zeitumstellungen können eine Ortszeit überspringen, etwa 02:30 beim Wechsel zur Sommerzeit, oder im Herbst eine Zeit wiederholen. Die Vorschau zeigt jedes tatsächliche lokale Vorkommen. Prüfen Sie deshalb, wie Ihr Cron-Daemon diese Übergänge behandelt.",
  "pageText.71055715": "Syntax, die dieser Parser abweist",
  "pageText.941d3d4e": "Monats- und Wochentagsnamen wie JAN oder MON. Verwenden Sie die Zahlen 1–12 und 0–7.",
  "pageText.1155fe27": "Makros wie @hourly, @daily und @reboot.",
  "pageText.aac0ad9e": "Quartz- und Spring-Erweiterungen: ein Sekunden- oder Jahresfeld, ?, L, W und #.",
  "pageText.eb78245f": "Eine Schrittweite auf einem einzelnen Wert wie 5/10. Schreiben Sie stattdessen 5-59/10.",
  "pageText.a20b5d46": "Zufallswerte wie H im Jenkins-Stil oder die ~-Syntax, die manche Cron-Versionen unterstützen.",
  "pageText.01e5036b": "Kann das Werkzeug doppelte Header parsen?",
  "pageText.a5eb4734": "Ja. Doppelte Header-Schlüssel werden in der geparsten JSON-Ausgabe zu Arrays zusammengefasst.",
  "pageText.48b8738b": "Welches Eingabeformat wird erwartet?",
  "pageText.b75acdab": "Verwenden Sie einen Header pro Zeile im Format \"Header-Name: value\".",
  "pageText.3d8017de": "Was sind HTTP-Statuscodes?",
  "pageText.f49da83d": "HTTP-Statuscodes sind standardisierte Serverantworten, die anzeigen, ob eine Anfrage erfolgreich war, fehlgeschlagen ist oder weitergeleitet wurde.",
  "pageText.09b5ad7b": "Welche Statuscodeklassen gibt es?",
  "pageText.ed562809": "1xx: Informationen, 2xx: Erfolg, 3xx: Weiterleitung, 4xx: Clientfehler und 5xx: Serverfehler.",
  "pageText.fc679ed8": "Wie genau ist die User-Agent-Analyse?",
  "pageText.8d6134ab": "Das Werkzeug verwendet den mitgelieferten Regelsatz von UAParser.js 1.0.41. Die Ergebnisse bleiben jedoch heuristisch, da User-Agent-Zeichenfolgen Selbstauskünfte sind, reduziert sein können und sich fälschen lassen.",
  "pageText.14c11e52": "Kann es Bots erkennen?",
  "pageText.ac1e7ccc": "Es erkennt häufige benannte Tokens von Such- und KI-Crawlern und verwendet ergänzend eine Heuristik für bot/crawler/spider. Ein nicht aufgeführter oder getarnter Crawler kann trotzdem übersehen werden.",
  "pageText.28488b1d": "Kann ich mehrere User-Agent-Zeichenfolgen parsen?",
  "pageText.f540646b": "Ja. Aktivieren Sie den Stapelmodus und fügen Sie eine User-Agent-Zeichenfolge pro Zeile ein, um ein JSON-Array mit geparsten Ergebnissen zu erhalten.",
  "pageText.964b16b5": "Was dieser Online-User-Agent-Parser zurückgibt",
  "pageText.9d61821a": "Fügen Sie eine User-Agent-Zeichenfolge ein oder aktivieren Sie den Stapelmodus mit einer Zeichenfolge pro Zeile, um Browsername und -version, Betriebssystem, Rendering-Engine, Gerätehersteller, -modell und -typ, CPU-Architektur und bekannte Bot-Signale zu parsen. RFC 9110 definiert User-Agent als Anfragefeld mit Produktkennungen und optionalen Kommentaren über die Software, von der eine Anfrage stammt. Dieses Werkzeug liest diese selbst angegebenen Tokens. Es kontaktiert weder das Gerät noch untersucht es den Browser, der sie gesendet hat.",
  "pageText.32c1543c": "So funktioniert die Erkennung",
  "pageText.080c4d60": "Der mitgelieferte Regelsatz von UAParser.js 1.0.41 wendet seine Regex-Daten für Browser, Engine, Betriebssystem, Gerät und CPU im Browser an.",
  "pageText.c680aa0e": "Das Ergebnis zeigt Versionen sowie Gerätehersteller und -modell, wenn die eingefügte Zeichenfolge tatsächlich genügend Informationen enthält.",
  "pageText.954982d4": "Eine separate Bot-Erkennung erkennt benannte Tokens wie Googlebot, Bingbot, OAI-SearchBot, GPTBot, PerplexityBot, ClaudeBot und Applebot. Danach greift eine allgemeine Heuristik für Crawler-Schlüsselwörter.",
  "pageText.ddc447f4": "„Meinen User-Agent verwenden“ liest navigator.userAgent aus diesem Browser. Der Stapelmodus parst eine eingefügte Zeichenfolge pro Zeile.",
  "pageText.ef145930": "Genauigkeit und Einschränkungen",
  "pageText.1f7dae65": "Betrachten Sie jedes Ergebnis als Hinweis, nicht als bestätigte Identität. User-Agent-Zeichenfolgen lassen sich ändern oder fälschen. Kompatibilitätstokens können mehrere Browser nennen, und reduzierte Zeichenfolgen können Versionen oder Gerätedetails auslassen. Unbekannte Werte bleiben „Unbekannt“; eine nicht erkannte Zeichenfolge für ein nicht mobiles Gerät fällt auf „Desktop“ zurück. Auch die Bot-Erkennung ist heuristisch: Nicht aufgeführte oder getarnte Crawler können übersehen werden, und gewöhnliche Produktnamen mit einem Crawler-Schlüsselwort können eine Markierung auslösen. Client Hints und Funktionserkennung können andere oder nützlichere Signale liefern, wenn Sie die Anwendung kontrollieren.",
  "pageText.22aebc3c": "Datenschutz und sichere Verwendung",
  "pageText.2ae8ed4d": "Das Parsen erfolgt während der Eingabe in Ihrem Browser. Die Eingabe wird nicht an eine Parsing-API gesendet. User-Agent-Werte können jedoch zusammen mit anderen Daten zum Fingerprinting beitragen. Verwenden Sie diese Ausgabe nicht als Authentifizierung, Autorisierung, Betrugsnachweis oder Ersatz für Funktionserkennung.",
  "pageText.0381d4bc": "Welche Eingabeformate werden unterstützt?",
  "pageText.e1375844": "Geben Sie eine kanonische IPv4-Adresse in dezimaler Punktschreibweise sowie entweder ein Präfix wie /24 oder eine zusammenhängende Subnetzmaske wie 255.255.255.0 ein.",
  "pageText.245b4291": "Wie werden /31- und /32-Netzwerke behandelt?",
  "pageText.683e314e": "Ein /31 wird gemäß der Punkt-zu-Punkt-Auslegung aus RFC 3021 angezeigt: Beide Endpunkte sind nutzbar, und es gibt keine Broadcast-Adresse. Prüfen Sie, ob die Zielverbindung dies unterstützt. Ein /32 bezeichnet eine einzelne Hostroute und hat ebenfalls keine Broadcast-Adresse.",
  "pageText.c6d33e69": "Unterstützt dieser Rechner IPv6?",
  "pageText.a3da1f3e": "Nein. Diese Version prüft bewusst nur IPv4, damit die Bedeutung von Adressen und Hostbereichen eindeutig bleibt.",
  "pageText.790f8f4a": "Was der IPv4-CIDR-Rechner zurückgibt",
  "pageText.d1b4b69d": "CIDR verbindet eine IPv4-Adresse mit einer Präfixlänge, die angibt, wie viele führende Bits das Netzwerk identifizieren. Der Rechner normalisiert die eingegebene Adresse auf ihr kanonisches Netzwerk und zeigt dann die Broadcast-Grenze, Netzmaske in Punktschreibweise, inverse Wildcard-Maske, Gesamtzahl der Adressen und nutzbaren Hostbereich.",
  "pageText.1d5581a7": "Strenge Eingabeprüfung und Sonderfälle",
  "pageText.f2babb34": "IPv4-Eingaben müssen vier dezimale Oktette von 0 bis 255 enthalten. Mehrdeutige Formen mit führenden Nullen und Kurzformen werden abgewiesen.",
  "pageText.de8ed2ff": "Präfixlängen von /0 bis /32 sowie zusammenhängende Masken in dezimaler Punktschreibweise werden unterstützt.",
  "pageText.238148ff": "Für /0 bis /30 werden Netzwerk- und Broadcast-Grenzen vom nutzbaren Hostbereich ausgeschlossen.",
  "pageText.678c186b": "Bei /31 sind nach RFC 3021 beide Punkt-zu-Punkt-Endpunkte nutzbar. /32 bezeichnet eine einzelne Hostroute.",
  "pageText.08e319a3": "Grenzen im Betrieb",
  "pageText.16280f4e": "Das Ergebnis beschreibt Adressberechnungen, nicht die Erreichbarkeit über Routing, Firewall-Richtlinien, DHCP-Zuteilung, Reservierungen von Cloud-Anbietern, VLAN-Zugehörigkeit oder die öffentliche Routbarkeit einer Adresse. Wenden Sie die Regeln der Zielnetzwerkplattform an, bevor Sie Hosts zuweisen.",
  "pageText.43b9f352": "Was bedeuten 755 und 644?",
  "pageText.244efe25": "Jede Oktalziffer kombiniert Lesen (4), Schreiben (2) und Ausführen (1). Modus 755 entspricht rwxr-xr-x, 644 entspricht rw-r--r--.",
  "pageText.0a65a354": "Was sind setuid-, setgid- und Sticky-Bits?",
  "pageText.3c3c8484": "Dies sind besondere Modusbits, die durch eine führende Oktalziffer dargestellt werden. Ihre genaue Sicherheitswirkung hängt von Objekttyp, Betriebssystem, Dateisystem, Einhängeoptionen und Ausführungskontext ab.",
  "pageText.d9d32a1e": "Ändert dieses Werkzeug eine Datei?",
  "pageText.b0c7d669": "Nein. Es berechnet und kopiert nur Berechtigungsschreibweisen. Es kann nicht auf Ihr Dateisystem zugreifen oder es verändern.",
  "pageText.ad18866f": "So funktioniert der chmod-Rechner",
  "pageText.47cea64b": "Unix-Berechtigungsmodi gruppieren Lese-, Schreib- und Ausführungsbits für Eigentümer, Gruppe und andere. Die Summe der Bitwerte ergibt die jeweilige Oktalziffer: Lesen ist 4, Schreiben 2 und Ausführen 1. Der Rechner hält Oktal-, rwx- und Kontrollkästchendarstellung synchron.",
  "pageText.c281eef7": "Vermeiden Sie weitreichende Schreibberechtigungen wie 777, sofern das genaue Bedrohungsmodell und die Umgebung sie nicht erfordern.",
  "pageText.81ae01d1": "Ein Modus zeigt weder Dateieigentümer noch ACLs, Capabilities, SELinux- oder AppArmor-Regeln, Einhängeflags, Containerzuordnungen oder geerbte Richtlinien.",
  "pageText.a50e1c4a": "Ein großes S oder T bedeutet, dass das besondere Bit gesetzt ist, das zugehörige Ausführungsbit aber nicht.",
  "pageText.ba30cf48": "Prüfen Sie Zielpfad und Eigentümer, bevor Sie einen kopierten chmod-Befehl ausführen, insbesondere bei rekursiver Anwendung.",
  "pageText.57ae6fe2": "Was ist der Unterschied zwischen no-cache und no-store?",
  "pageText.856cc543": "no-cache erlaubt eine gespeicherte Antwort, verlangt aber vor der Wiederverwendung eine Validierung. no-store weist Caches an, die Antwort nicht zu speichern. Die beiden Werte sind nicht austauschbar.",
  "pageText.a24540f5": "Was steuert s-maxage?",
  "pageText.07c63451": "s-maxage legt die Frische für gemeinsam genutzte Caches fest und hat dort Vorrang vor max-age. Das Verhalten von Browsern und privaten Caches kann weiterhin abweichen.",
  "pageText.47165661": "Kann dieses Werkzeug das CDN-Verhalten garantieren?",
  "pageText.4736a111": "Nein. Es prüft die Syntax und markiert häufige Konflikte. Das tatsächliche Verhalten hängt jedoch von der vollständigen Antwort, Anfragedirektiven, Cache-Implementierung, CDN-Richtlinie, Framework-Voreinstellungen und dem Zustand der Invalidierung ab.",
  "pageText.ca31e679": "Was das Cache-Control-Werkzeug prüft",
  "pageText.7a512319": "Der Parser trennt kommagetrennte Direktiven, ohne Kommas in angeführten Werten zu trennen. Er vereinheitlicht Direktivnamen, entfernt doppelte Namen in der formatierten Ausgabe und warnt vor häufigen Konflikten, etwa public mit private oder nicht numerischen Frischewerten.",
  "pageText.be225eb9": "Einschränkungen im Betrieb",
  "pageText.cd535d5c": "Die Bedeutung von Cache-Control unterscheidet sich zwischen Anfragen und Antworten. Die Vorlagen sind Beispiele für Antworten.",
  "pageText.ae842969": "Ein gültiger Header setzt nicht jede CDN-Regel, jeden Surrogate-Header, Framework-Cache, Service Worker, jede Browserheuristik oder ausdrückliche Leerung außer Kraft.",
  "pageText.12ea33ca": "immutable eignet sich vor allem für versionierte Ressourcen, deren URL sich bei jeder Inhaltsänderung ändert.",
  "pageText.819756b2": "Speichern Sie personalisierte oder sensible Antworten nicht öffentlich im Cache, ohne Authentifizierung, Vary, Cookies und das Verhalten von Zwischenstellen vollständig zu prüfen.",
  "pageText.8fc53dd8": "Kann der Analyzer beweisen, dass eine CSP sicher ist?",
  "pageText.6bdde330": "Nein. Er markiert häufige statische Probleme, kann aber nicht jeden Anwendungsablauf, jedes Browserverhalten, jeden Nonce-Lebenszyklus, jede Drittanbieterintegration, jeden Meldeendpunkt oder jede Umgehungsmöglichkeit in der geschützten Anwendung verstehen.",
  "pageText.00ae173a": "Warum sollte ich mit dem Report-Only-Modus beginnen?",
  "pageText.487cd4a8": "Content-Security-Policy-Report-Only zeichnet Verstöße auf, ohne die Richtlinie durchzusetzen. Das hilft, vor der Durchsetzung benötigte Ressourcen zu identifizieren. Berichte müssen dennoch sorgfältig geprüft werden und können sensible URLs enthalten.",
  "pageText.1828ef21": "Was passiert mit doppelten Direktiven?",
  "pageText.b8228f81": "Browser verwenden das erste Vorkommen und ignorieren spätere doppelte Direktiven. Der Analyzer meldet Duplikate; die normalisierte Generatorausgabe behält eine ausdrücklich angegebene Direktive.",
  "pageText.18b89636": "Was der CSP-Generator prüft",
  "pageText.c8f0e194": "Content Security Policy beschränkt, von wo ein Dokument Ressourcen laden oder ausführen darf. Dieses Werkzeug parst durch Semikolons getrennte Direktiven, vereinheitlicht ihre Werte, erkennt Duplikate und markiert häufige Risiken wie weit gefasste Skriptquellen, data:-Skripte, 'unsafe-eval' oder 'unsafe-inline' ohne Nonce oder Hash.",
  "pageText.8bc2d491": "Grundlegende Direktiven und Befunde",
  "pageText.6a15b338": "default-src dient als Rückfallregel für Fetch-Direktiven, die nicht ausdrücklich deklariert sind.",
  "pageText.aa0c2e7c": "object-src 'none' blockiert Inhalte älterer Plugins, wenn die Anwendung sie nicht benötigt.",
  "pageText.18e827de": "base-uri beschränkt Änderungen an der Basis-URL des Dokuments. frame-ancestors steuert dagegen, welche übergeordneten Seiten es einbetten dürfen.",
  "pageText.4033496a": "Eine syntaktisch gültige Richtlinie kann trotzdem die Produktion beeinträchtigen oder einen unsicheren Ablauf erlauben. Prüfen Sie erforderliche Ursprünge, Nonces, Hashwerte, Worker, Frames, Formulare und Meldungen gesondert.",
  "pageText.190ec910": "Ablauf für eine sichere Bereitstellung",
  "pageText.ae9648e1": "Beginnen Sie mit einem Entwurf nach dem Prinzip minimaler Berechtigungen, stellen Sie ihn als Content-Security-Policy-Report-Only bereit, durchlaufen Sie echte Anwendungsabläufe und prüfen Sie Verstöße. Entfernen Sie unbeabsichtigte Abhängigkeiten oder ergänzen Sie die engsten erforderlichen Quellen. Setzen Sie anschließend die geprüfte Richtlinie durch. Verwalten Sie den Header in der Versionskontrolle und testen Sie ihn erneut, wenn sich Frameworks, CDNs, Analytik, Werbung oder Authentifizierungsabläufe ändern.",
  "pageText.d68c4d88": "Führt dieses Werkzeug den cURL-Befehl aus?",
  "pageText.74f4df78": "Nein. Es zerlegt nur unterstützte Eingaben in Tokens und erzeugt Text. Es startet niemals eine Shell, kontaktiert die Ziel-URL nicht und sendet weder Header noch Anfragetext.",
  "pageText.48e8b2e0": "Welche cURL-Optionen lassen sich umwandeln?",
  "pageText.2aedeaa5": "Der Konverter behandelt übliche Anfrageoptionen wie Methode, URL, Header und Daten sowie unbedenkliche Weiterleitungs- oder Komprimierungsflags. Nicht unterstützte oder mehrdeutige Shell-Funktionen werden abgewiesen, statt geraten.",
  "pageText.159eff58": "Sind cURL und fetch immer gleichwertig?",
  "pageText.dde74409": "Nein. Weiterleitungen, Cookies, TLS, Proxys, Komprimierung, Streaming, CORS, vom Browser verbotene Header, Zugangsdaten und Multipart-Uploads können sich unterschiedlich verhalten. Prüfen und testen Sie den erzeugten Code in seiner tatsächlichen Laufzeitumgebung.",
  "pageText.ec80b478": "Was der cURL- und Fetch-Konverter macht",
  "pageText.68449604": "Der Anfragegenerator wandelt strukturierte Eingaben zu Methode, URL, Abfrage, Headern und Anfragetext in einen cURL-Befehl mit POSIX-Shell-Maskierung und ein JavaScript-fetch-Beispiel um. Der Konverter zerlegt einen unterstützten eingefügten cURL-Befehl in Tokens, ohne ihn auszuführen, und bildet die Anfragedaten anschließend auf die fetch-Syntax ab.",
  "pageText.cee22a22": "Grenzen beim Parsen und bei der Sicherheit",
  "pageText.a46bfb45": "Shell-Ersetzungen, Backticks, NUL-Bytes, fehlerhafte Anführungszeichen, CRLF-Header-Injection und nicht unterstützte Optionen werden abgewiesen.",
  "pageText.a46b5014": "Sensible Authorization-, Cookie-, Proxy-Autorisierungs- und API-Schlüsselwerte lassen sich in der erzeugten Ausgabe schwärzen. In der Oberfläche ist diese Schwärzung standardmäßig aktiviert.",
  "pageText.b759e2e1": "POSIX-Shell-Maskierung unterscheidet sich von der Maskierung in PowerShell und Windows cmd. Prüfen Sie die Ziel-Shell, bevor Sie kopierten Text ausführen.",
  "pageText.d923e0c4": "Wiederholte Anfrageheader können von der Fetch-Headers-API zusammengeführt werden. Das erzeugte Codebeispiel weist auf doppelte Namen zur manuellen Prüfung hin.",
  "pageText.6518c723": "Das Werkzeug sendet keine Anfrage, prüft keinen entfernten Server, speichert keine Zugangsdaten und beweist nicht, dass kopierte Geheimnisse vor Erweiterungen, Seitenskripten, Zwischenablageverlauf oder Bildschirmfreigabe geschützt sind.",
  "pageText.a52cbc62": "Warum erzeugtes fetch Anpassungen benötigen kann",
  "pageText.a0b2fa3c": "Browser-fetch wendet CORS- und Regeln für verbotene Header an, die der curl-Kommandozeilenclient nicht verwendet. Serverseitiges JavaScript hat wiederum eine andere Umgebung für Cookies, Proxys und TLS. Multipart-Formularuploads, gestreamte Anfragetexte, Clientzertifikate, benutzerdefinierte DNS-Auflösung oder curl-spezifisches Wiederholungsverhalten erfordern laufzeitspezifischen Code über eine direkte Umwandlung hinaus.",
  "pageText.92e93e00": "Welche Kontrastverhältnisse verlangt WCAG für Text?",
  "pageText.71cfc9b4": "Für die meisten Texte verlangt AA mindestens 4,5:1 und AAA 7:1. Großer Text benötigt 3:1 für AA und 4,5:1 für AAA. Großer Text ist mindestens 18 Punkt normal oder 14 Punkt fett, häufig angenähert als 24 CSS-Pixel oder etwa 18,66 CSS-Pixel fett.",
  "pageText.76601b6f": "Was bedeutet das Ergebnis für UI-Komponenten?",
  "pageText.88ec1351": "Es verwendet den Schwellenwert 3:1, der häufig für visuelle Informationen erforderlich ist, um Benutzeroberflächenkomponenten und grafische Objekte zu erkennen. Die Anwendbarkeit hängt von Zustand, Begrenzungen, angrenzenden Farben und davon ab, ob die Darstellung zum Verstehen oder Bedienen der Oberfläche nötig ist.",
  "pageText.f6c937f8": "Macht ein ausreichendes Verhältnis das gesamte Design barrierefrei?",
  "pageText.c55058e2": "Nein. Kontrast ist eine Anforderung. Schriftstärke, Größe, Abstände, Hover- und Fokuszustände, Farbverläufe, Bilder, Unterschiede im Farbsehen, Zoom, erzwungene Farben und die Vermittlung von Informationen ohne Farbe müssen alle gesondert getestet werden.",
  "pageText.bd34b3a3": "So wird das Kontrastverhältnis berechnet",
  "pageText.93057296": "Jeder deckende sRGB-Kanal wird von seinem codierten Wert in lineares Licht umgewandelt, mit den WCAG-Koeffizienten für relative Leuchtdichte kombiniert und als (heller + 0,05) / (dunkler + 0,05) verglichen. Das Verhältnis reicht von 1:1 bei gleicher Leuchtdichte bis 21:1 für Schwarz und Weiß. Das Vertauschen von Vorder- und Hintergrund ändert den Zahlenwert nicht.",
  "pageText.587b353d": "AA, AAA und Live-Vorschau",
  "pageText.a7a29b7f": "Normaler Text erfüllt AA ab 4,5:1 und AAA ab 7:1.",
  "pageText.4a22824d": "Großer Text erfüllt AA ab 3:1 und AAA ab 4,5:1.",
  "pageText.6232d70c": "Das UI-Beispiel zeigt den Nicht-Text-Schwellenwert 3:1, ohne anzunehmen, dass jede sichtbare Begrenzung ihn erfüllen muss.",
  "pageText.25adca33": "Der Vorschlag wählt aus deckendem Schwarz und Weiß die Farbe mit dem höheren Verhältnis zum aktuellen Hintergrund. Die Absicht des Markendesigns bleibt dabei nicht erhalten.",
  "pageText.3543a31e": "Die Live-Vorschau hilft beim Erkennen offensichtlicher Lesbarkeitsprobleme, ersetzt aber keine Tests des gerenderten Produkts in seinen tatsächlichen Größen und Zuständen.",
  "pageText.1aad56b9": "Grenzen von Farben und Darstellung",
  "pageText.e945b142": "Der Rechner akzeptiert deckende sRGB-Farben mit drei oder sechs Hexadezimalstellen. Alphatransparenz, Farbverläufe, Bilder, Mischmodi, Bildschirmkalibrierung, Kantenglättung, Farben mit erweitertem Farbumfang und Text über wechselndem Inhalt erfordern die Prüfung der endgültig zusammengesetzten Pixel. Die Verarbeitung erfolgt lokal und erfasst keine andere Webseite automatisch.",
  "pageText.23984f68": "Welche OpenAPI-Versionen werden unterstützt?",
  "pageText.a8bb0e10": "Der Strukturanalyzer akzeptiert Versionszeichenfolgen für OpenAPI 3.0, 3.1 und 3.2. Swagger 2.0 wird als nicht unterstützt gemeldet, statt stillschweigend umgewandelt.",
  "pageText.052ac5a9": "Werden externe $ref-Dokumente heruntergeladen?",
  "pageText.a9423d78": "Nein. Lokale Fragmentverweise, die mit # beginnen, werden innerhalb des eingefügten Dokuments aufgelöst. Datei- und Netzwerkverweise werden als Warnungen aufgeführt, aber nie abgerufen. So bleibt die Analyse lokal und vermeidet versteckte Netzwerkzugriffe.",
  "pageText.0aa9d75d": "Garantiert ein gültiges Ergebnis vollständige OpenAPI-Konformität?",
  "pageText.66286acc": "Nein. Dies ist ein gezielter Strukturanalyzer, der nicht das offizielle Schema samt sämtlichen semantischen Regeln abdeckt. Verwenden Sie vor der Veröffentlichung eines API-Vertrags einen versionsspezifischen Validator und den Zielgenerator oder das Zielgateway in CI.",
  "pageText.df996466": "Was der Strukturvalidator prüft",
  "pageText.4c230715": "Der Parser akzeptiert JSON oder begrenzte YAML-Eingaben, verlangt eine OpenAPI-3-Version, Titel und Version in info sowie ein paths-Objekt und erfasst anschließend die standardmäßigen HTTP-Operationen. Er meldet fehlende Antworten, doppelte Operations-IDs, nicht zugeordnete oder optionale Pfadvorlagenparameter, ungewöhnliche Antwortschlüssel, nicht aufgelöste lokale Verweise, nicht unterstützte Wurzelversionen und unbekannte Path-Item-Felder.",
  "pageText.c33b24c7": "So fasst der Endpunkt-Explorer den Vertrag zusammen",
  "pageText.bd67021b": "Jede Zeile zeigt Methode, Pfad, Zusammenfassung, operationId, Antwortschlüssel, Veraltungsstatus und wirksamen Sicherheitsstatus.",
  "pageText.af6d9ec9": "Sicherheit auf Operationsebene überschreibt die Sicherheit auf Wurzelebene. Ein leeres security-Array wird als ausdrücklich öffentlich angezeigt.",
  "pageText.f6c0ea2a": "Die Suche erfasst Pfad, Zusammenfassung, operationId und Tags. Die Methodenauswahl schränkt die sichtbare Operationsliste ein.",
  "pageText.f6b3cb96": "Die normalisierte JSON-Ansicht macht YAML-Parsing-Ergebnisse und zusammengeführte Aliase zur Prüfung sichtbar.",
  "pageText.39b0dc9b": "Externe Verweise werden gezählt und gemeldet, ohne dass der Browser eine Anfrage sendet.",
  "pageText.477e1f43": "Grenzen von Validierung und Sicherheit",
  "pageText.aa9a6db6": "Ein strukturell gültiges Dokument kann weiterhin inkompatible Schemas, ungültige Beispiele, fehlerhafte Callbacks, falsche Medientypen, generatorspezifische Erweiterungen, nicht nutzbare Authentifizierungsabläufe oder fachliches Verhalten enthalten, das nicht zur Implementierung passt. Die lokale $ref-Auflösung prüft die Existenz, dereferenziert aber nicht jeden semantischen Kontext vollständig. YAML-Tiefe, Aliase, Merge-Erweiterungen und Gesamteingabegröße sind begrenzt, damit der Browser reaktionsfähig bleibt.",
  "pageText.e8aa500a": "Was ist SPF, und warum wird es benötigt?",
  "pageText.3a448f2b": "SPF (Sender Policy Framework) ist ein DNS-TXT-Eintrag, der autorisierte Mailserver auflistet, die im Namen Ihrer Domain E-Mails senden dürfen.",
  "pageText.101baaa1": "Was ist DMARC?",
  "pageText.5c6e3f51": "DMARC (Domain-based Message Authentication, Reporting, and Conformance) verwendet SPF und DKIM, um empfangenden Servern vorzugeben, wie sie E-Mails mit fehlgeschlagener Authentifizierung behandeln sollen.",
  "pageText.db14ea51": "Welche Programmiersprachen und HTTP-Bibliotheken werden unterstützt?",
  "pageText.cd3899b9": "Das Werkzeug erzeugt Code für JavaScript (Fetch-API und Axios), Python (Requests-Bibliothek), Go (Standardbibliothek net/http), PHP (curl_init) und Rust (reqwest async).",
  "pageText.7db0a8b2": "Führt das Werkzeug meine cURL-Anfrage aus oder sendet sie über das Internet?",
  "pageText.95abcd54": "Nein. Der Befehl wird vollständig lokal in Ihrem Browser geparst und in Tokens zerlegt, um Code zu erzeugen. Es wird nichts gesendet oder ausgeführt.",
  "pageText.125a50e9": "Was ist ein mehrstufiger Docker-Build?",
  "pageText.7a608e37": "Mehrstufige Builds verwenden getrennte Zwischencontainer für die Kompilierung und die Produktionslaufzeit. Dadurch werden die endgültigen Images erheblich kleiner, und Build-Abhängigkeiten gelangen nicht in die Produktion.",
  "pageText.c322990e": "Verwendet das erzeugte Dockerfile einen Benutzer ohne Root-Rechte?",
  "pageText.585c03a7": "Ja. Wo sinnvoll, konfiguriert das erzeugte Dockerfile einen eigenen Benutzer ohne Root-Rechte, etwa USER node oder appuser, entsprechend bewährten Verfahren für Containersicherheit.",
  "pageText.4adfa17f": "Welche CSS-Eigenschaften erzeugen den Glassmorphismus-Effekt?",
  "pageText.cb13b4db": "Glassmorphismus entsteht durch backdrop-filter: blur(), einen halbtransparenten Hintergrund (rgba), dezente weiße Ränder (rgba) und box-shadow für einen Eindruck von Höhe.",
  "pageText.78f35ba1": "Wird backdrop-filter in allen modernen Browsern unterstützt?",
  "pageText.afdcf83f": "Ja. backdrop-filter wird in allen modernen Browsern unterstützt: Chrome, Edge, Safari und Firefox. Herstellerpräfixe wie -webkit-backdrop-filter werden für größtmögliche Kompatibilität ergänzt.",
  "pageText.a0d9ac95": "Welche Einheiten kann ich für Spalten und Zeilen verwenden?",
  "pageText.0d74534d": "Sie können flexible Bruchteilseinheiten (fr), genaue Pixelmaße (px) oder Prozentwerte (%) für ein möglichst anpassungsfähiges Layout konfigurieren.",
  "pageText.85a4a549": "Kann ich sowohl CSS als auch HTML kopieren?",
  "pageText.349f7349": "Ja. Das CSS des .parent-Containers mit grid-template-columns und die passende HTML-Struktur werden gleichzeitig erzeugt.",
  "pageText.db476089": "Wozu dient robots.txt?",
  "pageText.c4e38da5": "Eine robots.txt-Datei weist Suchmaschinen-Crawler wie Googlebot und Bingbot an, auf welche URLs und Verzeichnisse Ihrer Website sie zugreifen dürfen und auf welche nicht.",
  "pageText.8f3b1cb2": "Wo sollte die robots.txt-Datei liegen?",
  "pageText.f8c6a14d": "Die robots.txt-Datei muss immer auf der Wurzelebene Ihrer Website-Domain liegen, etwa https://example.com/robots.txt.",
  "pageText.dadb2232": "Welche Tags enthält das erzeugte Sitemap-XML?",
  "pageText.0acc8ea9": "Das erzeugte XML entspricht dem Schema sitemaps.org 0.9 und enthält die Elemente <url>, <loc>, <lastmod>, <changefreq> und <priority>.",
  "pageText.972e9d03": "Wie reiche ich es in der Google Search Console ein?",
  "pageText.6bb374e1": "Laden Sie die erzeugte sitemap.xml herunter, laden Sie sie in das Wurzelverzeichnis Ihrer Website (https://example.com/sitemap.xml) hoch und reichen Sie die URL in der Google Search Console ein.",
  "pageText.912a6605": "Was ist der Unterschied zwischen event.key und event.code?",
  "pageText.5f3e9043": "event.key liefert den Wert der gedrückten Taste unter Berücksichtigung von Umschalt- und Feststelltaste, etwa \"A\" oder \"a\". event.code bezeichnet dagegen die physische Taste im Tastaturlayout, etwa \"KeyA\".",
  "pageText.d6886318": "Warum ist keyCode in modernem JavaScript veraltet?",
  "pageText.47c83a7e": "event.keyCode war zwischen Betriebssystemen und Nicht-QWERTY-Layouts uneinheitlich. Die moderne Webentwicklung verwendet standardmäßig event.key und event.code.",
  "pageText.44aec8dc": "Wie funktionieren reine CSS-Dreiecke?",
  "pageText.178348f0": "CSS-Dreiecke entstehen, indem ein Element Breite und Höhe 0 erhält und dicke Ränder verwendet, von denen drei transparent sind und einer farbig ist.",
  "pageText.4e5692e9": "Kann ich diagonale Eckdreiecke erzeugen?",
  "pageText.0633b12d": "Ja. Sie können aus 8 Richtungen wählen: oben, unten, links, rechts, oben links, oben rechts, unten links und unten rechts.",
  "pageText.376bbf44": "Liefert dieser Generator sowohl reines CSS als auch Tailwind-Klassen?",
  "pageText.59dce7df": "Ja. Standard-CSS-Regeln wie display: flex, justify-content, align-items und gap sowie Tailwind-Hilfsklassen werden in Echtzeit erzeugt.",
  "pageText.99e78b69": "Kann ich Test-Flex-Elemente in der Sandbox hinzufügen oder entfernen?",
  "pageText.b824b684": "Ja. Mit den Schaltflächen + und - ändern Sie die Anzahl der Testkarten im Container, um das Verhalten von Umbrüchen und Abständen zu sehen.",
  "pageText.b1a93891": "Welche sozialen Plattformen simuliert die Vorschau?",
  "pageText.c1f4071a": "Sie können zwischen Ansichten für Twitter/X Large Image Card, Facebook-Feedbeitrag, LinkedIn-Linkfreigabe und Google-Suchergebnisvorschau wechseln.",
  "pageText.fb1820cd": "Welche Open-Graph-Bildauflösung wird empfohlen?",
  "pageText.da87fb9a": "Die übliche empfohlene Bildgröße für Twitter Cards und Facebook Open Graph ist 1200 × 630 Pixel bei einem Seitenverhältnis von 1,91:1.",
  "pageText.5141dfd9": "Welche Animationsvorlagen stehen zur Verfügung?",
  "pageText.1033cd43": "Die Vorlagen umfassen Hüpfen, Pulsieren, Drehen, Schütteln, Einblenden, 3D-Umdrehen, Wackeln und Heranzoomen.",
  "pageText.96e7dd99": "Kann ich die Zeitfunktion (Easing) anpassen?",
  "pageText.0aa29a50": "Ja. Sie können zwischen ease, linear, ease-in, ease-out und ease-in-out wählen und außerdem Dauer und Verzögerung in Sekunden anpassen.",
  "pageText.2c0cc2c1": "Kann ich dem Text mehrere Schattenebenen hinzufügen?",
  "pageText.8175f838": "Ja. Sie können beliebig viele übereinanderliegende text-shadow-Ebenen hinzufügen, um realistische 3D-Tiefe, mehrfarbige Retro-Konturen oder mehrstufiges Neonleuchten zu erzeugen.",
  "pageText.9ec3072a": "Gibt es sofort nutzbare Stilvorlagen?",
  "pageText.9e6ee7e1": "Ja. Zu den Vorlagen mit einem Klick zählen „Weicher Schlagschatten“, „Neonleuchten“, „3D-Extrusion“ und „Retro-Kontur“.",
  "pageText.deb09314": "Welche Informationen liefert der Subnetzrechner?",
  "pageText.6e09390f": "Er berechnet Netzwerkadresse, Broadcast-Adresse, Subnetzmaske, Wildcard-Maske, erste und letzte nutzbare Host-IP, Gesamtzahl und nutzbare Anzahl von Hosts, IP-Klasse und 32-Bit-Binärdarstellungen.",
  "pageText.f6fb6409": "Unterstützt er alle CIDR-Präfixe von /0 bis /32?",
  "pageText.eb723f55": "Ja. Alle Subnetzpräfixe von /0 bis /32 werden unterstützt, einschließlich besonderer /31-Punkt-zu-Punkt-Verbindungen nach RFC 3021 und einzelner /32-Hostmasken.",
  "pageText.7c278231": "Welche CSS-Filterfunktionen werden unterstützt?",
  "pageText.3027f78d": "Unterstützt werden blur(), brightness(), contrast(), grayscale(), hue-rotate(), invert(), saturate(), sepia() und opacity().",
  "pageText.2666dde6": "Enthält das erzeugte CSS Herstellerpräfixe?",
  "pageText.45bdde19": "Ja. Für größtmögliche browserübergreifende Kompatibilität werden sowohl die Standard-Eigenschaft `filter` als auch `-webkit-filter` ausgegeben.",
  "pageText.4f32f1e3": "Wie funktioniert die CSS-border-radius-Syntax mit 8 Werten?",
  "pageText.c08c1dc8": "Der Schrägstrich (/) trennt horizontale von vertikalen Radien: `border-radius: [TL-h] [TR-h] [BR-h] [BL-h] / [TL-v] [TR-v] [BR-v] [BL-v]`. So entstehen glatte organische Kurven, die nicht kreisförmig sind.",
  "pageText.8ed31f5b": "Kann ich zwischen Prozent- (%) und Pixeleinheiten (px) wählen?",
  "pageText.974f8f3e": "Ja. Wechseln Sie mit dem Einheitenschalter im Einstellungsbereich zwischen % und px.",
  "pageText.aff2e0e9": "Welche Authentifizierungsmethoden werden unterstützt?",
  "pageText.33b1ea50": "Unterstützt werden Bearer-Tokens (`-H \"Authorization: Bearer ...\"`) und Basic-Authentifizierung (`-u \"user:pass\"`).",
  "pageText.f1fe0990": "Werden Sonderzeichen und einfache Anführungszeichen sicher maskiert?",
  "pageText.cacf393b": "Ja. JSON-Anfragetexte und Header-Zeichenfolgen werden korrekt maskiert, um Shell-Syntaxfehler in bash- und zsh-Terminals zu vermeiden.",
  "pageText.5785e598": "Welche Oberflächenformen stehen zur Verfügung?",
  "pageText.7e6f4277": "Unterstützt werden flache, eingedrückte (innerer Schatten), konkave (nach innen gewölbter Verlauf) und konvexe (umgekehrt gewölbter Verlauf) Oberflächen.",
  "pageText.9f1d34df": "Wie werden doppelte Schatten berechnet?",
  "pageText.b74d0389": "Der Generator berechnet anhand Ihrer Grundfarbe und Intensitätseinstellungen automatisch die ergänzende Hervorhebung auf der Lichtseite und den Schlagschatten auf der dunklen Seite.",
  "pageText.65e43540": "Wie funktionieren CSS-Mesh-Farbverläufe ohne Canvas oder SVG?",
  "pageText.19ca56b9": "Mehrere übereinanderliegende `radial-gradient()`-Positionen werden auf einem einfarbigen Hintergrund mit Backdrop-/Filter-Weichzeichnungseffekten überblendet, um sehr schnelles GPU-Rendering zu ermöglichen.",
  "pageText.49cc9737": "Kann ich mehrere Farbknoten hinzufügen oder neu positionieren?",
  "pageText.f51bb3c6": "Ja. Sie können bis zu 6 eigene Farbknoten hinzufügen und ihre X-/Y-Koordinaten unabhängig von 0 % bis 100 % festlegen.",
  "pageText.51b04c8d": "Welche Formen sind vorkonfiguriert?",
  "pageText.f8a18c44": "Enthalten sind Dreiecke, Trapeze, Parallelogramme, Rauten, Fünfecke, Sechsecke, Sterne und Sprechblasen für Nachrichten.",
  "pageText.27ea598c": "Unterstützt das Werkzeug Firefox und moderne Chromium-Browser?",
  "pageText.a550ba24": "Ja. Es erzeugt sowohl moderne Standards (`scrollbar-color` und `scrollbar-width`) als auch `::-webkit-scrollbar`-Herstellerregeln für umfassende Browserunterstützung.",
  "pageText.c0a0fbb0": "Sind Bilddateien zur Darstellung dieser Muster erforderlich?",
  "pageText.da49a542": "Nein. Alle Muster werden mit reinen CSS-Funktionen `radial-gradient` und `linear-gradient` erzeugt.",
  "pageText.3349cc09": "Kann ich unverarbeitete <path>-HTML-Tags einfügen?",
  "pageText.bc6be089": "Ja. Das Werkzeug extrahiert automatisch das Attribut `d=\"...\"` aus unverarbeiteten SVG-Tags.",
  "pageText.b5c8f73b": "Was ist der Unterschied zwischen ^ und ~ in npm?",
  "pageText.5e52dc36": "`^1.2.3` erlaubt Aktualisierungen, die die erste von links gelesene Ziffer ungleich null nicht ändern (< 2.0.0). `~1.2.3` erlaubt dagegen nur Änderungen auf Patch-Ebene (< 1.3.0).",
  "pageText.0e286eaf": "Was ist das übliche Subnetzpräfix für lokale IPv6-Netzwerke?",
  "pageText.aa2aad9c": "Nach RFC 4291 ist /64 die übliche Subnetzgröße für lokale IPv6-Netzwerksegmente.",
  "pageText.58ddddc2": "Aus welchen Feldern besteht ein fünfteiliger Cron-Ausdruck?",
  "pageText.09710cdd": "Minute (0–59), Stunde (0–23), Tag des Monats (1–31), Monat (1–12) und Wochentag (0–6, Sonntag = 0).",
  "pageText.d3c9a849": "Warum ist SPF für Domain-E-Mails wichtig?",
  "pageText.61b98659": "SPF (Sender Policy Framework) verhindert, dass Spammer unautorisierte E-Mails mit gefälschtem Domainnamen versenden, und schützt damit den Ruf Ihrer Domain und die Zustellbarkeit Ihrer E-Mails."
};
